INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C1','sci',5,1,'u1',1,'발굴 체험 — 투명한 그릇에 흙을 담고 물을 조금씩 넣으며 숟가락으로 섞음 → 흙이 뭉치면 작은 블록 몇 개를 보이지 않게 숨기고 윗부분을 눌러 단단하게 함 → 그릇을 친구와 바꾸어 끌과 작은 붓으로 찾음 → 찾은 블록에 묻은 흙을 작은 붓으로 살살 털어 냄 · 묻힌 것은 겉에서 보이지 않음',ARRAY['여러 가지 지층을 관찰하여 지층의 특징을 설명하고, 지층이 만들어지는 과정을 모형으로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C2','sci',5,1,'u1',1,'발굴 도구 — 플라스틱 끌(굳은 흙을 조금씩 밀어 파냄, 세게 내리치면 안의 것이 깨짐), 작은 붓(찾아낸 것에 묻은 흙을 털어 냄, 마지막 단계), 숟가락(흙과 물을 섞고 옮겨 담음, 준비 단계), 보안경·면장갑(튀는 흙에서 눈 보호, 손 보호) · 마스크·실험복 · 흙 만진 손으로 눈·얼굴을 만지지 않고 활동 뒤 손 씻기 · 뛰어다니지 않기',ARRAY['여러 가지 지층을 관찰하여 지층의 특징을 설명하고, 지층이 만들어지는 과정을 모형으로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C3','sci',5,1,'u1',1,'땅속의 화석 — 박물관의 공룡 뼈는 땅속에 묻혀 있던 것을 과학자가 오랜 시간 조심스럽게 파낸 것 · 땅속에서 공룡 뼈·조개·나뭇잎·공룡 발자국 같은 화석이 나옴 · 서두르면 깨지거나 부서져 정보를 잃으므로 빠르기보다 조심스러움이 중요 · 땅속에서 나온 것이 모두 화석은 아님(플라스틱 장난감·유리병 조각)',ARRAY['여러 가지 화석을 관찰하여 화석이 만들어지는 과정을 모형으로 설명하고, 화석으로 과거 생물과 환경을 추리하여 화석의 가치를 앎(문구 초안 — 성취기준 코드 W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C4','sci',5,1,'u1',2,'지층 — 자갈·모래·진흙 같은 퇴적물이 쌓여 층을 이룬 것 · 무지개떡·샌드위치처럼 여러 층이 위아래로 겹친 모습 · 산비탈·바닷가 절벽·도로 옆 깎인 땅·계곡의 벼랑처럼 땅속이 겉으로 드러난 곳에서 볼 수 있음',ARRAY['여러 가지 지층을 관찰하여 지층의 특징을 설명하고, 지층이 만들어지는 과정을 모형으로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C5','sci',5,1,'u1',2,'지층의 공통점 — 여러 층으로 이루어져 줄무늬가 보임 · 두꺼운 층과 얇은 층이 있어 층마다 두께가 다름 · 밝은 층과 어두운 층이 있어 층마다 색깔이 다름 · 층마다 쌓인 퇴적물의 종류가 달라서 색깔이 다름(사람이 칠한 것·햇빛·바람 때문이 아님)',ARRAY['여러 가지 지층을 관찰하여 지층의 특징을 설명하고, 지층이 만들어지는 과정을 모형으로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C6','sci',5,1,'u1',2,'지층의 모양 — 수평인 지층(층이 나란히 평평하게 이어짐, 가장 흔함, 경상남도 고성군), 휘어진 지층(층이 물결처럼 구부러짐, 평평하던 층이 나중에 휘어짐, 전북특별자치도 군산시), 끊어진 지층(층이 도중에 끊겨 어긋남, 끊어진 자리에서 위아래로 밀림, 전라남도 여수시) · 지층의 모양은 한 가지가 아니라 다양함',ARRAY['여러 가지 지층을 관찰하여 지층의 특징을 설명하고, 지층이 만들어지는 과정을 모형으로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C7','sci',5,1,'u1',2,'지층 카드 관찰 — 실험관찰의 지층 카드를 뜯어냄 → 지층의 모양·층의 두께·색깔을 하나씩 관찰해 적음 → 층의 줄무늬를 따라 유성펜으로 선을 그어 모양을 뚜렷하게 봄 → 모양에 따라 수평·휘어진·끊어진 지층으로 분류 · 눈으로 관찰할 수 있는 것은 두께·색깔·모양이고 땅속의 온도·소리는 관찰할 수 없음',ARRAY['여러 가지 지층을 관찰하여 지층의 특징을 설명하고, 지층이 만들어지는 과정을 모형으로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C8','sci',5,1,'u1',3,'지층 모형 — 투명한 사각 통에 물을 4분의 1 정도 부음 → 투명한 컵 세 개에 자갈과 모래·모래·진흙을 절반 정도 채움 → 각 컵의 재료가 잠기도록 물을 부음 → 넣을 순서를 정해 정한 순서대로 사각 통에 부음 · 먼저 부은 것이 맨 아래에 깔림 · 실험복·실험용 장갑, 재료 만진 손으로 눈·얼굴을 만지지 않기, 실험 뒤 주변 정리와 안내에 따른 재료 처리',ARRAY['여러 가지 지층을 관찰하여 지층의 특징을 설명하고, 지층이 만들어지는 과정을 모형으로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C9','sci',5,1,'u1',3,'지층이 만들어지는 과정 — ① 흐르는 물이 운반한 자갈·모래·진흙이 바다나 호수 밑바닥에 쌓임 ② 그 위에 계속 쌓여 먼저 쌓인 것이 무게에 눌리고 알갱이 사이가 좁아짐 ③ 오랜 시간이 지나 단단하게 굳어져 지층이 됨 ④ 지층이 땅 위로 드러나 깎이면 우리가 볼 수 있음 · 쌓이는 재료와 차례는 그때그때 다름',ARRAY['여러 가지 지층을 관찰하여 지층의 특징을 설명하고, 지층이 만들어지는 과정을 모형으로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C10','sci',5,1,'u1',3,'층의 차례 — 돌탑의 맨 아래 돌이 가장 먼저 놓인 돌인 것처럼, 지층에서 아래에 있는 층이 위에 있는 층보다 먼저 쌓인 더 오래된 층 · 맨 위 층이 가장 나중에 쌓인 층',ARRAY['여러 가지 지층을 관찰하여 지층의 특징을 설명하고, 지층이 만들어지는 과정을 모형으로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C11','sci',5,1,'u1',3,'모형과 실제 — 공통점: 여러 층이 생기고 층마다 두께·색깔이 다름 · 차이점: 모형은 몇 분이면 만들어지고 손으로 쉽게 흩뜨릴 수 있지만 실제 지층은 아주 오랜 시간 눌리고 굳어져 단단함 · 모형 속 물은 자연에서 흐르는 물처럼 자갈·모래·진흙을 운반해 한곳에 쌓아 줌',ARRAY['여러 가지 지층을 관찰하여 지층의 특징을 설명하고, 지층이 만들어지는 과정을 모형으로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C12','sci',5,1,'u1',4,'퇴적암 — 퇴적물이 굳어져 만들어진 암석 · 지층은 퇴적암으로 이루어져 있음 · 층마다 쌓인 알갱이가 달라 색깔과 두께도 다름 · 강정이 쌀알·콩처럼 알갱이 크기가 다르듯 암석도 알갱이를 살펴봄',ARRAY['지층이 퇴적암으로 이루어져 있음을 알고, 퇴적암을 알갱이의 크기에 따라 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C13','sci',5,1,'u1',4,'퇴적암 분류 — 기준은 암석을 이루는 알갱이의 크기(색깔·무게·발견 지역이 아님) · 이암: 주로 진흙이나 갯벌의 흙, 알갱이가 매우 작음(경상북도 포항시) · 사암: 주로 모래, 진흙보다 알갱이가 큼(경상북도 포항시) · 역암: 자갈에 모래나 진흙이 섞임, 알갱이가 가장 큼(전북특별자치도 부안군) · 이암 → 사암 → 역암 순으로 알갱이가 커짐',ARRAY['지층이 퇴적암으로 이루어져 있음을 알고, 퇴적암을 알갱이의 크기에 따라 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C14','sci',5,1,'u1',4,'퇴적암 관찰 — 흰 종이에 퇴적암 표본 여섯 개를 올리고 번호 붙임딱지를 붙임 → 표면을 손으로 만져 느낌을 봄(거칠거칠한 것·매끈한 것) → 돋보기로 색깔과 알갱이의 크기를 관찰 → 알갱이가 작은 것·중간인 것·큰 것으로 분류 · 실험복·면장갑, 암석 만진 손으로 눈·얼굴을 만지지 않기, 암석끼리 부딪치거나 떨어뜨리지 않기, 맛보지 않기',ARRAY['지층이 퇴적암으로 이루어져 있음을 알고, 퇴적암을 알갱이의 크기에 따라 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C15','sci',5,1,'u1',4,'퇴적암이 만들어지는 과정 — ① 퇴적물이 쌓임 ② 눌리면서 알갱이 사이의 공간이 좁아짐 ③ 물에 녹은 물질이 알갱이를 엉겨 붙게 함 → 오랜 시간 뒤 단단한 암석 · 손으로 모래를 세게 쥐어도 단단해지지 않는 까닭은 오랜 시간 눌리고 엉겨 붙는 과정이 없기 때문(불에 굽는 것이 아님)',ARRAY['지층이 퇴적암으로 이루어져 있음을 알고, 퇴적암을 알갱이의 크기에 따라 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C16','sci',5,1,'u1',5,'화석 — 옛날에 살았던 생물의 몸체나 흔적이 지층 속에 남아 있는 것 · 몸체: 뼈·껍데기·잎 · 흔적: 발자국·배설물·알 자국처럼 생물이 생활한 흔적도 화석이 될 수 있음',ARRAY['여러 가지 화석을 관찰하여 화석이 만들어지는 과정을 모형으로 설명하고, 화석으로 과거 생물과 환경을 추리하여 화석의 가치를 앎(문구 초안 — 성취기준 코드 W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C17','sci',5,1,'u1',5,'여러 가지 화석 — 동물 화석(삼엽충은 마디가 많은 벌레처럼, 물고기는 뼈와 지느러미, 암모나이트는 둥글게 말린 모양), 식물 화석(나뭇잎은 잎맥, 고사리는 갈라진 잎 모양, 솔방울은 오톨도톨한 겉모습), 흔적 화석(공룡 발자국은 발가락 자국, 새 발자국은 작고 발가락이 펼쳐짐, 공룡알은 달걀처럼 생겨 여러 개가 모임) · 맨눈으로 보이지 않을 만큼 작은 화석부터 거대한 공룡 뼈까지 종류와 크기가 다양함 · 관찰 순서: 흰 종이에 표본 → 돋보기로 모양·크기·무늬 → 몸체인지 흔적인지 → 가상 현실(VR) 자료 찾아 공유 · 안전: 표본 만진 손으로 눈·얼굴 만지지 않기, 떨어뜨리지 않기, 기기에서 열이 나면 멈추고 알리기, VR 중 어지러우면 바로 알리고 쉬기',ARRAY['여러 가지 화석을 관찰하여 화석이 만들어지는 과정을 모형으로 설명하고, 화석으로 과거 생물과 환경을 추리하여 화석의 가치를 앎(문구 초안 — 성취기준 코드 W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C18','sci',5,1,'u1',5,'화석과 암석 — 화성암은 뜨거운 것이 식어 굳은 암석, 퇴적암은 퇴적물이 쌓여 굳은 암석 · 퇴적물이 쌓일 때 그 속의 생물이 함께 묻혀 굳어지므로 화석은 주로 퇴적암에서 발견됨',ARRAY['여러 가지 화석을 관찰하여 화석이 만들어지는 과정을 모형으로 설명하고, 화석으로 과거 생물과 환경을 추리하여 화석의 가치를 앎(문구 초안 — 성취기준 코드 W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C19','sci',5,1,'u1',6,'화석 모형 — 투명한 그릇에 비닐봉지를 펼치고 찰흙을 평평하게 폄 → 찰흙 위에 조개껍데기를 눌렀다 뗌 → 자국이 모두 덮이도록 물을 부음 → 물 표면이 보이지 않을 정도로 석고 가루를 넣음 → 석고가 굳으면 비닐봉지를 들어 올려 꺼냄 → 찰흙과 석고를 떼어 내어 관찰 · 찰흙 = 퇴적물이 쌓여 흔적이 남는 곳, 조개껍데기 = 옛날에 살았던 생물, 물과 석고 가루 = 흔적 위에 쌓이는 퇴적물, 굳은 석고 속 모형 = 지층 속 화석 · 모형은 몇 분, 실제는 아주 오랜 시간 · 석고 가루는 선생님의 안내에 따르고 실험복·보안경·실험용 장갑, 쓰고 난 것은 안내에 따라 처리',ARRAY['여러 가지 화석을 관찰하여 화석이 만들어지는 과정을 모형으로 설명하고, 화석으로 과거 생물과 환경을 추리하여 화석의 가치를 앎(문구 초안 — 성취기준 코드 W7 확인)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C20','sci',5,1,'u1',6,'화석이 만들어지는 과정 — 생물의 몸체나 흔적이 바다나 호수에 가라앉음 → 그 위로 퇴적물이 빠르게 쌓임(빠르게 덮여야 그대로 남음) → 오랜 시간 쌓인 퇴적물이 굳어져 지층이 되고 그 속의 생물은 화석이 됨 → 물 밖으로 드러난 지층이 깎이며 화석이 발견됨 · 뼈·이빨·껍데기처럼 단단한 부분, 줄기·잎처럼 질긴 부분이 있으면 화석이 되기 쉬움 · 생물이 죽는다고 모두 화석이 되는 것은 아님 · 벌레가 기어간 자국이나 공룡 발자국도 무른 진흙·모래에 찍힌 뒤 퇴적물이 빠르게 덮어 굳어진 것',ARRAY['여러 가지 화석을 관찰하여 화석이 만들어지는 과정을 모형으로 설명하고, 화석으로 과거 생물과 환경을 추리하여 화석의 가치를 앎(문구 초안 — 성취기준 코드 W7 확인)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C21','sci',5,1,'u1',7,'과거 생물 추리 — 공룡 발자국 화석의 크기로 몸집을, 발자국 사이의 간격으로 걸음을 짐작해 공룡의 크기나 움직임을 알 수 있음 · 공룡알 화석으로 공룡이 알을 낳았고 그곳이 알을 낳던 곳이었음을 알 수 있음 · 몸 색깔·울음소리·태어난 날짜 같은 것은 화석으로 알기 어려움',ARRAY['여러 가지 화석을 관찰하여 화석이 만들어지는 과정을 모형으로 설명하고, 화석으로 과거 생물과 환경을 추리하여 화석의 가치를 앎(문구 초안 — 성취기준 코드 W7 확인)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C22','sci',5,1,'u1',7,'과거 환경 추리 — 화석이 된 생물과 비슷한 오늘날의 생물이 사는 곳을 살펴 그 지역의 과거 환경을 추리 · 오늘날 산호는 따뜻하고 깊이가 얕은 바다에 사므로 산호 화석이 나온 곳은 과거에 따뜻하고 깊이가 얕은 바다 · 고사리는 습기가 많은 곳에서 자라므로 고사리 화석이 나온 곳은 과거에 따뜻하고 습기가 많은 육지 · 같은 지역도 옛날에는 오늘날과 달랐을 수 있음 · 지층이 쌓인 당시의 환경을 알려 줌',ARRAY['여러 가지 화석을 관찰하여 화석이 만들어지는 과정을 모형으로 설명하고, 화석으로 과거 생물과 환경을 추리하여 화석의 가치를 앎(문구 초안 — 성취기준 코드 W7 확인)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C23','sci',5,1,'u1',7,'화석의 가치 — 화석은 과거 지구에 관한 많은 정보를 알려 주는 소중한 자료 · 자연사 박물관: 공룡 모형과 화석 표본 전시, 전시 해설사의 자세한 설명, 화석 모형 만들기·가상 체험 · 화석 산지: 화석이 많이 발견되는 곳, 우리나라는 주로 강가나 바닷가 지층, 탐방로를 따라 실제 화석 관찰, 옛 생물과 당시 환경을 알 수 있어 생태계 연구에 중요한 자료 · 우리나라 여러 지역에서 공룡 발자국·공룡알 화석이 많이 발견됨',ARRAY['여러 가지 화석을 관찰하여 화석이 만들어지는 과정을 모형으로 설명하고, 화석으로 과거 생물과 환경을 추리하여 화석의 가치를 앎(문구 초안 — 성취기준 코드 W7 확인)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C24','sci',5,1,'u1',8,'관광 지도 만들기 — 지층과 화석을 본 경험 이야기 → 모둠별로 지층과 화석 가운데 하나를 정하고 소개할 내용 정하기 → 필요한 역할 정하기 → 스마트 기기로 조사(올바른 정보인지 확인하고 출처 밝히기) → 소개 글을 써서 지도로 된 공유 게시판에 올리기 → 다른 모둠 지도에 칭찬 댓글, 더 알아보고 싶은 내용 이야기 · 바르고 고운 말, 어려워하는 친구 돕기, 기기에서 열이 나면 멈추고 알리기 · 지층과 화석을 소중히 보전하고 가져오지 않기',ARRAY['여러 가지 화석을 관찰하여 화석이 만들어지는 과정을 모형으로 설명하고, 화석으로 과거 생물과 환경을 추리하여 화석의 가치를 앎(문구 초안 — 성취기준 코드 W7 확인)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C25','sci',5,1,'u1',8,'우리나라의 지층과 화석 — 특히 바닷가에서 여러 모습의 지층과 공룡 발자국 화석이 많이 발견됨 · 전북특별자치도 부안군 채석강(여러 겹으로 쌓인 지층) · 경상남도 고성군 상족암(공룡 발자국 화석, 지층과 화석을 함께) · 경상남도 진주시 가진리(새 발자국 화석, 화석 산지) · 경기도 화성시 고정리(공룡알 화석, 화석 산지)',ARRAY['여러 가지 화석을 관찰하여 화석이 만들어지는 과정을 모형으로 설명하고, 화석으로 과거 생물과 환경을 추리하여 화석의 가치를 앎(문구 초안 — 성취기준 코드 W7 확인)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-1-u1-C26','sci',5,1,'u1',8,'땅속 조사 — 구멍을 파면서 땅속 물질을 채집해 지층의 상태를 조사 · 탄성파 탐사(진동을 보내 되돌아온 신호 분석) · 바닷속은 음파로 지층 구조를 파악(직접 들어가 파기 어려운 깊은 곳까지) · 인공위성·무인 항공기가 촬영한 화면으로 넓은 범위를 효율적으로 · 지구의 과거 모습을 이해하고 지속가능한 지구를 만들기 위해 지층을 조사하고 연구함',ARRAY['여러 가지 화석을 관찰하여 화석이 만들어지는 과정을 모형으로 설명하고, 화석으로 과거 생물과 환경을 추리하여 화석의 가치를 앎(문구 초안 — 성취기준 코드 W7 확인)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X01','sci',5,'u1',ARRAY['SC5-1-u1-C1','SC5-1-u1-C3']::text[],'발굴은 빠르고 세게 할수록 좋다고 여긴다(쇠망치로 내리치기, 흙덩이를 바닥에 내리치기, 두 손으로 부수기 등)','조금씩, 조심스럽게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X02','sci',5,'u1',ARRAY['SC5-1-u1-C2']::text[],'끌·붓·숟가락·보안경의 쓰임을 서로 바꾸어 안다','파내기 · 털어 내기 · 섞기 · 보호') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X03','sci',5,'u1',ARRAY['SC5-1-u1-C2']::text[],'발굴 활동의 안전 수칙을 잘못 안다(흙 묻은 손으로 눈 비비기, 뛰어다니기, 손 씻지 않기 등)','눈·얼굴 만지지 않고 손 씻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X04','sci',5,'u1',ARRAY['SC5-1-u1-C3']::text[],'땅속에서 나온 것은 모두 화석이라고 여긴다(플라스틱 장난감, 깨진 유리병 조각 등)','옛 생물의 몸체나 흔적인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X05','sci',5,'u1',ARRAY['SC5-1-u1-C4']::text[],'지층을 퇴적물이 쌓인 것이 아닌 다른 것으로 여긴다(뜨거운 물질이 굳은 산, 사람이 만든 것, 땅속의 물 등)','퇴적물이 쌓여 층을 이룬 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X06','sci',5,'u1',ARRAY['SC5-1-u1-C5']::text[],'지층의 모든 층은 두께와 색깔이 똑같다고 여긴다','두꺼운 층, 얇은 층, 밝은 층, 어두운 층') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X07','sci',5,'u1',ARRAY['SC5-1-u1-C5']::text[],'지층의 줄무늬나 층마다 다른 색깔이 사람이 칠했거나 햇빛·바람·온도 때문이라고 여긴다','쌓인 퇴적물이 달라서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X08','sci',5,'u1',ARRAY['SC5-1-u1-C6']::text[],'지층은 언제나 수평이거나 모양이 한 가지뿐이라고 여긴다','수평·휘어진·끊어진') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X09','sci',5,'u1',ARRAY['SC5-1-u1-C6','SC5-1-u1-C7']::text[],'휘어진 지층과 끊어진 지층, 수평인 지층의 모습을 서로 바꾸어 안다','구부러짐과 어긋남') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X10','sci',5,'u1',ARRAY['SC5-1-u1-C7']::text[],'지층 카드로 땅속의 온도나 소리처럼 볼 수 없는 것도 관찰할 수 있다고 여기거나, 관찰 순서를 잘못 안다','모양·두께·색깔을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X11','sci',5,'u1',ARRAY['SC5-1-u1-C8']::text[],'지층 모형 만들기의 방법이나 안전을 잘못 안다(재료를 물 없이 붓기, 순서를 정하지 않기, 재료 만진 손으로 눈 만지기, 남은 재료를 아무 데나 버리기 등)','물에 잠기게 · 정한 순서대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X12','sci',5,'u1',ARRAY['SC5-1-u1-C10']::text[],'지층에서 맨 위 층이 가장 먼저 쌓인 층이라고 여긴다','돌탑의 맨 아래 돌') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X13','sci',5,'u1',ARRAY['SC5-1-u1-C9','SC5-1-u1-C11']::text[],'실제 지층도 모형처럼 몇 분이나 하루 만에 금방 만들어진다고 여긴다','아주 오랜 시간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X14','sci',5,'u1',ARRAY['SC5-1-u1-C9','SC5-1-u1-C11']::text[],'실제 지층이 단단한 까닭을 불에 구워지거나 얼어붙었거나 사람이 붙였기 때문이라고 여긴다','오랜 시간 눌리고 굳어져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X15','sci',5,'u1',ARRAY['SC5-1-u1-C11']::text[],'지층 모형 속 물이 층에 색을 입히거나 층을 단단하게 한다고 여긴다','흐르는 물처럼 운반해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X16','sci',5,'u1',ARRAY['SC5-1-u1-C9']::text[],'지층이 만들어지는 차례를 뒤바꾼다(굳어진 뒤에 쌓인다, 드러나 깎인 뒤에 쌓인다 등)','쌓임 → 눌림 → 굳어짐 → 드러남') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X17','sci',5,'u1',ARRAY['SC5-1-u1-C9']::text[],'자갈·모래·진흙은 언제나 같은 차례로 쌓인다고 여긴다','쌓이는 차례는 그때그때 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X18','sci',5,'u1',ARRAY['SC5-1-u1-C13']::text[],'퇴적암을 색깔·무게·발견된 지역으로 분류한다고 여긴다','알갱이의 크기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X19','sci',5,'u1',ARRAY['SC5-1-u1-C13']::text[],'이암·사암·역암의 알갱이 크기를 뒤바꾼다(역암이 가장 작다, 사암이 가장 작다 등)','이암 → 사암 → 역암 순으로 커져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X20','sci',5,'u1',ARRAY['SC5-1-u1-C13']::text[],'색깔이 같으면 같은 암석이라고 여긴다','알갱이를 돋보기로 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X21','sci',5,'u1',ARRAY['SC5-1-u1-C15']::text[],'퇴적암이 불에 구워지거나 하루 만에 만들어진다고 여긴다','눌리고 엉겨 붙어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X22','sci',5,'u1',ARRAY['SC5-1-u1-C15']::text[],'모래를 세게 쥐어도 단단해지지 않는 까닭을 손힘이 약하거나 모래가 차갑기 때문이라고 여긴다','오랜 시간과 엉겨 붙는 과정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X23','sci',5,'u1',ARRAY['SC5-1-u1-C14']::text[],'퇴적암 관찰의 방법이나 안전을 잘못 안다(암석을 맛보기, 부딪쳐 보기, 번호를 붙이지 않기 등)','번호 · 손 느낌 · 돋보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X24','sci',5,'u1',ARRAY['SC5-1-u1-C12']::text[],'지층과 퇴적암을 관계없는 것으로 여긴다(지층은 퇴적암이 아닌 암석으로 이루어진다 등)','지층은 퇴적암으로 이루어져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X25','sci',5,'u1',ARRAY['SC5-1-u1-C16']::text[],'생물의 몸체만 화석이 되고, 발자국·배설물 같은 흔적은 화석이 아니라고 여긴다','흔적도 화석이 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X26','sci',5,'u1',ARRAY['SC5-1-u1-C17']::text[],'공룡처럼 큰 동물만 화석이 되거나, 화석은 모두 맨눈에 잘 보일 만큼 크다고 여긴다','종류와 크기가 다양해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X27','sci',5,'u1',ARRAY['SC5-1-u1-C17']::text[],'식물은 화석이 될 수 없다고 여기거나, 동물 화석과 식물 화석을 바꾸어 가른다','잎맥·고사리·솔방울') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X28','sci',5,'u1',ARRAY['SC5-1-u1-C17']::text[],'화석 관찰의 안전을 잘못 안다(표본을 깨뜨려 속 보기, 가상 현실이 어지러워도 참기 등)','어지러우면 바로 알려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X29','sci',5,'u1',ARRAY['SC5-1-u1-C18']::text[],'화석이 뜨거운 것이 식어 굳은 암석(화성암)에서 주로 발견된다고 여긴다','퇴적물과 함께 묻혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X30','sci',5,'u1',ARRAY['SC5-1-u1-C19']::text[],'화석 모형 만들기의 차례나 재료의 짝을 잘못 안다(찰흙을 불에 굽기, 석고를 먼저 넣기, 조개껍데기를 퇴적물로 보기 등)','찰흙 → 조개 → 물 → 석고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X31','sci',5,'u1',ARRAY['SC5-1-u1-C19','SC5-1-u1-C20']::text[],'실제 화석도 모형처럼 몇 분이나 며칠 만에 만들어진다고 여긴다','발견되기까지 아주 오랜 시간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X32','sci',5,'u1',ARRAY['SC5-1-u1-C20']::text[],'생물이 죽으면 모두 화석이 된다고 여기거나, 퇴적물이 천천히 쌓여도 그대로 남는다고 여긴다','빠르게 덮여야 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X33','sci',5,'u1',ARRAY['SC5-1-u1-C20']::text[],'말랑말랑한 살처럼 물렁한 부분이 화석으로 잘 남는다고 여긴다','단단하거나 질긴 부분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X34','sci',5,'u1',ARRAY['SC5-1-u1-C20']::text[],'지층 속 화석이 발견되는 까닭을 모른다(지층이 드러나 깎이는 일 없이 그냥 보인다고 여기기 등)','드러나 깎여서 발견돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X35','sci',5,'u1',ARRAY['SC5-1-u1-C21']::text[],'발자국·알 화석으로 공룡의 몸 색깔·울음소리·태어난 날짜까지 알 수 있다고 여긴다','크기와 움직임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X36','sci',5,'u1',ARRAY['SC5-1-u1-C22']::text[],'산호 화석과 고사리 화석이 알려 주는 과거 환경을 뒤바꾸거나 잘못 안다(산호 = 춥고 깊은 바다, 고사리 = 바다 등)','산호는 얕은 바다, 고사리는 습한 육지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X37','sci',5,'u1',ARRAY['SC5-1-u1-C22']::text[],'화석은 오늘날의 환경만 알려 주거나, 한 지역의 환경은 옛날에도 지금과 같았다고 여긴다','같은 곳도 옛날엔 달랐어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X38','sci',5,'u1',ARRAY['SC5-1-u1-C23']::text[],'자연사 박물관과 화석 산지에서 하는 일을 바꾸어 알거나, 화석의 가치를 모른다','전시와 해설 · 탐방로와 연구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X39','sci',5,'u1',ARRAY['SC5-1-u1-C23','SC5-1-u1-C24']::text[],'멋진 화석을 발견하면 집에 가져가도 된다고 여긴다','소중히 보전해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X40','sci',5,'u1',ARRAY['SC5-1-u1-C24']::text[],'조사하고 나누는 태도를 잘못 안다(출처 없이 옮기기, 확인하지 않기, 장난스러운 댓글, 혼자만 하기 등)','확인 · 출처 · 고운 말 · 협력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X41','sci',5,'u1',ARRAY['SC5-1-u1-C25']::text[],'우리나라의 장소와 그곳에서 볼 수 있는 지층·화석을 바꾸어 짝짓는다','채석강·상족암·가진리·고정리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X42','sci',5,'u1',ARRAY['SC5-1-u1-C25']::text[],'우리나라에서는 지층과 화석을 볼 수 없거나, 주로 도시 한가운데에서 발견된다고 여긴다','바닷가에서 많이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X43','sci',5,'u1',ARRAY['SC5-1-u1-C26']::text[],'땅속은 직접 파야만 조사할 수 있다고 여기거나, 조사 방법과 하는 일을 바꾸어 안다','진동 · 음파 · 인공위성') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-1-u1-X44','sci',5,'u1',ARRAY['SC5-1-u1-C20','SC5-1-u1-C21']::text[],'단단한 암석에 공룡 발자국이 찍힌 까닭을 공룡의 힘이 아주 세거나 사람이 새겼기 때문이라고 여긴다','그때는 무른 진흙이었어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_basic#1','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C2',1,'mc','auto','단단하게 굳은 흙 속에서 블록을 파낼 때 알맞은 도구는 어느 것인가요?',ARRAY['SC5-1-u1-X01','SC5-1-u1-X02']::text[],false,'{"seq":1,"concept":"SC5-1-u1-C2","difficulty":1,"kind":"mc","stem":"단단하게 굳은 흙 속에서 블록을 파낼 때 알맞은 도구는 어느 것인가요?","options":[{"t":"플라스틱 끌","correct":true},{"t":"쇠망치","mis":"SC5-1-u1-X01"},{"t":"작은 붓","mis":"SC5-1-u1-X02"},{"t":"물뿌리개","mis":"SC5-1-u1-X02"}],"explanation":["굳은 흙을 파내요.","끝을 대고 조금씩 밀어요.","플라스틱 끌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_basic#2','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C2',1,'mc','auto','찾아낸 블록에 묻은 흙은 무엇으로 털어 내나요?',ARRAY['SC5-1-u1-X02','SC5-1-u1-X01']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C2","difficulty":1,"kind":"mc","stem":"찾아낸 블록에 묻은 흙은 무엇으로 털어 내나요?","options":[{"t":"작은 붓","correct":true},{"t":"끌 끝","mis":"SC5-1-u1-X02"},{"t":"젖은 수세미","mis":"SC5-1-u1-X01"},{"t":"입김","mis":"SC5-1-u1-X01"}],"explanation":["마지막 단계예요.","살살 털어 내요.","작은 붓이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_basic#3','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C2',1,'ox','auto','흙을 만진 손으로 눈이나 얼굴을 만지지 않아요.',ARRAY['SC5-1-u1-X03']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C2","difficulty":1,"kind":"ox","stem":"흙을 만진 손으로 눈이나 얼굴을 만지지 않아요.","answer":"O","reason_options":[{"t":"흙이 눈에 들어가거나 얼굴이 더러워질 수 있기 때문에","correct":true},{"t":"흙은 깨끗해서 상관없지만 규칙이라서","mis":"SC5-1-u1-X03"}],"mis":"SC5-1-u1-X03","explanation":["안전을 떠올려요.","흙이 눈에 들어갈 수 있어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_basic#4','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C3',1,'sa','auto','「옛날에 살았던 생물의 몸체나 흔적이 땅속에 남은 것을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u1-C3","difficulty":1,"kind":"sa","stem":"「옛날에 살았던 생물의 몸체나 흔적이 땅속에 남은 것을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["화석"],"explanation":["공룡 뼈를 떠올려요.","땅속에서 나와요.","화석이에요."],"mis":"SC5-1-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_basic#5','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C2',2,'match','auto','도구와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u1-C2","difficulty":2,"kind":"match","stem":"도구와 하는 일을 알맞게 이으세요.","pairs":[{"l":"플라스틱 끌","r":"굳은 흙을 조금씩 파낸다"},{"l":"작은 붓","r":"묻은 흙을 털어 낸다"},{"l":"숟가락","r":"흙과 물을 섞는다"},{"l":"보안경","r":"튀는 흙에서 눈을 보호한다"}],"mis":"SC5-1-u1-X02","explanation":["도구를 하나씩 떠올려요.","파내기·털기·섞기·보호예요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_basic#6','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C1',2,'mc','auto','숨겨진 블록을 찾는 활동에서 블록을 숨긴 다음 할 일은 어느 것인가요?',ARRAY['SC5-1-u1-X01']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C1","difficulty":2,"kind":"mc","stem":"숨겨진 블록을 찾는 활동에서 블록을 숨긴 다음 할 일은 어느 것인가요?","options":[{"t":"흙이 단단해지도록 윗부분을 누른다","correct":true},{"t":"흙을 바닥에 쏟아 블록을 바로 꺼낸다","mis":"SC5-1-u1-X01"},{"t":"블록이 잘 보이게 위에 올려 둔다","mis":"SC5-1-u1-X01"},{"t":"그릇에 물을 가득 부어 흙을 씻어 낸다","mis":"SC5-1-u1-X01"}],"explanation":["보이지 않게 숨겼어요.","흙을 단단하게 해요.","윗부분을 눌러요."],"asset":{"type":"passage","lines":["① 투명한 그릇에 흙을 담고 물을 조금씩 넣으며 숟가락으로 섞는다.","② 흙이 뭉치면 작은 블록 몇 개를 보이지 않게 숨기고 윗부분을 누른다.","③ 그릇을 친구와 바꾸어 끌과 작은 붓으로 숨긴 블록을 찾는다.","④ 찾은 블록에 묻은 흙을 작은 붓으로 살살 털어 낸다."],"title":"숨겨진 블록을 찾아라!"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_basic#7','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C1',2,'ox','auto','블록을 찾을 때는 빨리 찾으려고 흙덩이를 바닥에 내리쳐도 돼요.',ARRAY['SC5-1-u1-X01']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C1","difficulty":2,"kind":"ox","stem":"블록을 찾을 때는 빨리 찾으려고 흙덩이를 바닥에 내리쳐도 돼요.","answer":"X","reason_options":[{"t":"서두르면 안에 있는 것이 깨지거나 부서질 수 있기 때문에","correct":true},{"t":"흙덩이를 내리치면 블록이 더 잘 보이기 때문에","mis":"SC5-1-u1-X01"}],"mis":"SC5-1-u1-X01","explanation":["발굴은 어떻게 하나요?","조심스럽게 조금씩 해요.","내리치지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_basic#8','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C3',2,'mc','auto','땅속에서 나온 것 가운데 화석인 것은 어느 것인가요?',ARRAY['SC5-1-u1-X04']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C3","difficulty":2,"kind":"mc","stem":"땅속에서 나온 것 가운데 화석인 것은 어느 것인가요?","options":[{"t":"돌에 남은 조개 모양","correct":true},{"t":"플라스틱 장난감","mis":"SC5-1-u1-X04"},{"t":"깨진 유리병 조각","mis":"SC5-1-u1-X04"},{"t":"땅에 떨어진 동전","mis":"SC5-1-u1-X04"}],"explanation":["옛 생물과 관계있나요?","조개는 생물이에요.","돌에 남은 조개 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_basic#9','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C2',2,'error','auto','활동하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X03','SC5-1-u1-X02']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C2","difficulty":2,"kind":"error","stem":"활동하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「블록을 빨리 찾으려면 뛰어다니면서 찾아야 해.」","correct":true,"mis_target":"SC5-1-u1-X03"},{"t":"나은 — 「활동이 끝나면 손을 씻자.」","mis":"SC5-1-u1-X03"},{"t":"시우 — 「마스크와 보안경을 쓰고 하자.」","mis":"SC5-1-u1-X02"}],"explanation":["안전을 떠올려요.","뛰면 다칠 수 있어요.","준서가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_basic#10','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C3',3,'mc','auto','과학자가 땅속의 화석을 아주 천천히 파내는 까닭은 어느 것인가요?',ARRAY['SC5-1-u1-X01','SC5-1-u1-X04']::text[],false,'{"seq":10,"concept":"SC5-1-u1-C3","difficulty":3,"kind":"mc","stem":"과학자가 땅속의 화석을 아주 천천히 파내는 까닭은 어느 것인가요?","options":[{"t":"서두르면 화석이 깨져 정보를 잃을 수 있기 때문에","correct":true},{"t":"정해진 시간을 채워야 하기 때문에","mis":"SC5-1-u1-X01"},{"t":"화석은 빠르게 파낼수록 더 잘 보이기 때문에","mis":"SC5-1-u1-X01"},{"t":"땅속에서 나온 것은 모두 화석이라 다 꺼내야 하기 때문에","mis":"SC5-1-u1-X04"}],"explanation":["깨지면 어떻게 될까요?","정보를 잃어요.","조심스러움이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_challenge#1','sci',5,1,'u1','L01','g5_1_sci_u1_L01_challenge','lesson_challenge','SC5-1-u1-C1',2,'sa','auto','「땅속에 묻힌 것을 조심스럽게 파내어 찾아내는 일을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u1-C1","difficulty":2,"kind":"sa","stem":"「땅속에 묻힌 것을 조심스럽게 파내어 찾아내는 일을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["발굴"],"explanation":["과학자가 하는 일이에요.","파내어 찾아요.","발굴이에요."],"mis":"SC5-1-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_challenge#2','sci',5,1,'u1','L01','g5_1_sci_u1_L01_challenge','lesson_challenge','SC5-1-u1-C1',2,'mc','auto','활동 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X01']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C1","difficulty":2,"kind":"mc","stem":"활동 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"흙과 물 섞기 → 블록 숨기고 누르기 → 그릇 바꾸어 찾기 → 붓으로 흙 털기","correct":true},{"t":"블록 숨기고 누르기 → 흙과 물 섞기 → 붓으로 흙 털기 → 그릇 바꾸어 찾기","mis":"SC5-1-u1-X01"},{"t":"그릇 바꾸어 찾기 → 흙과 물 섞기 → 블록 숨기고 누르기 → 붓으로 흙 털기","mis":"SC5-1-u1-X01"},{"t":"흙과 물 섞기 → 그릇 바꾸어 찾기 → 블록 숨기고 누르기 → 붓으로 흙 털기","mis":"SC5-1-u1-X01"}],"explanation":["먼저 흙을 준비해요.","숨긴 다음 찾아요.","마지막에 털어요."],"asset":{"type":"passage","lines":["① 투명한 그릇에 흙을 담고 물을 조금씩 넣으며 숟가락으로 섞는다.","② 흙이 뭉치면 작은 블록 몇 개를 보이지 않게 숨기고 윗부분을 누른다.","③ 그릇을 친구와 바꾸어 끌과 작은 붓으로 숨긴 블록을 찾는다.","④ 찾은 블록에 묻은 흙을 작은 붓으로 살살 털어 낸다."],"title":"숨겨진 블록을 찾아라!"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_challenge#3','sci',5,1,'u1','L01','g5_1_sci_u1_L01_challenge','lesson_challenge','SC5-1-u1-C2',3,'mc','auto','숟가락을 쓰는 때로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X02','SC5-1-u1-X01']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C2","difficulty":3,"kind":"mc","stem":"숟가락을 쓰는 때로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"발굴을 준비하며 흙과 물을 섞을 때","correct":true},{"t":"찾아낸 블록의 흙을 털어 낼 때","mis":"SC5-1-u1-X02"},{"t":"굳은 흙을 세게 내리쳐 부술 때","mis":"SC5-1-u1-X01"},{"t":"튀는 흙에서 눈을 보호할 때","mis":"SC5-1-u1-X02"}],"explanation":["숟가락은 언제 썼나요?","준비 단계예요.","흙과 물을 섞어요."],"asset":{"type":"passage","lines":["① 투명한 그릇에 흙을 담고 물을 조금씩 넣으며 숟가락으로 섞는다.","② 흙이 뭉치면 작은 블록 몇 개를 보이지 않게 숨기고 윗부분을 누른다.","③ 그릇을 친구와 바꾸어 끌과 작은 붓으로 숨긴 블록을 찾는다.","④ 찾은 블록에 묻은 흙을 작은 붓으로 살살 털어 낸다."],"title":"숨겨진 블록을 찾아라!"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_challenge#4','sci',5,1,'u1','L01','g5_1_sci_u1_L01_challenge','lesson_challenge','SC5-1-u1-C3',3,'error','auto','발굴에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X04','SC5-1-u1-X01']::text[],false,'{"seq":4,"concept":"SC5-1-u1-C3","difficulty":3,"kind":"error","stem":"발굴에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「땅속에서 나온 것은 무엇이든 다 화석이야.」","correct":true,"mis_target":"SC5-1-u1-X04"},{"t":"도현 — 「공룡 발자국도 땅속에서 화석으로 나와.」","mis":"SC5-1-u1-X04"},{"t":"은채 — 「묻힌 것은 겉에서 보이지 않아.」","mis":"SC5-1-u1-X01"}],"explanation":["화석이 무엇인지 떠올려요.","유리병 조각은 화석일까요?","하윤이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_challenge#5','sci',5,1,'u1','L01','g5_1_sci_u1_L01_challenge','lesson_challenge','SC5-1-u1-C1',3,'ox','auto','블록을 다 찾은 뒤에 끌로 블록 표면을 세게 긁어 흙을 없애요.',ARRAY['SC5-1-u1-X02']::text[],false,'{"seq":5,"concept":"SC5-1-u1-C1","difficulty":3,"kind":"ox","stem":"블록을 다 찾은 뒤에 끌로 블록 표면을 세게 긁어 흙을 없애요.","answer":"X","reason_options":[{"t":"표면이 상할 수 있으니 작은 붓으로 살살 털어 내야 하기 때문에","correct":true},{"t":"끌은 흙을 섞을 때 쓰는 도구이기 때문에","mis":"SC5-1-u1-X02"}],"mis":"SC5-1-u1-X02","explanation":["마지막 단계의 도구예요.","표면을 지켜요.","붓으로 털어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_challenge#6','sci',5,1,'u1','L01','g5_1_sci_u1_L01_challenge','lesson_challenge','SC5-1-u1-C3',3,'match','auto','땅속에서 나온 것을 화석과 화석이 아닌 것으로 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC5-1-u1-C3","difficulty":3,"kind":"match","stem":"땅속에서 나온 것을 화석과 화석이 아닌 것으로 알맞게 이으세요.","pairs":[{"l":"돌에 찍힌 공룡 발자국","r":"옛 생물의 흔적이 남은 화석"},{"l":"돌에 남은 나뭇잎 모양","r":"옛 생물의 몸체가 남은 화석"},{"l":"흙 속의 플라스틱 장난감","r":"사람이 만든 물건이라 화석이 아님"}],"mis":"SC5-1-u1-X04","explanation":["옛 생물과 관계있나요?","발자국은 흔적이에요.","장난감은 화석이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_challenge#7','sci',5,1,'u1','L01','g5_1_sci_u1_L01_challenge','lesson_challenge','SC5-1-u1-C2',3,'mc','auto','보안경과 면장갑을 끼는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X01','SC5-1-u1-X02']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C2","difficulty":3,"kind":"mc","stem":"보안경과 면장갑을 끼는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"튀는 흙에서 눈을 보호하고 손이 다치거나 더러워지는 것을 막기 위해","correct":true},{"t":"블록을 더 빨리 찾기 위해","mis":"SC5-1-u1-X01"},{"t":"흙과 물을 잘 섞기 위해","mis":"SC5-1-u1-X02"},{"t":"찾은 블록의 흙을 털어 내기 위해","mis":"SC5-1-u1-X02"}],"explanation":["무엇을 보호하나요?","눈과 손이에요.","안전을 위해 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_challenge#8','sci',5,1,'u1','L01','g5_1_sci_u1_L01_challenge','lesson_challenge','SC5-1-u1-C3',4,'mc','auto','박물관의 공룡 뼈 화석이 처음부터 그 모습으로 있었던 것이 아니라면, 가장 알맞은 설명은 어느 것인가요?',ARRAY['SC5-1-u1-X04','SC5-1-u1-X01']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C3","difficulty":4,"kind":"mc","stem":"박물관의 공룡 뼈 화석이 처음부터 그 모습으로 있었던 것이 아니라면, 가장 알맞은 설명은 어느 것인가요?","options":[{"t":"땅속 깊이 묻혀 있던 것을 과학자들이 오랜 시간에 걸쳐 조심스럽게 파낸 것이다","correct":true},{"t":"과학자가 공룡 뼈를 보고 흙으로 빚어 만든 것이다","mis":"SC5-1-u1-X04"},{"t":"땅속에서 빠르게 파낼수록 온전한 모습으로 꺼낼 수 있다","mis":"SC5-1-u1-X01"},{"t":"땅 위에 놓여 있던 것을 그대로 옮겨 온 것이다","mis":"SC5-1-u1-X01"}],"explanation":["발굴을 떠올려요.","오랜 시간 조심스럽게 했어요.","땅속에서 파낸 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_challenge#9','sci',5,1,'u1','L01','g5_1_sci_u1_L01_challenge','lesson_challenge','SC5-1-u1-C2',4,'mc','auto','친구가 블록을 찾다가 흙이 튀어 눈을 비비려고 해요. 가장 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u1-X03','SC5-1-u1-X01']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C2","difficulty":4,"kind":"mc","stem":"친구가 블록을 찾다가 흙이 튀어 눈을 비비려고 해요. 가장 알맞은 말은 어느 것인가요?","options":[{"t":"흙 묻은 손으로 눈을 비비지 말고 선생님께 바로 알리자","correct":true},{"t":"조금 비비면 금방 괜찮아질 거야","mis":"SC5-1-u1-X03"},{"t":"얼른 다시 블록을 찾고 나서 생각하자","mis":"SC5-1-u1-X01"},{"t":"흙을 끌로 더 세게 파면 튀지 않아","mis":"SC5-1-u1-X01"}],"explanation":["눈은 소중해요.","흙 묻은 손이에요.","비비지 말고 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L01_challenge#10','sci',5,1,'u1','L01','g5_1_sci_u1_L01_challenge','lesson_challenge','SC5-1-u1-C3',4,'essay','teacher','숨겨진 블록을 찾는 활동을 과학자의 화석 발굴과 견주어, 두 가지가 비슷한 점을 쓰고 화석을 발굴할 때 가장 중요한 것과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u1-C3","difficulty":4,"kind":"essay","stem":"숨겨진 블록을 찾는 활동을 과학자의 화석 발굴과 견주어, 두 가지가 비슷한 점을 쓰고 화석을 발굴할 때 가장 중요한 것과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 블록이 흙 속에 묻혀 겉에서 보이지 않는 것처럼 화석도 땅속에 묻혀 있어서 겉에서 보이지 않는다. 블록을 끌로 조금씩 파내고 붓으로 흙을 털어 낸 것처럼 과학자도 알맞은 도구로 화석을 파낸다. 화석을 발굴할 때 가장 중요한 것은 빠르기가 아니라 조심스러움이다. 서두르면 화석이 깨지거나 부서져 화석이 알려 주는 정보를 잃기 때문이다.","scoring_points":["비슷한 점을 썼는가","조심스러움이 가장 중요하다고 썼는가","깨져 정보를 잃는다는 까닭을 썼는가"]},"explanation":["두 활동을 견줘요.","무엇이 가장 중요한가요?","까닭을 써요."],"asset":{"type":"passage","lines":["① 투명한 그릇에 흙을 담고 물을 조금씩 넣으며 숟가락으로 섞는다.","② 흙이 뭉치면 작은 블록 몇 개를 보이지 않게 숨기고 윗부분을 누른다.","③ 그릇을 친구와 바꾸어 끌과 작은 붓으로 숨긴 블록을 찾는다.","④ 찾은 블록에 묻은 흙을 작은 붓으로 살살 털어 낸다."],"title":"숨겨진 블록을 찾아라!"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_basic#1','sci',5,1,'u1','L02','g5_1_sci_u1_L02_basic','lesson_basic','SC5-1-u1-C4',1,'mc','auto','지층이란 무엇인가요?',ARRAY['SC5-1-u1-X05']::text[],false,'{"seq":1,"concept":"SC5-1-u1-C4","difficulty":1,"kind":"mc","stem":"지층이란 무엇인가요?","options":[{"t":"자갈·모래·진흙 같은 퇴적물이 쌓여 층을 이룬 것","correct":true},{"t":"뜨거운 물질이 굳어 생긴 산","mis":"SC5-1-u1-X05"},{"t":"땅속에 고여 있는 물","mis":"SC5-1-u1-X05"},{"t":"흙 위에 자라는 식물의 뿌리","mis":"SC5-1-u1-X05"}],"explanation":["무지개떡을 떠올려요.","여러 층이 쌓였어요.","퇴적물이 쌓인 층이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_basic#2','sci',5,1,'u1','L02','g5_1_sci_u1_L02_basic','lesson_basic','SC5-1-u1-C5',1,'blank','auto','「지층은 여러 층으로 이루어져 있어 (    )가 보입니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u1-X07']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C5","difficulty":1,"kind":"blank","stem":"「지층은 여러 층으로 이루어져 있어 (    )가 보입니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"줄무늬","correct":true},{"t":"구멍","mis":"SC5-1-u1-X07"},{"t":"물방울","mis":"SC5-1-u1-X07"},{"t":"그림자","mis":"SC5-1-u1-X07"}],"explanation":["층이 겹쳐 있어요.","줄처럼 보여요.","줄무늬예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_basic#3','sci',5,1,'u1','L02','g5_1_sci_u1_L02_basic','lesson_basic','SC5-1-u1-C5',1,'ox','auto','지층의 층은 모두 두께가 똑같아요.',ARRAY['SC5-1-u1-X06']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C5","difficulty":1,"kind":"ox","stem":"지층의 층은 모두 두께가 똑같아요.","answer":"X","reason_options":[{"t":"두꺼운 층도 있고 얇은 층도 있기 때문에","correct":true},{"t":"지층은 사람이 자로 재어 똑같이 쌓았기 때문에","mis":"SC5-1-u1-X06"}],"mis":"SC5-1-u1-X06","explanation":["카드를 떠올려요.","두께가 달랐어요.","층마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_basic#4','sci',5,1,'u1','L02','g5_1_sci_u1_L02_basic','lesson_basic','SC5-1-u1-C4',1,'sa','auto','「자갈, 모래, 진흙 같은 것을 □□□이라고 합니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u1-C4","difficulty":1,"kind":"sa","stem":"「자갈, 모래, 진흙 같은 것을 □□□이라고 합니다.」 □□□에 알맞은 말을 쓰세요.","answer":["퇴적물"],"explanation":["쌓여서 층을 만들어요.","세 글자예요.","퇴적물이에요."],"mis":"SC5-1-u1-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_basic#5','sci',5,1,'u1','L02','g5_1_sci_u1_L02_basic','lesson_basic','SC5-1-u1-C6',2,'match','auto','지층의 모양과 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u1-C6","difficulty":2,"kind":"match","stem":"지층의 모양과 모습을 알맞게 이으세요.","pairs":[{"l":"수평인 지층","r":"층이 나란히 평평하게 이어진다"},{"l":"휘어진 지층","r":"층이 물결처럼 구부러져 있다"},{"l":"끊어진 지층","r":"층이 도중에 끊겨 어긋나 있다"}],"mis":"SC5-1-u1-X09","explanation":["이름을 잘 봐요.","평평·구부러짐·어긋남이에요.","모양이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_basic#6','sci',5,1,'u1','L02','g5_1_sci_u1_L02_basic','lesson_basic','SC5-1-u1-C5',2,'mc','auto','층마다 색깔이 다른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X07','SC5-1-u1-X06']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C5","difficulty":2,"kind":"mc","stem":"층마다 색깔이 다른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"층마다 쌓인 퇴적물의 종류가 다르기 때문에","correct":true},{"t":"사람이 층마다 다르게 칠했기 때문에","mis":"SC5-1-u1-X07"},{"t":"햇빛을 받은 시간이 다르기 때문에","mis":"SC5-1-u1-X07"},{"t":"모든 층의 색깔은 사실 같기 때문에","mis":"SC5-1-u1-X06"}],"explanation":["무엇이 쌓였나요?","쌓인 것이 달라요.","퇴적물의 종류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_basic#7','sci',5,1,'u1','L02','g5_1_sci_u1_L02_basic','lesson_basic','SC5-1-u1-C7',2,'mc','auto','지층 카드를 보고 관찰할 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u1-X10']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C7","difficulty":2,"kind":"mc","stem":"지층 카드를 보고 관찰할 수 있는 것은 어느 것인가요?","options":[{"t":"층의 두께","correct":true},{"t":"땅속의 온도","mis":"SC5-1-u1-X10"},{"t":"땅속의 소리","mis":"SC5-1-u1-X10"},{"t":"층이 쌓일 때 분 바람의 세기","mis":"SC5-1-u1-X10"}],"explanation":["눈으로 볼 수 있는 것이에요.","두께·색깔·모양이에요.","층의 두께예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_basic#8','sci',5,1,'u1','L02','g5_1_sci_u1_L02_basic','lesson_basic','SC5-1-u1-C6',2,'ox','auto','지층의 모양은 언제나 수평이에요.',ARRAY['SC5-1-u1-X08']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C6","difficulty":2,"kind":"ox","stem":"지층의 모양은 언제나 수평이에요.","answer":"X","reason_options":[{"t":"휘어진 지층이나 끊어진 지층처럼 모양이 다양하기 때문에","correct":true},{"t":"수평이 아닌 지층은 지층이라고 부르지 않기 때문에","mis":"SC5-1-u1-X08"}],"mis":"SC5-1-u1-X08","explanation":["세 가지 모양을 떠올려요.","휘어지고 끊어지기도 해요.","모양이 다양해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_basic#9','sci',5,1,'u1','L02','g5_1_sci_u1_L02_basic','lesson_basic','SC5-1-u1-C4',2,'mc','auto','지층을 볼 수 있는 곳으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X05']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C4","difficulty":2,"kind":"mc","stem":"지층을 볼 수 있는 곳으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바닷가 절벽","correct":true},{"t":"바닷물 속 한가운데","mis":"SC5-1-u1-X05"},{"t":"새로 지은 건물의 벽","mis":"SC5-1-u1-X05"},{"t":"구름 위","mis":"SC5-1-u1-X05"}],"explanation":["땅속이 드러난 곳이에요.","산비탈·절벽이에요.","바닷가 절벽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_basic#10','sci',5,1,'u1','L02','g5_1_sci_u1_L02_basic','lesson_basic','SC5-1-u1-C7',3,'mc','auto','지층 카드를 관찰하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X10']::text[],false,'{"seq":10,"concept":"SC5-1-u1-C7","difficulty":3,"kind":"mc","stem":"지층 카드를 관찰하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"카드 뜯기 → 모양·두께·색깔 적기 → 줄무늬 따라 선 긋기 → 모양별로 나누기","correct":true},{"t":"모양별로 나누기 → 카드 뜯기 → 줄무늬 따라 선 긋기 → 모양·두께·색깔 적기","mis":"SC5-1-u1-X10"},{"t":"줄무늬 따라 선 긋기 → 모양별로 나누기 → 카드 뜯기 → 모양·두께·색깔 적기","mis":"SC5-1-u1-X10"},{"t":"카드 뜯기 → 모양별로 나누기 → 모양·두께·색깔 적기 → 줄무늬 따라 선 긋기","mis":"SC5-1-u1-X10"}],"explanation":["먼저 카드를 뜯어요.","관찰하고 선을 그어요.","마지막에 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_challenge#1','sci',5,1,'u1','L02','g5_1_sci_u1_L02_challenge','lesson_challenge','SC5-1-u1-C6',2,'sa','auto','「층이 물결처럼 구부러져 있는 지층을 □□□ 지층이라고 합니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u1-C6","difficulty":2,"kind":"sa","stem":"「층이 물결처럼 구부러져 있는 지층을 □□□ 지층이라고 합니다.」 □□□에 알맞은 말을 쓰세요.","answer":["휘어진"],"explanation":["구부러진 모양이에요.","세 글자예요.","휘어진 지층이에요."],"mis":"SC5-1-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_challenge#2','sci',5,1,'u1','L02','g5_1_sci_u1_L02_challenge','lesson_challenge','SC5-1-u1-C6',2,'mc','auto','지층 카드 관찰 기록에서 끊어진 지층은 어느 카드인가요?',ARRAY['SC5-1-u1-X09','SC5-1-u1-X08']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C6","difficulty":2,"kind":"mc","stem":"지층 카드 관찰 기록에서 끊어진 지층은 어느 카드인가요?","options":[{"t":"다 카드","correct":true},{"t":"가 카드","mis":"SC5-1-u1-X09"},{"t":"나 카드","mis":"SC5-1-u1-X09"},{"t":"라 카드","mis":"SC5-1-u1-X08"}],"explanation":["어긋난 층을 찾아요.","끊겨 어긋났어요.","다 카드예요."],"asset":{"type":"passage","lines":["가 카드 — 층이 나란히 평평하게 이어진다. 두꺼운 층과 얇은 층이 있다.","나 카드 — 층이 물결처럼 구부러져 있다.","다 카드 — 층이 가운데에서 끊겨 위아래로 어긋나 있다.","라 카드 — 밝은 층과 어두운 층이 번갈아 보인다. 층이 평평하다."],"title":"지층 카드 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_challenge#3','sci',5,1,'u1','L02','g5_1_sci_u1_L02_challenge','lesson_challenge','SC5-1-u1-C6',3,'match','auto','카드를 지층의 모양에 맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u1-C6","difficulty":3,"kind":"match","stem":"카드를 지층의 모양에 맞게 이으세요.","pairs":[{"l":"가 카드","r":"수평인 지층"},{"l":"나 카드","r":"휘어진 지층"},{"l":"다 카드","r":"끊어진 지층"}],"mis":"SC5-1-u1-X09","explanation":["기록을 하나씩 읽어요.","평평·구부러짐·끊김이에요.","모양을 짝지어요."],"asset":{"type":"passage","lines":["가 카드 — 층이 나란히 평평하게 이어진다. 두꺼운 층과 얇은 층이 있다.","나 카드 — 층이 물결처럼 구부러져 있다.","다 카드 — 층이 가운데에서 끊겨 위아래로 어긋나 있다.","라 카드 — 밝은 층과 어두운 층이 번갈아 보인다. 층이 평평하다."],"title":"지층 카드 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_challenge#4','sci',5,1,'u1','L02','g5_1_sci_u1_L02_challenge','lesson_challenge','SC5-1-u1-C5',3,'error','auto','그림의 지층을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X07','SC5-1-u1-X06']::text[],false,'{"seq":4,"concept":"SC5-1-u1-C5","difficulty":3,"kind":"error","stem":"그림의 지층을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「층마다 색깔이 다른 건 햇빛이 비치는 방향 때문이야.」","correct":true,"mis_target":"SC5-1-u1-X07"},{"t":"민호 — 「세 층으로 이루어져 줄무늬가 보여.」","mis":"SC5-1-u1-X06"},{"t":"지아 — 「진흙층과 자갈층은 쌓인 것이 달라.」","mis":"SC5-1-u1-X06"}],"explanation":["색이 다른 까닭이에요.","쌓인 것이 달라서예요.","서윤이 잘못 말했어요."],"asset":{"type":"geo","items":[{"w":300,"h":128,"seg":[[[10,10],[290,10]],[[10,118],[290,118]],[[10,10],[10,118]],[[290,10],[290,118]],[[10,46],[290,46]],[[10,82],[290,82]]],"lab":[[[150,28],"진흙층"],[[150,64],"모래층"],[[150,100],"자갈층"]],"cap":"어느 바닷가 절벽의 지층(위에서부터)"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_challenge#5','sci',5,1,'u1','L02','g5_1_sci_u1_L02_challenge','lesson_challenge','SC5-1-u1-C5',3,'ox','auto','라 카드처럼 층이 평평한 지층에서도 층마다 색깔이 다를 수 있어요.',ARRAY['SC5-1-u1-X06']::text[],false,'{"seq":5,"concept":"SC5-1-u1-C5","difficulty":3,"kind":"ox","stem":"라 카드처럼 층이 평평한 지층에서도 층마다 색깔이 다를 수 있어요.","answer":"O","reason_options":[{"t":"층의 모양과 관계없이 층마다 쌓인 퇴적물이 다를 수 있기 때문에","correct":true},{"t":"평평한 지층은 언제나 한 가지 색이기 때문에","mis":"SC5-1-u1-X06"}],"mis":"SC5-1-u1-X06","explanation":["라 카드를 읽어요.","밝은 층·어두운 층이 있어요.","맞는 말이에요."],"asset":{"type":"passage","lines":["가 카드 — 층이 나란히 평평하게 이어진다. 두꺼운 층과 얇은 층이 있다.","나 카드 — 층이 물결처럼 구부러져 있다.","다 카드 — 층이 가운데에서 끊겨 위아래로 어긋나 있다.","라 카드 — 밝은 층과 어두운 층이 번갈아 보인다. 층이 평평하다."],"title":"지층 카드 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_challenge#6','sci',5,1,'u1','L02','g5_1_sci_u1_L02_challenge','lesson_challenge','SC5-1-u1-C7',3,'mc','auto','카드에 유성펜으로 줄무늬를 따라 선을 긋는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X10','SC5-1-u1-X06']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C7","difficulty":3,"kind":"mc","stem":"카드에 유성펜으로 줄무늬를 따라 선을 긋는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"층의 모양을 뚜렷하게 보기 위해","correct":true},{"t":"땅속의 온도를 알아보기 위해","mis":"SC5-1-u1-X10"},{"t":"카드를 예쁘게 꾸미기 위해","mis":"SC5-1-u1-X10"},{"t":"층의 색깔을 모두 같게 만들기 위해","mis":"SC5-1-u1-X06"}],"explanation":["선을 그으면 무엇이 잘 보이나요?","층의 모양이에요.","모양을 뚜렷하게 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_challenge#7','sci',5,1,'u1','L02','g5_1_sci_u1_L02_challenge','lesson_challenge','SC5-1-u1-C4',3,'mc','auto','무지개떡과 지층이 닮은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X05','SC5-1-u1-X06']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C4","difficulty":3,"kind":"mc","stem":"무지개떡과 지층이 닮은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 층이 위아래로 겹쳐 줄무늬를 이룬다","correct":true},{"t":"뜨거운 것이 식어 굳어 만들어진다","mis":"SC5-1-u1-X05"},{"t":"사람이 먹을 수 있다","mis":"SC5-1-u1-X05"},{"t":"층이 모두 똑같은 두께와 색깔이다","mis":"SC5-1-u1-X06"}],"explanation":["모습을 견줘요.","층이 겹쳐 있어요.","줄무늬예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_challenge#8','sci',5,1,'u1','L02','g5_1_sci_u1_L02_challenge','lesson_challenge','SC5-1-u1-C6',4,'mc','auto','「평평하던 층이 나중에 구부러졌다」는 설명이 가장 잘 어울리는 지층은 어느 것인가요?',ARRAY['SC5-1-u1-X09','SC5-1-u1-X08']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C6","difficulty":4,"kind":"mc","stem":"「평평하던 층이 나중에 구부러졌다」는 설명이 가장 잘 어울리는 지층은 어느 것인가요?","options":[{"t":"휘어진 지층","correct":true},{"t":"끊어진 지층","mis":"SC5-1-u1-X09"},{"t":"수평인 지층","mis":"SC5-1-u1-X09"},{"t":"모든 지층이 처음부터 구부러져 쌓였다","mis":"SC5-1-u1-X08"}],"explanation":["구부러진 모양이에요.","나중에 휘었어요.","휘어진 지층이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_challenge#9','sci',5,1,'u1','L02','g5_1_sci_u1_L02_challenge','lesson_challenge','SC5-1-u1-C5',4,'mc','auto','그림의 지층에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u1-X06','SC5-1-u1-X07','SC5-1-u1-X08']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C5","difficulty":4,"kind":"mc","stem":"그림의 지층에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"세 층의 쌓인 것이 달라 층마다 색깔과 두께가 다를 수 있다","correct":true},{"t":"세 층은 퇴적물이 같으니 색깔도 같다","mis":"SC5-1-u1-X06"},{"t":"층마다 색이 다른 것은 바람이 표면을 문질러서이다","mis":"SC5-1-u1-X07"},{"t":"층이 평평하니 이것은 지층이 아니다","mis":"SC5-1-u1-X08"}],"explanation":["층 이름을 읽어요.","진흙·모래·자갈이에요.","쌓인 것이 달라요."],"asset":{"type":"geo","items":[{"w":300,"h":128,"seg":[[[10,10],[290,10]],[[10,118],[290,118]],[[10,10],[10,118]],[[290,10],[290,118]],[[10,46],[290,46]],[[10,82],[290,82]]],"lab":[[[150,28],"진흙층"],[[150,64],"모래층"],[[150,100],"자갈층"]],"cap":"어느 바닷가 절벽의 지층(위에서부터)"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L02_challenge#10','sci',5,1,'u1','L02','g5_1_sci_u1_L02_challenge','lesson_challenge','SC5-1-u1-C5',4,'essay','teacher','지층 카드 관찰 기록을 보고 네 카드에서 모두 찾을 수 있는 지층의 공통점을 두 가지 쓰고, 모양이 서로 다른 점을 카드를 들어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u1-C5","difficulty":4,"kind":"essay","stem":"지층 카드 관찰 기록을 보고 네 카드에서 모두 찾을 수 있는 지층의 공통점을 두 가지 쓰고, 모양이 서로 다른 점을 카드를 들어 설명하세요.","answer_guide":{"answer":"예: 네 카드 모두 여러 층으로 이루어져 줄무늬가 보이고, 층마다 두께나 색깔이 다르다. 모양은 서로 다르다. 가 카드와 라 카드는 층이 평평한 수평인 지층이고, 나 카드는 층이 물결처럼 구부러진 휘어진 지층이며, 다 카드는 층이 끊겨 어긋난 끊어진 지층이다.","scoring_points":["공통점(여러 층·줄무늬)을 썼는가","두께·색깔이 다름을 썼는가","카드를 들어 모양의 차이를 설명했는가"]},"explanation":["공통점을 먼저 찾아요.","모양을 견줘요.","카드를 들어 써요."],"asset":{"type":"passage","lines":["가 카드 — 층이 나란히 평평하게 이어진다. 두꺼운 층과 얇은 층이 있다.","나 카드 — 층이 물결처럼 구부러져 있다.","다 카드 — 층이 가운데에서 끊겨 위아래로 어긋나 있다.","라 카드 — 밝은 층과 어두운 층이 번갈아 보인다. 층이 평평하다."],"title":"지층 카드 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_basic#1','sci',5,1,'u1','L03','g5_1_sci_u1_L03_basic','lesson_basic','SC5-1-u1-C10',1,'mc','auto','지층에서 가장 먼저 쌓인 층은 어디에 있나요?',ARRAY['SC5-1-u1-X12']::text[],false,'{"seq":1,"concept":"SC5-1-u1-C10","difficulty":1,"kind":"mc","stem":"지층에서 가장 먼저 쌓인 층은 어디에 있나요?","options":[{"t":"맨 아래","correct":true},{"t":"맨 위","mis":"SC5-1-u1-X12"},{"t":"가운데","mis":"SC5-1-u1-X12"},{"t":"층마다 달라 알 수 없다","mis":"SC5-1-u1-X12"}],"explanation":["돌탑을 떠올려요.","먼저 놓은 돌은 아래에 있어요.","맨 아래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_basic#2','sci',5,1,'u1','L03','g5_1_sci_u1_L03_basic','lesson_basic','SC5-1-u1-C11',1,'mc','auto','지층 모형에서 물은 어떤 역할을 했나요?',ARRAY['SC5-1-u1-X15','SC5-1-u1-X14']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C11","difficulty":1,"kind":"mc","stem":"지층 모형에서 물은 어떤 역할을 했나요?","options":[{"t":"자갈·모래·진흙을 함께 흘러내리게 해 쌓이게 했다","correct":true},{"t":"층에 색깔을 입혔다","mis":"SC5-1-u1-X15"},{"t":"층을 단단하게 구웠다","mis":"SC5-1-u1-X14"},{"t":"층을 끊어지게 했다","mis":"SC5-1-u1-X15"}],"explanation":["물과 함께 부었어요.","흘러내려 쌓였어요.","운반하는 역할이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_basic#3','sci',5,1,'u1','L03','g5_1_sci_u1_L03_basic','lesson_basic','SC5-1-u1-C9',1,'ox','auto','실제 지층은 아주 오랜 시간에 걸쳐 만들어져요.',ARRAY['SC5-1-u1-X13']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C9","difficulty":1,"kind":"ox","stem":"실제 지층은 아주 오랜 시간에 걸쳐 만들어져요.","answer":"O","reason_options":[{"t":"쌓인 것이 오랜 시간 눌리고 굳어져야 하기 때문에","correct":true},{"t":"모형처럼 몇 분이면 만들어지기 때문에","mis":"SC5-1-u1-X13"}],"mis":"SC5-1-u1-X13","explanation":["모형과 실제를 견줘요.","실제는 오래 걸려요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_basic#4','sci',5,1,'u1','L03','g5_1_sci_u1_L03_basic','lesson_basic','SC5-1-u1-C10',1,'sa','auto','그림의 지층에서 가장 먼저 쌓인 층은 무엇인가요? (□□층)','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u1-C10","difficulty":1,"kind":"sa","stem":"그림의 지층에서 가장 먼저 쌓인 층은 무엇인가요? (□□층)","answer":["자갈층","자갈"],"explanation":["맨 아래 층을 봐요.","아래가 먼저예요.","자갈층이에요."],"asset":{"type":"geo","items":[{"w":300,"h":128,"seg":[[[10,10],[290,10]],[[10,118],[290,118]],[[10,10],[10,118]],[[290,10],[290,118]],[[10,46],[290,46]],[[10,82],[290,82]]],"lab":[[[150,28],"진흙층"],[[150,64],"모래층"],[[150,100],"자갈층"]],"cap":"어느 바닷가 절벽의 지층(위에서부터)"}],"tag":false},"mis":"SC5-1-u1-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_basic#5','sci',5,1,'u1','L03','g5_1_sci_u1_L03_basic','lesson_basic','SC5-1-u1-C9',2,'match','auto','지층이 만들어지는 차례와 일어나는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u1-C9","difficulty":2,"kind":"match","stem":"지층이 만들어지는 차례와 일어나는 일을 알맞게 이으세요.","pairs":[{"l":"첫째","r":"흐르는 물이 운반한 것이 밑바닥에 쌓인다"},{"l":"둘째","r":"계속 쌓여 먼저 쌓인 것이 눌린다"},{"l":"셋째","r":"오랜 시간이 지나 단단하게 굳어진다"},{"l":"넷째","r":"땅 위로 드러나 깎이면 보인다"}],"mis":"SC5-1-u1-X16","explanation":["쌓이는 것부터 시작해요.","눌리고 굳어요.","마지막에 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_basic#6','sci',5,1,'u1','L03','g5_1_sci_u1_L03_basic','lesson_basic','SC5-1-u1-C8',2,'mc','auto','지층 모형을 만들 때 컵 세 개에 각각 무엇을 담나요?',ARRAY['SC5-1-u1-X11']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C8","difficulty":2,"kind":"mc","stem":"지층 모형을 만들 때 컵 세 개에 각각 무엇을 담나요?","options":[{"t":"자갈과 모래, 모래, 진흙","correct":true},{"t":"밀가루, 콩, 쌀","mis":"SC5-1-u1-X11"},{"t":"흙, 블록, 붓","mis":"SC5-1-u1-X11"},{"t":"소금, 설탕, 물","mis":"SC5-1-u1-X11"}],"explanation":["층을 이룰 재료예요.","알갱이가 서로 달라요.","자갈과 모래·모래·진흙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_basic#7','sci',5,1,'u1','L03','g5_1_sci_u1_L03_basic','lesson_basic','SC5-1-u1-C10',2,'ox','auto','그림의 지층에서 진흙층은 가장 나중에 쌓인 층이에요.',ARRAY['SC5-1-u1-X17']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C10","difficulty":2,"kind":"ox","stem":"그림의 지층에서 진흙층은 가장 나중에 쌓인 층이에요.","answer":"O","reason_options":[{"t":"맨 위에 있는 층이 가장 나중에 쌓였기 때문에","correct":true},{"t":"진흙은 언제나 가장 나중에 쌓이기 때문에","mis":"SC5-1-u1-X17"}],"mis":"SC5-1-u1-X17","explanation":["진흙층의 자리를 봐요.","맨 위에 있어요.","맞는 말이에요."],"asset":{"type":"geo","items":[{"w":300,"h":128,"seg":[[[10,10],[290,10]],[[10,118],[290,118]],[[10,10],[10,118]],[[290,10],[290,118]],[[10,46],[290,46]],[[10,82],[290,82]]],"lab":[[[150,28],"진흙층"],[[150,64],"모래층"],[[150,100],"자갈층"]],"cap":"어느 바닷가 절벽의 지층(위에서부터)"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_basic#8','sci',5,1,'u1','L03','g5_1_sci_u1_L03_basic','lesson_basic','SC5-1-u1-C9',2,'mc','auto','흐르는 물이 운반한 자갈·모래·진흙은 주로 어디에 쌓이나요?',ARRAY['SC5-1-u1-X16','SC5-1-u1-X05']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C9","difficulty":2,"kind":"mc","stem":"흐르는 물이 운반한 자갈·모래·진흙은 주로 어디에 쌓이나요?","options":[{"t":"바다나 호수 밑바닥","correct":true},{"t":"산꼭대기","mis":"SC5-1-u1-X16"},{"t":"구름 속","mis":"SC5-1-u1-X05"},{"t":"나뭇가지 위","mis":"SC5-1-u1-X05"}],"explanation":["물이 흘러가 멈추는 곳이에요.","밑바닥이에요.","바다나 호수 밑바닥이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_basic#9','sci',5,1,'u1','L03','g5_1_sci_u1_L03_basic','lesson_basic','SC5-1-u1-C8',2,'error','auto','실험하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X11']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C8","difficulty":2,"kind":"error","stem":"실험하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「남은 진흙은 개수대에 그냥 버리면 돼.」","correct":true,"mis_target":"SC5-1-u1-X11"},{"t":"소율 — 「재료 만진 손으로 눈을 만지지 말자.」","mis":"SC5-1-u1-X11"},{"t":"건우 — 「실험이 끝나면 주변을 정리하자.」","mis":"SC5-1-u1-X11"}],"explanation":["정리와 처리를 떠올려요.","안내에 따라 처리해요.","태윤이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_basic#10','sci',5,1,'u1','L03','g5_1_sci_u1_L03_basic','lesson_basic','SC5-1-u1-C11',3,'mc','auto','실제 지층이 모형과 달리 단단한 까닭은 어느 것인가요?',ARRAY['SC5-1-u1-X14','SC5-1-u1-X13']::text[],false,'{"seq":10,"concept":"SC5-1-u1-C11","difficulty":3,"kind":"mc","stem":"실제 지층이 모형과 달리 단단한 까닭은 어느 것인가요?","options":[{"t":"오랜 시간 눌리면서 굳어졌기 때문에","correct":true},{"t":"뜨거운 불에 구워졌기 때문에","mis":"SC5-1-u1-X14"},{"t":"얼음처럼 얼어붙었기 때문에","mis":"SC5-1-u1-X14"},{"t":"하루 만에 빠르게 만들어졌기 때문에","mis":"SC5-1-u1-X13"}],"explanation":["모형은 쉽게 흩어져요.","실제는 오래 걸려요.","눌리고 굳어졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_challenge#1','sci',5,1,'u1','L03','g5_1_sci_u1_L03_challenge','lesson_challenge','SC5-1-u1-C9',2,'sa','auto','「먼저 쌓인 것은 그 위에 계속 쌓이는 것의 무게에 □□□.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u1-C9","difficulty":2,"kind":"sa","stem":"「먼저 쌓인 것은 그 위에 계속 쌓이는 것의 무게에 □□□.」 □□□에 알맞은 말을 쓰세요.","answer":["눌린다","눌립니다","눌려요"],"explanation":["위에서 무게가 실려요.","납작해져요.","눌린다예요."],"mis":"SC5-1-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_challenge#2','sci',5,1,'u1','L03','g5_1_sci_u1_L03_challenge','lesson_challenge','SC5-1-u1-C10',2,'mc','auto','도윤이네 모둠의 지층 모형에서 맨 아래에 깔린 층은 어느 것인가요?',ARRAY['SC5-1-u1-X12','SC5-1-u1-X11']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C10","difficulty":2,"kind":"mc","stem":"도윤이네 모둠의 지층 모형에서 맨 아래에 깔린 층은 어느 것인가요?","options":[{"t":"모래층","correct":true},{"t":"진흙층","mis":"SC5-1-u1-X12"},{"t":"자갈과 모래층","mis":"SC5-1-u1-X12"},{"t":"세 층이 섞여 층이 생기지 않는다","mis":"SC5-1-u1-X11"}],"explanation":["가장 먼저 부은 것을 찾아요.","먼저 부은 것이 아래로 가요.","모래층이에요."],"asset":{"type":"passage","lines":["투명한 사각 통에 물을 4분의 1 정도 부었다.","컵 세 개에 자갈과 모래, 모래, 진흙을 절반 정도 채우고 잠기도록 물을 부었다.","모래 → 자갈과 모래 → 진흙 차례로 사각 통에 부었다."],"title":"도윤이네 모둠의 지층 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_challenge#3','sci',5,1,'u1','L03','g5_1_sci_u1_L03_challenge','lesson_challenge','SC5-1-u1-C10',3,'mc','auto','그림의 지층을 오래된 층부터 차례로 늘어놓은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X12','SC5-1-u1-X17','SC5-1-u1-X13']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C10","difficulty":3,"kind":"mc","stem":"그림의 지층을 오래된 층부터 차례로 늘어놓은 것은 어느 것인가요?","options":[{"t":"진흙층 → 자갈과 모래층 → 진흙층 → 모래층","correct":true},{"t":"모래층 → 진흙층 → 자갈과 모래층 → 진흙층","mis":"SC5-1-u1-X12"},{"t":"자갈과 모래층 → 모래층 → 진흙층 → 진흙층","mis":"SC5-1-u1-X17"},{"t":"네 층은 한꺼번에 쌓여 차례가 없다","mis":"SC5-1-u1-X13"}],"explanation":["맨 아래부터 읽어요.","아래가 오래된 층이에요.","아래에서 위로 늘어놓아요."],"asset":{"type":"geo","items":[{"w":300,"h":164,"seg":[[[10,10],[290,10]],[[10,154],[290,154]],[[10,10],[10,154]],[[290,10],[290,154]],[[10,46],[290,46]],[[10,82],[290,82]],[[10,118],[290,118]]],"lab":[[[150,28],"모래층"],[[150,64],"진흙층"],[[150,100],"자갈과 모래층"],[[150,136],"진흙층"]],"cap":"어느 산비탈의 지층(위에서부터)"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_challenge#4','sci',5,1,'u1','L03','g5_1_sci_u1_L03_challenge','lesson_challenge','SC5-1-u1-C9',3,'error','auto','지층이 만들어지는 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X16','SC5-1-u1-X17','SC5-1-u1-X34']::text[],false,'{"seq":4,"concept":"SC5-1-u1-C9","difficulty":3,"kind":"error","stem":"지층이 만들어지는 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예서 — 「단단하게 굳은 다음에 그 위로 자갈과 모래가 운반되어 와서 눌러.」","correct":true,"mis_target":"SC5-1-u1-X16"},{"t":"주원 — 「진흙이 언제나 맨 위에 쌓이는 건 아니야.」","mis":"SC5-1-u1-X17"},{"t":"하늘 — 「땅 위로 드러나 깎여야 우리가 볼 수 있어.」","mis":"SC5-1-u1-X34"}],"explanation":["차례를 떠올려요.","쌓이고 눌리고 굳어요.","예서가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_challenge#5','sci',5,1,'u1','L03','g5_1_sci_u1_L03_challenge','lesson_challenge','SC5-1-u1-C11',3,'match','auto','지층 모형과 실제 지층을 견준 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u1-C11","difficulty":3,"kind":"match","stem":"지층 모형과 실제 지층을 견준 내용을 알맞게 이으세요.","pairs":[{"l":"여러 층이 생긴다","r":"모형과 실제 지층의 공통점"},{"l":"몇 분이면 만들어진다","r":"모형만의 특징"},{"l":"아주 오랜 시간 눌리고 굳어진다","r":"실제 지층만의 특징"}],"mis":"SC5-1-u1-X13","explanation":["하나씩 견줘요.","닮은 것과 다른 것이 있어요.","시간과 단단함이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_challenge#6','sci',5,1,'u1','L03','g5_1_sci_u1_L03_challenge','lesson_challenge','SC5-1-u1-C9',3,'ox','auto','그림의 지층과 달리 다른 곳에서는 진흙층이 맨 아래에 있을 수도 있어요.',ARRAY['SC5-1-u1-X17']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C9","difficulty":3,"kind":"ox","stem":"그림의 지층과 달리 다른 곳에서는 진흙층이 맨 아래에 있을 수도 있어요.","answer":"O","reason_options":[{"t":"자갈·모래·진흙이 쌓이는 차례는 그때그때 다를 수 있기 때문에","correct":true},{"t":"진흙은 언제나 맨 위에만 쌓이기 때문에","mis":"SC5-1-u1-X17"}],"mis":"SC5-1-u1-X17","explanation":["쌓이는 차례를 생각해요.","언제나 같지는 않아요.","맞는 말이에요."],"asset":{"type":"geo","items":[{"w":300,"h":128,"seg":[[[10,10],[290,10]],[[10,118],[290,118]],[[10,10],[10,118]],[[290,10],[290,118]],[[10,46],[290,46]],[[10,82],[290,82]]],"lab":[[[150,28],"진흙층"],[[150,64],"모래층"],[[150,100],"자갈층"]],"cap":"어느 바닷가 절벽의 지층(위에서부터)"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_challenge#7','sci',5,1,'u1','L03','g5_1_sci_u1_L03_challenge','lesson_challenge','SC5-1-u1-C11',3,'mc','auto','지층 모형 속 물은 실제 자연의 무엇과 같은 일을 하나요?',ARRAY['SC5-1-u1-X14','SC5-1-u1-X15']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C11","difficulty":3,"kind":"mc","stem":"지층 모형 속 물은 실제 자연의 무엇과 같은 일을 하나요?","options":[{"t":"흐르는 물","correct":true},{"t":"뜨거운 불","mis":"SC5-1-u1-X14"},{"t":"얼음","mis":"SC5-1-u1-X14"},{"t":"사람의 손","mis":"SC5-1-u1-X15"}],"explanation":["재료를 옮겨 쌓아요.","자연에서 옮겨 주는 것이에요.","흐르는 물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_challenge#8','sci',5,1,'u1','L03','g5_1_sci_u1_L03_challenge','lesson_challenge','SC5-1-u1-C8',4,'mc','auto','지층 모형을 만들 때 각 컵에 물을 붓는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X15','SC5-1-u1-X14','SC5-1-u1-X11']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C8","difficulty":4,"kind":"mc","stem":"지층 모형을 만들 때 각 컵에 물을 붓는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"재료가 물과 섞여 사각 통으로 한 번에 흘러내리게 하려고","correct":true},{"t":"재료의 색깔을 모두 같게 하려고","mis":"SC5-1-u1-X15"},{"t":"재료를 단단하게 굳히려고","mis":"SC5-1-u1-X14"},{"t":"물 없이 마른 재료를 부어야 층이 생기니 물은 필요 없다","mis":"SC5-1-u1-X11"}],"explanation":["물에 잠긴 재료를 부어요.","흘러내려야 해요.","함께 흘러내리게 해요."],"asset":{"type":"passage","lines":["투명한 사각 통에 물을 4분의 1 정도 부었다.","컵 세 개에 자갈과 모래, 모래, 진흙을 절반 정도 채우고 잠기도록 물을 부었다.","모래 → 자갈과 모래 → 진흙 차례로 사각 통에 부었다."],"title":"도윤이네 모둠의 지층 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_challenge#9','sci',5,1,'u1','L03','g5_1_sci_u1_L03_challenge','lesson_challenge','SC5-1-u1-C10',4,'mc','auto','친구가 「돌탑의 맨 위 돌을 가장 먼저 쌓았을 거야.」라고 말했어요. 가장 알맞은 대답은 어느 것인가요?',ARRAY['SC5-1-u1-X12','SC5-1-u1-X17','SC5-1-u1-X13']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C10","difficulty":4,"kind":"mc","stem":"친구가 「돌탑의 맨 위 돌을 가장 먼저 쌓았을 거야.」라고 말했어요. 가장 알맞은 대답은 어느 것인가요?","options":[{"t":"맨 아래 돌이 먼저 놓여야 그 위에 쌓을 수 있으니 맨 아래 돌이 가장 먼저 쌓은 돌이야","correct":true},{"t":"맞아, 지층도 맨 위 층이 가장 먼저 쌓인 층이야","mis":"SC5-1-u1-X12"},{"t":"돌탑과 지층은 쌓인 차례를 알 수 없어","mis":"SC5-1-u1-X17"},{"t":"돌탑은 하루 만에 쌓으니 지층도 하루 만에 생겨","mis":"SC5-1-u1-X13"}],"explanation":["돌을 쌓는 차례를 떠올려요.","아래부터 쌓아요.","맨 아래 돌이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L03_challenge#10','sci',5,1,'u1','L03','g5_1_sci_u1_L03_challenge','lesson_challenge','SC5-1-u1-C9',4,'essay','teacher','그림의 지층이 만들어지기까지의 과정을 쌓임·눌림·굳어짐·드러남의 차례로 설명하고, 세 층 가운데 가장 오래된 층과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u1-C9","difficulty":4,"kind":"essay","stem":"그림의 지층이 만들어지기까지의 과정을 쌓임·눌림·굳어짐·드러남의 차례로 설명하고, 세 층 가운데 가장 오래된 층과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 흐르는 물이 운반한 자갈, 모래, 진흙이 바다나 호수 밑바닥에 차례로 쌓였다. 그 위에 계속 쌓이면서 먼저 쌓인 것이 무게에 눌렸고, 오랜 시간이 지나 단단하게 굳어져 지층이 되었다. 이 지층이 땅 위로 드러나 깎여서 우리가 볼 수 있게 되었다. 가장 오래된 층은 맨 아래의 자갈층이다. 아래에 있는 층이 위에 있는 층보다 먼저 쌓였기 때문이다.","scoring_points":["네 단계를 차례대로 썼는가","오랜 시간이 걸림을 썼는가","가장 오래된 층과 까닭을 바르게 썼는가"]},"explanation":["쌓이는 것부터 써요.","드러나는 것까지 써요.","맨 아래 층을 봐요."],"asset":{"type":"geo","items":[{"w":300,"h":128,"seg":[[[10,10],[290,10]],[[10,118],[290,118]],[[10,10],[10,118]],[[290,10],[290,118]],[[10,46],[290,46]],[[10,82],[290,82]]],"lab":[[[150,28],"진흙층"],[[150,64],"모래층"],[[150,100],"자갈층"]],"cap":"어느 바닷가 절벽의 지층(위에서부터)"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_basic#1','sci',5,1,'u1','L04','g5_1_sci_u1_L04_basic','lesson_basic','SC5-1-u1-C13',1,'mc','auto','퇴적암을 이암·사암·역암으로 나누는 기준은 어느 것인가요?',ARRAY['SC5-1-u1-X18']::text[],false,'{"seq":1,"concept":"SC5-1-u1-C13","difficulty":1,"kind":"mc","stem":"퇴적암을 이암·사암·역암으로 나누는 기준은 어느 것인가요?","options":[{"t":"암석을 이루는 알갱이의 크기","correct":true},{"t":"암석의 색깔","mis":"SC5-1-u1-X18"},{"t":"암석의 무게","mis":"SC5-1-u1-X18"},{"t":"암석이 발견된 지역","mis":"SC5-1-u1-X18"}],"explanation":["강정을 떠올려요.","쌀알과 콩은 크기가 달라요.","알갱이의 크기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_basic#2','sci',5,1,'u1','L04','g5_1_sci_u1_L04_basic','lesson_basic','SC5-1-u1-C13',1,'mc','auto','주로 모래로 이루어진 퇴적암은 어느 것인가요?',ARRAY['SC5-1-u1-X19','SC5-1-u1-X24']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C13","difficulty":1,"kind":"mc","stem":"주로 모래로 이루어진 퇴적암은 어느 것인가요?","options":[{"t":"사암","correct":true},{"t":"이암","mis":"SC5-1-u1-X19"},{"t":"역암","mis":"SC5-1-u1-X19"},{"t":"얼음","mis":"SC5-1-u1-X24"}],"explanation":["모래를 떠올려요.","알갱이가 중간이에요.","사암이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_basic#3','sci',5,1,'u1','L04','g5_1_sci_u1_L04_basic','lesson_basic','SC5-1-u1-C12',1,'ox','auto','지층은 퇴적암으로 이루어져 있어요.',ARRAY['SC5-1-u1-X24']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C12","difficulty":1,"kind":"ox","stem":"지층은 퇴적암으로 이루어져 있어요.","answer":"O","reason_options":[{"t":"퇴적물이 쌓여 굳어진 암석이 지층을 이루기 때문에","correct":true},{"t":"지층은 뜨거운 물질이 식어 굳은 암석으로만 이루어지기 때문에","mis":"SC5-1-u1-X24"}],"mis":"SC5-1-u1-X24","explanation":["지층은 무엇이 쌓였나요?","퇴적물이 굳은 암석이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_basic#4','sci',5,1,'u1','L04','g5_1_sci_u1_L04_basic','lesson_basic','SC5-1-u1-C12',1,'sa','auto','「퇴적물이 굳어져 만들어진 암석을 □□□이라고 합니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u1-C12","difficulty":1,"kind":"sa","stem":"「퇴적물이 굳어져 만들어진 암석을 □□□이라고 합니다.」 □□□에 알맞은 말을 쓰세요.","answer":["퇴적암"],"explanation":["퇴적물이 굳었어요.","세 글자예요.","퇴적암이에요."],"mis":"SC5-1-u1-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_basic#5','sci',5,1,'u1','L04','g5_1_sci_u1_L04_basic','lesson_basic','SC5-1-u1-C13',2,'match','auto','퇴적암과 주로 이루고 있는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u1-C13","difficulty":2,"kind":"match","stem":"퇴적암과 주로 이루고 있는 것을 알맞게 이으세요.","pairs":[{"l":"이암","r":"진흙이나 갯벌의 흙"},{"l":"사암","r":"모래"},{"l":"역암","r":"자갈에 모래나 진흙이 섞인 것"}],"mis":"SC5-1-u1-X19","explanation":["알갱이를 떠올려요.","진흙·모래·자갈이에요.","셋이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_basic#6','sci',5,1,'u1','L04','g5_1_sci_u1_L04_basic','lesson_basic','SC5-1-u1-C13',2,'mc','auto','이암·사암·역암 가운데 알갱이가 가장 큰 것은 어느 것인가요?',ARRAY['SC5-1-u1-X19','SC5-1-u1-X18']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C13","difficulty":2,"kind":"mc","stem":"이암·사암·역암 가운데 알갱이가 가장 큰 것은 어느 것인가요?","options":[{"t":"역암","correct":true},{"t":"이암","mis":"SC5-1-u1-X19"},{"t":"사암","mis":"SC5-1-u1-X19"},{"t":"셋 다 알갱이 크기가 같다","mis":"SC5-1-u1-X18"}],"explanation":["자갈이 섞였어요.","자갈은 커요.","역암이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_basic#7','sci',5,1,'u1','L04','g5_1_sci_u1_L04_basic','lesson_basic','SC5-1-u1-C14',2,'mc','auto','퇴적암 표본의 알갱이 크기를 자세히 볼 때 쓰는 도구는 어느 것인가요?',ARRAY['SC5-1-u1-X23','SC5-1-u1-X18']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C14","difficulty":2,"kind":"mc","stem":"퇴적암 표본의 알갱이 크기를 자세히 볼 때 쓰는 도구는 어느 것인가요?","options":[{"t":"돋보기","correct":true},{"t":"자석","mis":"SC5-1-u1-X23"},{"t":"저울","mis":"SC5-1-u1-X18"},{"t":"온도계","mis":"SC5-1-u1-X23"}],"explanation":["작은 것을 크게 봐요.","알갱이를 봐요.","돋보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_basic#8','sci',5,1,'u1','L04','g5_1_sci_u1_L04_basic','lesson_basic','SC5-1-u1-C14',2,'ox','auto','퇴적암을 관찰할 때 암석을 혀로 맛보아도 돼요.',ARRAY['SC5-1-u1-X23']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C14","difficulty":2,"kind":"ox","stem":"퇴적암을 관찰할 때 암석을 혀로 맛보아도 돼요.","answer":"X","reason_options":[{"t":"암석을 맛보면 위험할 수 있고 관찰은 손과 돋보기로 하기 때문에","correct":true},{"t":"혀로 맛봐야 알갱이 크기를 알 수 있기 때문에","mis":"SC5-1-u1-X23"}],"mis":"SC5-1-u1-X23","explanation":["안전을 떠올려요.","맛보지 않아요.","손과 돋보기로 관찰해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_basic#9','sci',5,1,'u1','L04','g5_1_sci_u1_L04_basic','lesson_basic','SC5-1-u1-C15',2,'mc','auto','퇴적암이 만들어질 때 쌓인 퇴적물이 눌리면 어떻게 되나요?',ARRAY['SC5-1-u1-X21']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C15","difficulty":2,"kind":"mc","stem":"퇴적암이 만들어질 때 쌓인 퇴적물이 눌리면 어떻게 되나요?","options":[{"t":"알갱이 사이의 공간이 좁아진다","correct":true},{"t":"불에 구워져 단단해진다","mis":"SC5-1-u1-X21"},{"t":"알갱이가 모두 녹아 없어진다","mis":"SC5-1-u1-X21"},{"t":"알갱이 사이가 넓어진다","mis":"SC5-1-u1-X21"}],"explanation":["위에서 눌러요.","틈이 줄어요.","공간이 좁아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_basic#10','sci',5,1,'u1','L04','g5_1_sci_u1_L04_basic','lesson_basic','SC5-1-u1-C15',3,'mc','auto','손으로 모래를 세게 쥐어도 암석처럼 단단해지지 않는 까닭은 어느 것인가요?',ARRAY['SC5-1-u1-X22','SC5-1-u1-X21']::text[],false,'{"seq":10,"concept":"SC5-1-u1-C15","difficulty":3,"kind":"mc","stem":"손으로 모래를 세게 쥐어도 암석처럼 단단해지지 않는 까닭은 어느 것인가요?","options":[{"t":"오랜 시간 눌리고 엉겨 붙는 과정이 없기 때문에","correct":true},{"t":"손힘이 약하기 때문에","mis":"SC5-1-u1-X22"},{"t":"모래가 차갑기 때문에","mis":"SC5-1-u1-X22"},{"t":"모래는 불에 구워야만 암석이 되기 때문에","mis":"SC5-1-u1-X21"}],"explanation":["퇴적암이 되는 과정을 떠올려요.","오래 눌리고 엉겨 붙어요.","그 과정이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_challenge#1','sci',5,1,'u1','L04','g5_1_sci_u1_L04_challenge','lesson_challenge','SC5-1-u1-C15',2,'sa','auto','「물에 녹은 물질이 알갱이를 □□ 붙게 하여 퇴적암이 됩니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u1-C15","difficulty":2,"kind":"sa","stem":"「물에 녹은 물질이 알갱이를 □□ 붙게 하여 퇴적암이 됩니다.」 □□에 알맞은 말을 쓰세요.","answer":["엉겨"],"explanation":["알갱이끼리 붙어요.","두 글자예요.","엉겨예요."],"mis":"SC5-1-u1-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_challenge#2','sci',5,1,'u1','L04','g5_1_sci_u1_L04_challenge','lesson_challenge','SC5-1-u1-C13',2,'mc','auto','관찰 기록의 3번 표본은 어느 퇴적암인가요?',ARRAY['SC5-1-u1-X19','SC5-1-u1-X18']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C13","difficulty":2,"kind":"mc","stem":"관찰 기록의 3번 표본은 어느 퇴적암인가요?","options":[{"t":"역암","correct":true},{"t":"이암","mis":"SC5-1-u1-X19"},{"t":"사암","mis":"SC5-1-u1-X19"},{"t":"알 수 없다 — 색깔을 적지 않았다","mis":"SC5-1-u1-X18"}],"explanation":["자갈이 보여요.","자갈 사이에 모래와 진흙이 있어요.","역암이에요."],"asset":{"type":"passage","lines":["1번 — 만지면 매끈하다. 돋보기로 보아도 알갱이가 거의 보이지 않는다.","2번 — 만지면 까끌까끌하다. 모래만 한 알갱이가 보인다.","3번 — 콩알만 한 자갈 사이에 모래와 진흙이 섞여 있다.","4번 — 1번처럼 매끈하고 알갱이가 거의 보이지 않는다. 색은 1번보다 밝다."],"title":"퇴적암 표본 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_challenge#3','sci',5,1,'u1','L04','g5_1_sci_u1_L04_challenge','lesson_challenge','SC5-1-u1-C13',3,'error','auto','관찰 기록을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X20','SC5-1-u1-X19']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C13","difficulty":3,"kind":"error","stem":"관찰 기록을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라희 — 「1번과 4번은 색이 다르니까 다른 종류의 퇴적암이야.」","correct":true,"mis_target":"SC5-1-u1-X20"},{"t":"정우 — 「2번은 모래만 한 알갱이가 보이니 사암이야.」","mis":"SC5-1-u1-X19"},{"t":"수빈 — 「1번은 알갱이가 거의 안 보이니 이암이야.」","mis":"SC5-1-u1-X19"}],"explanation":["분류 기준을 떠올려요.","색이 아니라 알갱이예요.","라희가 잘못 말했어요."],"asset":{"type":"passage","lines":["1번 — 만지면 매끈하다. 돋보기로 보아도 알갱이가 거의 보이지 않는다.","2번 — 만지면 까끌까끌하다. 모래만 한 알갱이가 보인다.","3번 — 콩알만 한 자갈 사이에 모래와 진흙이 섞여 있다.","4번 — 1번처럼 매끈하고 알갱이가 거의 보이지 않는다. 색은 1번보다 밝다."],"title":"퇴적암 표본 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_challenge#4','sci',5,1,'u1','L04','g5_1_sci_u1_L04_challenge','lesson_challenge','SC5-1-u1-C13',3,'match','auto','관찰 기록의 표본과 퇴적암 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u1-C13","difficulty":3,"kind":"match","stem":"관찰 기록의 표본과 퇴적암 이름을 알맞게 이으세요.","pairs":[{"l":"1번","r":"이암"},{"l":"2번","r":"사암"},{"l":"3번","r":"역암"}],"mis":"SC5-1-u1-X19","explanation":["알갱이 크기를 읽어요.","작은 것·중간·큰 것이에요.","이암·사암·역암이에요."],"asset":{"type":"passage","lines":["1번 — 만지면 매끈하다. 돋보기로 보아도 알갱이가 거의 보이지 않는다.","2번 — 만지면 까끌까끌하다. 모래만 한 알갱이가 보인다.","3번 — 콩알만 한 자갈 사이에 모래와 진흙이 섞여 있다.","4번 — 1번처럼 매끈하고 알갱이가 거의 보이지 않는다. 색은 1번보다 밝다."],"title":"퇴적암 표본 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_challenge#5','sci',5,1,'u1','L04','g5_1_sci_u1_L04_challenge','lesson_challenge','SC5-1-u1-C14',3,'mc','auto','퇴적암 표본을 관찰하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X23']::text[],false,'{"seq":5,"concept":"SC5-1-u1-C14","difficulty":3,"kind":"mc","stem":"퇴적암 표본을 관찰하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"번호 붙임딱지 붙이기 → 손으로 만져 보기 → 돋보기로 보기 → 크기별로 나누기","correct":true},{"t":"크기별로 나누기 → 번호 붙임딱지 붙이기 → 돋보기로 보기 → 손으로 만져 보기","mis":"SC5-1-u1-X23"},{"t":"돋보기로 보기 → 크기별로 나누기 → 손으로 만져 보기 → 번호 붙임딱지 붙이기","mis":"SC5-1-u1-X23"},{"t":"손으로 만져 보기 → 크기별로 나누기 → 번호 붙임딱지 붙이기 → 돋보기로 보기","mis":"SC5-1-u1-X23"}],"explanation":["먼저 번호를 붙여요.","만지고 들여다봐요.","마지막에 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_challenge#6','sci',5,1,'u1','L04','g5_1_sci_u1_L04_challenge','lesson_challenge','SC5-1-u1-C15',3,'ox','auto','퇴적암은 퇴적물이 쌓이자마자 하루 만에 단단한 암석이 돼요.',ARRAY['SC5-1-u1-X21']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C15","difficulty":3,"kind":"ox","stem":"퇴적암은 퇴적물이 쌓이자마자 하루 만에 단단한 암석이 돼요.","answer":"X","reason_options":[{"t":"오랜 시간 눌리고 물에 녹은 물질이 엉겨 붙게 해야 하기 때문에","correct":true},{"t":"퇴적물은 쌓이면 바로 불에 구워지기 때문에","mis":"SC5-1-u1-X21"}],"mis":"SC5-1-u1-X21","explanation":["과정을 떠올려요.","눌리고 엉겨 붙어요.","오래 걸려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_challenge#7','sci',5,1,'u1','L04','g5_1_sci_u1_L04_challenge','lesson_challenge','SC5-1-u1-C12',3,'mc','auto','지층의 층마다 색깔과 두께가 다른 까닭을 퇴적암과 이어 가장 알맞게 설명한 것은 어느 것인가요?',ARRAY['SC5-1-u1-X24','SC5-1-u1-X07','SC5-1-u1-X18']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C12","difficulty":3,"kind":"mc","stem":"지층의 층마다 색깔과 두께가 다른 까닭을 퇴적암과 이어 가장 알맞게 설명한 것은 어느 것인가요?","options":[{"t":"층마다 쌓여 굳은 알갱이가 달라 서로 다른 퇴적암이 되기 때문에","correct":true},{"t":"지층은 퇴적암과 관계없는 암석으로 이루어지기 때문에","mis":"SC5-1-u1-X24"},{"t":"층마다 햇빛을 받은 시간이 다르기 때문에","mis":"SC5-1-u1-X07"},{"t":"층마다 발견된 지역이 다르기 때문에","mis":"SC5-1-u1-X18"}],"explanation":["지층은 무엇으로 이루어졌나요?","퇴적암이에요.","알갱이가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_challenge#8','sci',5,1,'u1','L04','g5_1_sci_u1_L04_challenge','lesson_challenge','SC5-1-u1-C15',4,'mc','auto','퇴적암이 만들어지는 과정을 차례로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X16','SC5-1-u1-X21']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C15","difficulty":4,"kind":"mc","stem":"퇴적암이 만들어지는 과정을 차례로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"퇴적물이 쌓인다 → 눌려 알갱이 사이가 좁아진다 → 물에 녹은 물질이 엉겨 붙게 한다","correct":true},{"t":"물에 녹은 물질이 엉겨 붙게 한다 → 퇴적물이 쌓인다 → 눌려 알갱이 사이가 좁아진다","mis":"SC5-1-u1-X16"},{"t":"퇴적물이 쌓인다 → 불에 구워진다 → 식어서 굳는다","mis":"SC5-1-u1-X21"},{"t":"눌려 알갱이 사이가 좁아진다 → 퇴적물이 쌓인다 → 하루 만에 굳는다","mis":"SC5-1-u1-X21"}],"explanation":["먼저 쌓여야 해요.","눌리고 엉겨 붙어요.","차례를 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_challenge#9','sci',5,1,'u1','L04','g5_1_sci_u1_L04_challenge','lesson_challenge','SC5-1-u1-C13',4,'mc','auto','알갱이 크기가 작은 것부터 차례로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X19']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C13","difficulty":4,"kind":"mc","stem":"알갱이 크기가 작은 것부터 차례로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"이암 → 사암 → 역암","correct":true},{"t":"역암 → 사암 → 이암","mis":"SC5-1-u1-X19"},{"t":"사암 → 이암 → 역암","mis":"SC5-1-u1-X19"},{"t":"이암 → 역암 → 사암","mis":"SC5-1-u1-X19"}],"explanation":["진흙·모래·자갈을 떠올려요.","진흙이 가장 작아요.","이암·사암·역암 순이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L04_challenge#10','sci',5,1,'u1','L04','g5_1_sci_u1_L04_challenge','lesson_challenge','SC5-1-u1-C13',4,'essay','teacher','관찰 기록의 네 표본을 이암·사암·역암으로 나누고, 그렇게 나눈 근거를 쓰세요. 그리고 1번과 4번을 색깔로 나누면 안 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u1-C13","difficulty":4,"kind":"essay","stem":"관찰 기록의 네 표본을 이암·사암·역암으로 나누고, 그렇게 나눈 근거를 쓰세요. 그리고 1번과 4번을 색깔로 나누면 안 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 1번과 4번은 알갱이가 거의 보이지 않을 만큼 작으므로 이암, 2번은 모래만 한 알갱이가 보이므로 사암, 3번은 자갈 사이에 모래와 진흙이 섞여 있으므로 역암이다. 퇴적암은 암석을 이루는 알갱이의 크기에 따라 분류한다. 1번과 4번은 색깔이 다르지만 알갱이 크기가 같으므로 색깔로 다른 암석이라고 나누면 안 된다.","scoring_points":["네 표본을 바르게 나누었는가","알갱이 크기를 근거로 썼는가","색깔로 나누면 안 되는 까닭을 썼는가"]},"explanation":["알갱이 크기를 읽어요.","셋으로 나눠요.","색깔을 따져요."],"asset":{"type":"passage","lines":["1번 — 만지면 매끈하다. 돋보기로 보아도 알갱이가 거의 보이지 않는다.","2번 — 만지면 까끌까끌하다. 모래만 한 알갱이가 보인다.","3번 — 콩알만 한 자갈 사이에 모래와 진흙이 섞여 있다.","4번 — 1번처럼 매끈하고 알갱이가 거의 보이지 않는다. 색은 1번보다 밝다."],"title":"퇴적암 표본 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_basic#1','sci',5,1,'u1','L05','g5_1_sci_u1_L05_basic','lesson_basic','SC5-1-u1-C16',1,'mc','auto','옛날에 살았던 생물의 몸체나 흔적이 지층 속에 남아 있는 것은 어느 것인가요?',ARRAY['SC5-1-u1-X25','SC5-1-u1-X29']::text[],false,'{"seq":1,"concept":"SC5-1-u1-C16","difficulty":1,"kind":"mc","stem":"옛날에 살았던 생물의 몸체나 흔적이 지층 속에 남아 있는 것은 어느 것인가요?","options":[{"t":"화석","correct":true},{"t":"퇴적물","mis":"SC5-1-u1-X25"},{"t":"사암","mis":"SC5-1-u1-X29"},{"t":"자갈","mis":"SC5-1-u1-X25"}],"explanation":["생물과 관계있어요.","지층 속에 남았어요.","화석이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_basic#2','sci',5,1,'u1','L05','g5_1_sci_u1_L05_basic','lesson_basic','SC5-1-u1-C17',1,'mc','auto','화석의 작은 무늬까지 자세히 볼 때 쓰는 도구는 어느 것인가요?',ARRAY['SC5-1-u1-X28']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C17","difficulty":1,"kind":"mc","stem":"화석의 작은 무늬까지 자세히 볼 때 쓰는 도구는 어느 것인가요?","options":[{"t":"돋보기","correct":true},{"t":"자석","mis":"SC5-1-u1-X28"},{"t":"저울","mis":"SC5-1-u1-X28"},{"t":"망치","mis":"SC5-1-u1-X28"}],"explanation":["크게 보여 줘요.","무늬를 들여다봐요.","돋보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_basic#3','sci',5,1,'u1','L05','g5_1_sci_u1_L05_basic','lesson_basic','SC5-1-u1-C16',1,'ox','auto','동물의 발자국도 화석이 될 수 있어요.',ARRAY['SC5-1-u1-X25']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C16","difficulty":1,"kind":"ox","stem":"동물의 발자국도 화석이 될 수 있어요.","answer":"O","reason_options":[{"t":"생물이 생활한 흔적도 지층 속에 남으면 화석이 되기 때문에","correct":true},{"t":"발자국은 뼈처럼 단단한 몸체이기 때문에","mis":"SC5-1-u1-X25"}],"mis":"SC5-1-u1-X25","explanation":["몸체만 화석일까요?","흔적도 화석이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_basic#4','sci',5,1,'u1','L05','g5_1_sci_u1_L05_basic','lesson_basic','SC5-1-u1-C17',1,'sa','auto','「나뭇잎·고사리·솔방울 화석처럼 식물이 남은 화석을 □□ 화석이라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u1-C17","difficulty":1,"kind":"sa","stem":"「나뭇잎·고사리·솔방울 화석처럼 식물이 남은 화석을 □□ 화석이라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["식물"],"explanation":["나뭇잎은 무엇인가요?","동물이 아니에요.","식물 화석이에요."],"mis":"SC5-1-u1-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_basic#5','sci',5,1,'u1','L05','g5_1_sci_u1_L05_basic','lesson_basic','SC5-1-u1-C17',2,'match','auto','화석과 관찰한 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u1-C17","difficulty":2,"kind":"match","stem":"화석과 관찰한 모습을 알맞게 이으세요.","pairs":[{"l":"삼엽충 화석","r":"마디가 많은 벌레처럼 보인다"},{"l":"나뭇잎 화석","r":"가늘게 뻗은 잎맥이 보인다"},{"l":"공룡알 화석","r":"달걀처럼 생긴 것 여러 개가 모여 있다"},{"l":"새 발자국 화석","r":"발가락이 펼쳐진 자국이 있다"}],"mis":"SC5-1-u1-X27","explanation":["모습을 떠올려요.","마디·잎맥·알·발가락이에요.","하나씩 짝지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_basic#6','sci',5,1,'u1','L05','g5_1_sci_u1_L05_basic','lesson_basic','SC5-1-u1-C16',2,'mc','auto','생물의 몸체가 아니라 흔적이 남은 화석은 어느 것인가요?',ARRAY['SC5-1-u1-X25']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C16","difficulty":2,"kind":"mc","stem":"생물의 몸체가 아니라 흔적이 남은 화석은 어느 것인가요?","options":[{"t":"공룡 발자국 화석","correct":true},{"t":"물고기 뼈 화석","mis":"SC5-1-u1-X25"},{"t":"나뭇잎 화석","mis":"SC5-1-u1-X25"},{"t":"조개껍데기 화석","mis":"SC5-1-u1-X25"}],"explanation":["몸이 남았나요, 자국이 남았나요?","발자국은 자국이에요.","공룡 발자국 화석이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_basic#7','sci',5,1,'u1','L05','g5_1_sci_u1_L05_basic','lesson_basic','SC5-1-u1-C18',2,'mc','auto','화석이 주로 발견되는 암석은 어느 것인가요?',ARRAY['SC5-1-u1-X29']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C18","difficulty":2,"kind":"mc","stem":"화석이 주로 발견되는 암석은 어느 것인가요?","options":[{"t":"퇴적암","correct":true},{"t":"화성암","mis":"SC5-1-u1-X29"},{"t":"얼음","mis":"SC5-1-u1-X29"},{"t":"모든 암석에서 똑같이 많이 발견된다","mis":"SC5-1-u1-X29"}],"explanation":["퇴적물이 쌓일 때 묻혀요.","쌓여 굳은 암석이에요.","퇴적암이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_basic#8','sci',5,1,'u1','L05','g5_1_sci_u1_L05_basic','lesson_basic','SC5-1-u1-C17',2,'ox','auto','화석은 모두 맨눈으로 잘 보일 만큼 커요.',ARRAY['SC5-1-u1-X26']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C17","difficulty":2,"kind":"ox","stem":"화석은 모두 맨눈으로 잘 보일 만큼 커요.","answer":"X","reason_options":[{"t":"맨눈으로 보이지 않을 만큼 작은 화석도 있기 때문에","correct":true},{"t":"공룡처럼 큰 동물만 화석이 되기 때문에","mis":"SC5-1-u1-X26"}],"mis":"SC5-1-u1-X26","explanation":["크기를 떠올려요.","아주 작은 화석도 있어요.","크기가 다양해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_basic#9','sci',5,1,'u1','L05','g5_1_sci_u1_L05_basic','lesson_basic','SC5-1-u1-C17',2,'error','auto','가상 현실(VR) 자료를 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X28','SC5-1-u1-X26']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C17","difficulty":2,"kind":"error","stem":"가상 현실(VR) 자료를 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤호 — 「어지러워도 끝까지 참고 봐야 해.」","correct":true,"mis_target":"SC5-1-u1-X28"},{"t":"채린 — 「기기에서 열이 나면 멈추고 선생님께 알리자.」","mis":"SC5-1-u1-X28"},{"t":"지후 — 「화석 사진을 친구들과 함께 보자.」","mis":"SC5-1-u1-X26"}],"explanation":["안전을 떠올려요.","어지러우면 쉬어요.","윤호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_basic#10','sci',5,1,'u1','L05','g5_1_sci_u1_L05_basic','lesson_basic','SC5-1-u1-C18',3,'mc','auto','화석이 주로 퇴적암에서 발견되는 까닭은 어느 것인가요?',ARRAY['SC5-1-u1-X29','SC5-1-u1-X25']::text[],false,'{"seq":10,"concept":"SC5-1-u1-C18","difficulty":3,"kind":"mc","stem":"화석이 주로 퇴적암에서 발견되는 까닭은 어느 것인가요?","options":[{"t":"퇴적물이 쌓일 때 생물이 함께 묻혀 굳어졌기 때문에","correct":true},{"t":"뜨거운 것이 식으면서 생물을 감쌌기 때문에","mis":"SC5-1-u1-X29"},{"t":"퇴적암의 색깔이 밝기 때문에","mis":"SC5-1-u1-X29"},{"t":"퇴적암에는 몸체만 남기 때문에","mis":"SC5-1-u1-X25"}],"explanation":["퇴적암은 어떻게 생기나요?","쌓여서 굳어요.","함께 묻혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_challenge#1','sci',5,1,'u1','L05','g5_1_sci_u1_L05_challenge','lesson_challenge','SC5-1-u1-C17',2,'sa','auto','관찰 기록에서 동물 화석은 ㄱ과 무엇인가요? (기호 하나)','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u1-C17","difficulty":2,"kind":"sa","stem":"관찰 기록에서 동물 화석은 ㄱ과 무엇인가요? (기호 하나)","answer":["ㅁ"],"explanation":["둥글게 말린 모양이에요.","암모나이트예요.","ㅁ이에요."],"asset":{"type":"passage","lines":["ㄱ — 마디가 많은 벌레처럼 보인다.","ㄴ — 가늘게 뻗은 잎맥이 보인다.","ㄷ — 발가락이 펼쳐진 작은 자국이 남아 있다.","ㄹ — 달걀처럼 생긴 것 여러 개가 모여 있다.","ㅁ — 둥글게 말린 모양이다."],"title":"화석 표본 관찰 기록"},"mis":"SC5-1-u1-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_challenge#2','sci',5,1,'u1','L05','g5_1_sci_u1_L05_challenge','lesson_challenge','SC5-1-u1-C16',2,'mc','auto','관찰 기록에서 흔적이 남은 화석끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X25','SC5-1-u1-X27']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C16","difficulty":2,"kind":"mc","stem":"관찰 기록에서 흔적이 남은 화석끼리 묶은 것은 어느 것인가요?","options":[{"t":"ㄷ, ㄹ","correct":true},{"t":"ㄱ, ㄴ","mis":"SC5-1-u1-X25"},{"t":"ㄴ, ㅁ","mis":"SC5-1-u1-X25"},{"t":"ㄱ, ㅁ","mis":"SC5-1-u1-X27"}],"explanation":["발자국과 알을 찾아요.","생활한 흔적이에요.","ㄷ과 ㄹ이에요."],"asset":{"type":"passage","lines":["ㄱ — 마디가 많은 벌레처럼 보인다.","ㄴ — 가늘게 뻗은 잎맥이 보인다.","ㄷ — 발가락이 펼쳐진 작은 자국이 남아 있다.","ㄹ — 달걀처럼 생긴 것 여러 개가 모여 있다.","ㅁ — 둥글게 말린 모양이다."],"title":"화석 표본 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_challenge#3','sci',5,1,'u1','L05','g5_1_sci_u1_L05_challenge','lesson_challenge','SC5-1-u1-C16',3,'match','auto','화석에 남은 것을 몸체와 흔적으로 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u1-C16","difficulty":3,"kind":"match","stem":"화석에 남은 것을 몸체와 흔적으로 알맞게 이으세요.","pairs":[{"l":"물고기의 뼈","r":"몸체가 남은 화석"},{"l":"동물의 배설물","r":"흔적이 남은 화석"},{"l":"나뭇잎의 잎맥","r":"몸체가 남은 잎 화석"}],"mis":"SC5-1-u1-X25","explanation":["생물의 몸인가요?","배설물은 흔적이에요.","하나씩 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_challenge#4','sci',5,1,'u1','L05','g5_1_sci_u1_L05_challenge','lesson_challenge','SC5-1-u1-C17',3,'error','auto','화석에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X27']::text[],false,'{"seq":4,"concept":"SC5-1-u1-C17","difficulty":3,"kind":"error","stem":"화석에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세아 — 「식물은 말랑해서 화석이 될 수 없어.」","correct":true,"mis_target":"SC5-1-u1-X27"},{"t":"도윤 — 「고사리 화석에는 갈라진 잎 모양이 남아 있어.」","mis":"SC5-1-u1-X27"},{"t":"나래 — 「솔방울 화석도 있어.」","mis":"SC5-1-u1-X27"}],"explanation":["식물 화석을 떠올려요.","잎맥·고사리·솔방울이 있어요.","세아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_challenge#5','sci',5,1,'u1','L05','g5_1_sci_u1_L05_challenge','lesson_challenge','SC5-1-u1-C18',3,'ox','auto','화성암은 뜨거운 것이 식어 굳은 암석이라 화석이 주로 발견되지 않아요.',ARRAY['SC5-1-u1-X29']::text[],false,'{"seq":5,"concept":"SC5-1-u1-C18","difficulty":3,"kind":"ox","stem":"화성암은 뜨거운 것이 식어 굳은 암석이라 화석이 주로 발견되지 않아요.","answer":"O","reason_options":[{"t":"생물이 퇴적물과 함께 묻혀 굳는 퇴적암과 만들어지는 과정이 다르기 때문에","correct":true},{"t":"화성암은 색깔이 어두워 화석이 숨어 보이지 않기 때문에","mis":"SC5-1-u1-X29"}],"mis":"SC5-1-u1-X29","explanation":["두 암석을 견줘요.","만들어지는 과정이 달라요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_challenge#6','sci',5,1,'u1','L05','g5_1_sci_u1_L05_challenge','lesson_challenge','SC5-1-u1-C17',3,'mc','auto','화석을 관찰하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X28']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C17","difficulty":3,"kind":"mc","stem":"화석을 관찰하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"흰 종이에 표본 놓기 → 돋보기로 모양·크기·무늬 보기 → 몸체인지 흔적인지 살피기 → VR 자료 찾아 나누기","correct":true},{"t":"VR 자료 찾아 나누기 → 흰 종이에 표본 놓기 → 몸체인지 흔적인지 살피기 → 돋보기로 모양·크기·무늬 보기","mis":"SC5-1-u1-X28"},{"t":"몸체인지 흔적인지 살피기 → VR 자료 찾아 나누기 → 흰 종이에 표본 놓기 → 돋보기로 모양·크기·무늬 보기","mis":"SC5-1-u1-X28"},{"t":"돋보기로 모양·크기·무늬 보기 → VR 자료 찾아 나누기 → 흰 종이에 표본 놓기 → 몸체인지 흔적인지 살피기","mis":"SC5-1-u1-X28"}],"explanation":["먼저 표본을 놓아요.","자세히 본 뒤 살펴요.","마지막에 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_challenge#7','sci',5,1,'u1','L05','g5_1_sci_u1_L05_challenge','lesson_challenge','SC5-1-u1-C17',3,'mc','auto','관찰 기록의 ㄱ~ㅁ 가운데 식물 화석은 어느 것인가요?',ARRAY['SC5-1-u1-X27','SC5-1-u1-X25']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C17","difficulty":3,"kind":"mc","stem":"관찰 기록의 ㄱ~ㅁ 가운데 식물 화석은 어느 것인가요?","options":[{"t":"ㄴ","correct":true},{"t":"ㄱ","mis":"SC5-1-u1-X27"},{"t":"ㄷ","mis":"SC5-1-u1-X25"},{"t":"ㄹ","mis":"SC5-1-u1-X25"}],"explanation":["식물의 모습을 찾아요.","잎맥이 보여요.","ㄴ이에요."],"asset":{"type":"passage","lines":["ㄱ — 마디가 많은 벌레처럼 보인다.","ㄴ — 가늘게 뻗은 잎맥이 보인다.","ㄷ — 발가락이 펼쳐진 작은 자국이 남아 있다.","ㄹ — 달걀처럼 생긴 것 여러 개가 모여 있다.","ㅁ — 둥글게 말린 모양이다."],"title":"화석 표본 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_challenge#8','sci',5,1,'u1','L05','g5_1_sci_u1_L05_challenge','lesson_challenge','SC5-1-u1-C16',4,'mc','auto','「화석은 생물의 몸체만 남은 것이다」라는 말을 바로잡을 때 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X25','SC5-1-u1-X26','SC5-1-u1-X04']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C16","difficulty":4,"kind":"mc","stem":"「화석은 생물의 몸체만 남은 것이다」라는 말을 바로잡을 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"발자국·배설물·알처럼 생물이 생활한 흔적도 지층 속에 남으면 화석이다","correct":true},{"t":"맞는 말이다 — 발자국은 생물이 아니라 화석이 아니다","mis":"SC5-1-u1-X25"},{"t":"큰 공룡의 몸체만 화석이고 작은 생물은 화석이 아니다","mis":"SC5-1-u1-X26"},{"t":"땅속에서 나온 것은 모두 화석이다","mis":"SC5-1-u1-X04"}],"explanation":["흔적을 떠올려요.","발자국도 화석이에요.","흔적도 화석이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_challenge#9','sci',5,1,'u1','L05','g5_1_sci_u1_L05_challenge','lesson_challenge','SC5-1-u1-C18',4,'mc','auto','퇴적암과 화성암 가운데 화석을 찾아보기에 알맞은 곳과 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X29','SC5-1-u1-X18']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C18","difficulty":4,"kind":"mc","stem":"퇴적암과 화성암 가운데 화석을 찾아보기에 알맞은 곳과 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"퇴적암 — 퇴적물이 쌓일 때 그 속의 생물이 함께 묻혀 굳기 때문이다","correct":true},{"t":"화성암 — 뜨거운 것이 생물을 감싸 그대로 굳히기 때문이다","mis":"SC5-1-u1-X29"},{"t":"어느 암석이든 똑같다 — 화석은 모든 돌에 들어 있다","mis":"SC5-1-u1-X29"},{"t":"퇴적암 — 색깔이 밝아 화석이 잘 보이기 때문이다","mis":"SC5-1-u1-X18"}],"explanation":["만들어지는 과정을 떠올려요.","쌓일 때 묻혀요.","퇴적암이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L05_challenge#10','sci',5,1,'u1','L05','g5_1_sci_u1_L05_challenge','lesson_challenge','SC5-1-u1-C16',4,'essay','teacher','관찰 기록의 다섯 화석을 동물 화석·식물 화석·흔적 화석으로 나누고, 이 활동으로 알게 된 화석의 뜻을 「몸체」와 「흔적」이라는 말을 넣어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u1-C16","difficulty":4,"kind":"essay","stem":"관찰 기록의 다섯 화석을 동물 화석·식물 화석·흔적 화석으로 나누고, 이 활동으로 알게 된 화석의 뜻을 「몸체」와 「흔적」이라는 말을 넣어 쓰세요.","answer_guide":{"answer":"예: ㄱ(삼엽충)과 ㅁ(암모나이트)은 동물 화석, ㄴ(나뭇잎)은 식물 화석, ㄷ(새 발자국)과 ㄹ(공룡알)은 흔적 화석이다. 화석은 옛날에 살았던 생물의 몸체나 흔적이 지층 속에 남아 있는 것이다. 몸체뿐만 아니라 발자국이나 알처럼 생물이 생활한 흔적도 화석이 된다.","scoring_points":["세 무리로 바르게 나누었는가","몸체와 흔적을 넣어 화석의 뜻을 썼는가","흔적도 화석임을 썼는가"]},"explanation":["기록을 하나씩 읽어요.","셋으로 나눠요.","뜻을 써요."],"asset":{"type":"passage","lines":["ㄱ — 마디가 많은 벌레처럼 보인다.","ㄴ — 가늘게 뻗은 잎맥이 보인다.","ㄷ — 발가락이 펼쳐진 작은 자국이 남아 있다.","ㄹ — 달걀처럼 생긴 것 여러 개가 모여 있다.","ㅁ — 둥글게 말린 모양이다."],"title":"화석 표본 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_basic#1','sci',5,1,'u1','L06','g5_1_sci_u1_L06_basic','lesson_basic','SC5-1-u1-C19',1,'mc','auto','찰흙 위에 조개껍데기를 눌렀다 뗀 다음에 할 일은 어느 것인가요?',ARRAY['SC5-1-u1-X30']::text[],false,'{"seq":1,"concept":"SC5-1-u1-C19","difficulty":1,"kind":"mc","stem":"찰흙 위에 조개껍데기를 눌렀다 뗀 다음에 할 일은 어느 것인가요?","options":[{"t":"자국이 모두 덮이도록 물을 붓는다","correct":true},{"t":"찰흙을 불에 굽는다","mis":"SC5-1-u1-X30"},{"t":"찰흙을 잘게 자른다","mis":"SC5-1-u1-X30"},{"t":"비닐봉지를 들어 올려 꺼낸다","mis":"SC5-1-u1-X30"}],"explanation":["자국이 생겼어요.","자국을 덮어요.","물을 부어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_basic#2','sci',5,1,'u1','L06','g5_1_sci_u1_L06_basic','lesson_basic','SC5-1-u1-C20',1,'mc','auto','화석이 되려면 생물의 몸체나 흔적 위로 무엇이 빠르게 쌓여야 하나요?',ARRAY['SC5-1-u1-X32']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C20","difficulty":1,"kind":"mc","stem":"화석이 되려면 생물의 몸체나 흔적 위로 무엇이 빠르게 쌓여야 하나요?","options":[{"t":"퇴적물","correct":true},{"t":"공기","mis":"SC5-1-u1-X32"},{"t":"소금","mis":"SC5-1-u1-X32"},{"t":"나뭇잎","mis":"SC5-1-u1-X32"}],"explanation":["빠르게 덮어야 해요.","지층을 만드는 것이에요.","퇴적물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_basic#3','sci',5,1,'u1','L06','g5_1_sci_u1_L06_basic','lesson_basic','SC5-1-u1-C20',1,'ox','auto','동물의 뼈나 이빨처럼 단단한 부분은 화석이 되기 쉬워요.',ARRAY['SC5-1-u1-X33']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C20","difficulty":1,"kind":"ox","stem":"동물의 뼈나 이빨처럼 단단한 부분은 화석이 되기 쉬워요.","answer":"O","reason_options":[{"t":"단단하거나 질긴 부분은 오래 남을 수 있기 때문에","correct":true},{"t":"단단한 부분은 퇴적물 없이도 저절로 화석이 되기 때문에","mis":"SC5-1-u1-X33"}],"mis":"SC5-1-u1-X33","explanation":["잘 남는 부분을 떠올려요.","단단하고 질긴 부분이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_basic#4','sci',5,1,'u1','L06','g5_1_sci_u1_L06_basic','lesson_basic','SC5-1-u1-C19',1,'sa','auto','「화석 모형에서 조개껍데기는 옛날에 살았던 □□을 나타냅니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u1-C19","difficulty":1,"kind":"sa","stem":"「화석 모형에서 조개껍데기는 옛날에 살았던 □□을 나타냅니다.」 □□에 알맞은 말을 쓰세요.","answer":["생물"],"explanation":["조개는 살아 있던 것이에요.","두 글자예요.","생물이에요."],"mis":"SC5-1-u1-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_basic#5','sci',5,1,'u1','L06','g5_1_sci_u1_L06_basic','lesson_basic','SC5-1-u1-C19',2,'match','auto','화석 모형의 재료와 실제를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u1-C19","difficulty":2,"kind":"match","stem":"화석 모형의 재료와 실제를 알맞게 이으세요.","pairs":[{"l":"찰흙","r":"퇴적물이 쌓여 흔적이 남는 곳"},{"l":"조개껍데기","r":"옛날에 살았던 생물"},{"l":"물과 석고 가루","r":"흔적 위에 쌓이는 퇴적물"},{"l":"굳은 석고 속 모형","r":"지층 속에 만들어진 화석"}],"mis":"SC5-1-u1-X30","explanation":["모형을 실제와 견줘요.","조개는 생물이에요.","석고는 위에 쌓이는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_basic#6','sci',5,1,'u1','L06','g5_1_sci_u1_L06_basic','lesson_basic','SC5-1-u1-C20',2,'mc','auto','화석이 되기 어려운 부분은 어느 것인가요?',ARRAY['SC5-1-u1-X33']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C20","difficulty":2,"kind":"mc","stem":"화석이 되기 어려운 부분은 어느 것인가요?","options":[{"t":"말랑말랑한 살","correct":true},{"t":"동물의 이빨","mis":"SC5-1-u1-X33"},{"t":"조개껍데기","mis":"SC5-1-u1-X33"},{"t":"질긴 식물의 줄기","mis":"SC5-1-u1-X33"}],"explanation":["금방 없어지는 부분이에요.","물렁해요.","말랑말랑한 살이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_basic#7','sci',5,1,'u1','L06','g5_1_sci_u1_L06_basic','lesson_basic','SC5-1-u1-C19',2,'ox','auto','실제 화석도 모형처럼 몇 분이면 만들어져요.',ARRAY['SC5-1-u1-X31']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C19","difficulty":2,"kind":"ox","stem":"실제 화석도 모형처럼 몇 분이면 만들어져요.","answer":"X","reason_options":[{"t":"실제 화석은 지층이 굳어지고 발견되기까지 아주 오랜 시간이 걸리기 때문에","correct":true},{"t":"석고만 있으면 실제 화석도 금방 만들 수 있기 때문에","mis":"SC5-1-u1-X31"}],"mis":"SC5-1-u1-X31","explanation":["모형과 실제를 견줘요.","실제는 오래 걸려요.","몇 분이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_basic#8','sci',5,1,'u1','L06','g5_1_sci_u1_L06_basic','lesson_basic','SC5-1-u1-C20',2,'mc','auto','지층 속에 있던 화석이 우리에게 발견되는 까닭은 어느 것인가요?',ARRAY['SC5-1-u1-X34','SC5-1-u1-X32']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C20","difficulty":2,"kind":"mc","stem":"지층 속에 있던 화석이 우리에게 발견되는 까닭은 어느 것인가요?","options":[{"t":"물 밖으로 드러난 지층이 깎이면서 화석이 드러나기 때문에","correct":true},{"t":"화석이 스스로 땅 위로 올라오기 때문에","mis":"SC5-1-u1-X34"},{"t":"지층이 쌓일 때 화석이 맨 위로 떠오르기 때문에","mis":"SC5-1-u1-X34"},{"t":"생물이 죽으면 모두 땅 위에 화석으로 남기 때문에","mis":"SC5-1-u1-X32"}],"explanation":["지층이 어떻게 되나요?","드러나 깎여요.","깎여서 발견돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_basic#9','sci',5,1,'u1','L06','g5_1_sci_u1_L06_basic','lesson_basic','SC5-1-u1-C19',2,'error','auto','화석 모형을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X30']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C19","difficulty":2,"kind":"error","stem":"화석 모형을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「석고 가루를 입으로 불어 날려 보자.」","correct":true,"mis_target":"SC5-1-u1-X30"},{"t":"다은 — 「석고 가루는 선생님 안내에 따라 다루자.」","mis":"SC5-1-u1-X30"},{"t":"로운 — 「쓰고 난 찰흙은 안내에 따라 처리하자.」","mis":"SC5-1-u1-X30"}],"explanation":["석고 가루는 날려요.","안내에 따라요.","하준이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_basic#10','sci',5,1,'u1','L06','g5_1_sci_u1_L06_basic','lesson_basic','SC5-1-u1-C20',3,'mc','auto','벌레가 기어간 자국이 화석이 된 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X30','SC5-1-u1-X32','SC5-1-u1-X44']::text[],false,'{"seq":10,"concept":"SC5-1-u1-C20","difficulty":3,"kind":"mc","stem":"벌레가 기어간 자국이 화석이 된 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자국 위로 퇴적물이 빠르게 쌓여 굳어졌기 때문에","correct":true},{"t":"자국이 불에 구워져 굳었기 때문에","mis":"SC5-1-u1-X30"},{"t":"자국이 물에 씻겨 내려갔기 때문에","mis":"SC5-1-u1-X32"},{"t":"벌레가 아주 세게 눌러 돌에 찍었기 때문에","mis":"SC5-1-u1-X44"}],"explanation":["흔적이 어떻게 남았을까요?","빠르게 덮였어요.","퇴적물이 쌓여 굳었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_challenge#1','sci',5,1,'u1','L06','g5_1_sci_u1_L06_challenge','lesson_challenge','SC5-1-u1-C19',2,'sa','auto','「물 표면이 보이지 않을 정도로 넣는 가루는 □□ 가루입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u1-C19","difficulty":2,"kind":"sa","stem":"「물 표면이 보이지 않을 정도로 넣는 가루는 □□ 가루입니다.」 □□에 알맞은 말을 쓰세요.","answer":["석고"],"explanation":["굳으면 단단해져요.","두 글자예요.","석고예요."],"mis":"SC5-1-u1-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_challenge#2','sci',5,1,'u1','L06','g5_1_sci_u1_L06_challenge','lesson_challenge','SC5-1-u1-C19',2,'mc','auto','차례가 섞인 ㉠~㉥을 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X30']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C19","difficulty":2,"kind":"mc","stem":"차례가 섞인 ㉠~㉥을 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉢ → ㉠ → ㉤ → ㉣ → ㉡ → ㉥","correct":true},{"t":"㉠ → ㉢ → ㉣ → ㉤ → ㉥ → ㉡","mis":"SC5-1-u1-X30"},{"t":"㉢ → ㉣ → ㉠ → ㉤ → ㉡ → ㉥","mis":"SC5-1-u1-X30"},{"t":"㉢ → ㉠ → ㉣ → ㉤ → ㉥ → ㉡","mis":"SC5-1-u1-X30"}],"explanation":["찰흙부터 펴요.","자국 → 물 → 석고예요.","굳으면 꺼내 떼어 내요."],"asset":{"type":"passage","lines":["㉠ 찰흙 위에 조개껍데기를 눌렀다가 떼어 낸다.","㉡ 석고가 굳으면 비닐봉지를 들어 올려 꺼낸다.","㉢ 투명한 그릇에 비닐봉지를 펼치고 찰흙을 평평하게 편다.","㉣ 물 표면이 보이지 않을 정도로 석고 가루를 넣는다.","㉤ 자국이 모두 덮이도록 물을 붓는다.","㉥ 찰흙과 석고를 떼어 내어 관찰한다."],"title":"화석 모형 만들기(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_challenge#3','sci',5,1,'u1','L06','g5_1_sci_u1_L06_challenge','lesson_challenge','SC5-1-u1-C20',3,'mc','auto','화석이 만들어지는 과정을 차례로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X34','SC5-1-u1-X31']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C20","difficulty":3,"kind":"mc","stem":"화석이 만들어지는 과정을 차례로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"생물이 가라앉는다 → 퇴적물이 빠르게 쌓인다 → 지층이 되고 화석이 된다 → 지층이 깎여 발견된다","correct":true},{"t":"퇴적물이 빠르게 쌓인다 → 지층이 깎여 발견된다 → 생물이 가라앉는다 → 화석이 된다","mis":"SC5-1-u1-X34"},{"t":"생물이 가라앉는다 → 지층이 깎여 발견된다 → 퇴적물이 빠르게 쌓인다 → 화석이 된다","mis":"SC5-1-u1-X34"},{"t":"생물이 가라앉는다 → 그대로 두면 며칠 뒤 화석이 된다 → 지층이 깎여 발견된다 → 퇴적물이 쌓인다","mis":"SC5-1-u1-X31"}],"explanation":["먼저 가라앉아요.","덮이고 굳어요.","마지막에 발견돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_challenge#4','sci',5,1,'u1','L06','g5_1_sci_u1_L06_challenge','lesson_challenge','SC5-1-u1-C20',3,'error','auto','화석이 만들어지는 조건을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X32','SC5-1-u1-X33']::text[],false,'{"seq":4,"concept":"SC5-1-u1-C20","difficulty":3,"kind":"error","stem":"화석이 만들어지는 조건을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「생물이 죽으면 모두 화석이 돼.」","correct":true,"mis_target":"SC5-1-u1-X32"},{"t":"보라 — 「퇴적물이 빠르게 덮어야 화석이 될 수 있어.」","mis":"SC5-1-u1-X32"},{"t":"태오 — 「질긴 잎도 화석이 되기 쉬워.」","mis":"SC5-1-u1-X33"}],"explanation":["모두 화석이 될까요?","조건이 있어요.","은우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_challenge#5','sci',5,1,'u1','L06','g5_1_sci_u1_L06_challenge','lesson_challenge','SC5-1-u1-C19',3,'match','auto','화석 모형과 실제 화석을 견준 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u1-C19","difficulty":3,"kind":"match","stem":"화석 모형과 실제 화석을 견준 내용을 알맞게 이으세요.","pairs":[{"l":"생물의 흔적이 남는다","r":"모형과 실제의 공통점"},{"l":"몇 분 만에 완성된다","r":"모형만의 특징"},{"l":"지층 속에서 아주 오랜 시간에 걸쳐 만들어진다","r":"실제 화석만의 특징"}],"mis":"SC5-1-u1-X31","explanation":["닮은 점을 찾아요.","시간이 달라요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_challenge#6','sci',5,1,'u1','L06','g5_1_sci_u1_L06_challenge','lesson_challenge','SC5-1-u1-C20',3,'ox','auto','공룡 발자국 화석은 공룡이 단단한 바위를 아주 세게 밟아서 생긴 거예요.',ARRAY['SC5-1-u1-X44']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C20","difficulty":3,"kind":"ox","stem":"공룡 발자국 화석은 공룡이 단단한 바위를 아주 세게 밟아서 생긴 거예요.","answer":"X","reason_options":[{"t":"그때는 무른 진흙이나 모래였고 그 위로 퇴적물이 쌓여 굳어졌기 때문에","correct":true},{"t":"공룡은 몸무게가 무거워 바위도 쉽게 눌렸기 때문에","mis":"SC5-1-u1-X44"}],"mis":"SC5-1-u1-X44","explanation":["그때 땅은 어땠을까요?","무른 진흙이었어요.","덮이고 굳었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_challenge#7','sci',5,1,'u1','L06','g5_1_sci_u1_L06_challenge','lesson_challenge','SC5-1-u1-C20',3,'mc','auto','물고기가 죽어 호수 바닥에 가라앉았지만 오랫동안 아무것도 덮이지 않았어요. 가장 알맞은 생각은 어느 것인가요?',ARRAY['SC5-1-u1-X32','SC5-1-u1-X33','SC5-1-u1-X31']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C20","difficulty":3,"kind":"mc","stem":"물고기가 죽어 호수 바닥에 가라앉았지만 오랫동안 아무것도 덮이지 않았어요. 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"퇴적물이 빠르게 덮지 않아 화석으로 남기 어렵다","correct":true},{"t":"죽었으니 언제나 화석이 된다","mis":"SC5-1-u1-X32"},{"t":"살이 말랑하니 오히려 더 잘 남는다","mis":"SC5-1-u1-X33"},{"t":"며칠 뒤면 저절로 화석이 된다","mis":"SC5-1-u1-X31"}],"explanation":["화석이 될 조건을 떠올려요.","빠르게 덮여야 해요.","남기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_challenge#8','sci',5,1,'u1','L06','g5_1_sci_u1_L06_challenge','lesson_challenge','SC5-1-u1-C19',4,'mc','auto','화석 모형에서 물과 석고 가루를 부은 일은 실제로 어떤 일을 나타내나요?',ARRAY['SC5-1-u1-X30','SC5-1-u1-X34']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C19","difficulty":4,"kind":"mc","stem":"화석 모형에서 물과 석고 가루를 부은 일은 실제로 어떤 일을 나타내나요?","options":[{"t":"생물의 흔적 위로 퇴적물이 쌓이는 일","correct":true},{"t":"생물이 바다나 호수에 가라앉는 일","mis":"SC5-1-u1-X30"},{"t":"지층이 깎여 화석이 발견되는 일","mis":"SC5-1-u1-X34"},{"t":"옛날에 살았던 생물 자체","mis":"SC5-1-u1-X30"}],"explanation":["자국 위를 덮었어요.","위에 쌓이는 것이에요.","퇴적물이 쌓이는 일이에요."],"asset":{"type":"passage","lines":["㉠ 찰흙 위에 조개껍데기를 눌렀다가 떼어 낸다.","㉡ 석고가 굳으면 비닐봉지를 들어 올려 꺼낸다.","㉢ 투명한 그릇에 비닐봉지를 펼치고 찰흙을 평평하게 편다.","㉣ 물 표면이 보이지 않을 정도로 석고 가루를 넣는다.","㉤ 자국이 모두 덮이도록 물을 붓는다.","㉥ 찰흙과 석고를 떼어 내어 관찰한다."],"title":"화석 모형 만들기(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_challenge#9','sci',5,1,'u1','L06','g5_1_sci_u1_L06_challenge','lesson_challenge','SC5-1-u1-C20',4,'mc','auto','조개는 껍데기가 단단하고 해파리는 몸이 물렁해요. 화석으로 더 잘 남을 것과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X33','SC5-1-u1-X32','SC5-1-u1-X26']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C20","difficulty":4,"kind":"mc","stem":"조개는 껍데기가 단단하고 해파리는 몸이 물렁해요. 화석으로 더 잘 남을 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"조개 — 단단한 껍데기는 오래 남을 수 있어서","correct":true},{"t":"해파리 — 물렁한 몸이 퇴적물에 잘 찍혀서","mis":"SC5-1-u1-X33"},{"t":"둘 다 똑같다 — 죽으면 모두 화석이 되어서","mis":"SC5-1-u1-X32"},{"t":"해파리 — 크기가 커서 큰 생물만 화석이 되어서","mis":"SC5-1-u1-X26"}],"explanation":["잘 남는 부분을 떠올려요.","단단하거나 질긴 부분이에요.","조개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L06_challenge#10','sci',5,1,'u1','L06','g5_1_sci_u1_L06_challenge','lesson_challenge','SC5-1-u1-C20',4,'essay','teacher','조개 화석 모형을 만든 과정과 실제 조개 화석이 만들어지는 과정을 짝지어 설명하고, 모형과 실제의 차이점 한 가지와 화석이 되려면 필요한 조건 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u1-C20","difficulty":4,"kind":"essay","stem":"조개 화석 모형을 만든 과정과 실제 조개 화석이 만들어지는 과정을 짝지어 설명하고, 모형과 실제의 차이점 한 가지와 화석이 되려면 필요한 조건 두 가지를 쓰세요.","answer_guide":{"answer":"예: 찰흙에 조개껍데기를 눌렀다 뗀 것은 생물의 흔적이 퇴적물에 남는 것과 같고, 물과 석고 가루를 부은 것은 그 위로 퇴적물이 쌓이는 것과 같다. 석고가 굳어 그 속에 화석 모형이 만들어진 것처럼 실제로는 지층이 굳어지고 그 속에 화석이 만들어진다. 모형은 몇 분이면 완성되지만 실제 화석은 아주 오랜 시간이 걸린다. 화석이 되려면 생물의 몸체나 흔적 위로 퇴적물이 빠르게 쌓여야 하고, 뼈나 껍데기처럼 단단하거나 질긴 부분이 있으면 화석이 되기 쉽다.","scoring_points":["모형과 실제를 짝지어 설명했는가","시간의 차이를 썼는가","빠르게 쌓임·단단하거나 질긴 부분 두 조건을 썼는가"]},"explanation":["모형 과정을 떠올려요.","실제와 짝지어요.","조건 두 가지를 써요."],"asset":{"type":"passage","lines":["㉠ 찰흙 위에 조개껍데기를 눌렀다가 떼어 낸다.","㉡ 석고가 굳으면 비닐봉지를 들어 올려 꺼낸다.","㉢ 투명한 그릇에 비닐봉지를 펼치고 찰흙을 평평하게 편다.","㉣ 물 표면이 보이지 않을 정도로 석고 가루를 넣는다.","㉤ 자국이 모두 덮이도록 물을 붓는다.","㉥ 찰흙과 석고를 떼어 내어 관찰한다."],"title":"화석 모형 만들기(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_basic#1','sci',5,1,'u1','L07','g5_1_sci_u1_L07_basic','lesson_basic','SC5-1-u1-C22',1,'mc','auto','과거에 따뜻하고 깊이가 얕은 바다였음을 알려 주는 화석은 어느 것인가요?',ARRAY['SC5-1-u1-X36']::text[],false,'{"seq":1,"concept":"SC5-1-u1-C22","difficulty":1,"kind":"mc","stem":"과거에 따뜻하고 깊이가 얕은 바다였음을 알려 주는 화석은 어느 것인가요?","options":[{"t":"산호 화석","correct":true},{"t":"고사리 화석","mis":"SC5-1-u1-X36"},{"t":"나뭇잎 화석","mis":"SC5-1-u1-X36"},{"t":"새 발자국 화석","mis":"SC5-1-u1-X36"}],"explanation":["오늘날 얕은 바다에 사는 생물이에요.","가지처럼 뻗었어요.","산호 화석이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_basic#2','sci',5,1,'u1','L07','g5_1_sci_u1_L07_basic','lesson_basic','SC5-1-u1-C21',1,'mc','auto','공룡 발자국 화석으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u1-X35']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C21","difficulty":1,"kind":"mc","stem":"공룡 발자국 화석으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"공룡의 크기나 움직임","correct":true},{"t":"공룡의 몸 색깔","mis":"SC5-1-u1-X35"},{"t":"공룡의 울음소리","mis":"SC5-1-u1-X35"},{"t":"공룡이 태어난 날짜","mis":"SC5-1-u1-X35"}],"explanation":["발자국에 남은 것을 봐요.","크기와 간격이에요.","크기나 움직임이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_basic#3','sci',5,1,'u1','L07','g5_1_sci_u1_L07_basic','lesson_basic','SC5-1-u1-C23',1,'ox','auto','화석이 많이 발견되는 곳을 화석 산지라고 해요.',ARRAY['SC5-1-u1-X38']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C23","difficulty":1,"kind":"ox","stem":"화석이 많이 발견되는 곳을 화석 산지라고 해요.","answer":"O","reason_options":[{"t":"화석이 많이 나오는 곳이어서 그렇게 부르기 때문에","correct":true},{"t":"화석을 만들어 파는 곳이어서 그렇게 부르기 때문에","mis":"SC5-1-u1-X38"}],"mis":"SC5-1-u1-X38","explanation":["이름을 풀어 봐요.","화석이 나오는 땅이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_basic#4','sci',5,1,'u1','L07','g5_1_sci_u1_L07_basic','lesson_basic','SC5-1-u1-C22',1,'sa','auto','「고사리 화석이 나온 곳은 과거에 따뜻하고 □□가 많은 육지였습니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u1-C22","difficulty":1,"kind":"sa","stem":"「고사리 화석이 나온 곳은 과거에 따뜻하고 □□가 많은 육지였습니다.」 □□에 알맞은 말을 쓰세요.","answer":["습기","물기"],"explanation":["고사리가 자라는 곳이에요.","축축해요.","습기예요."],"mis":"SC5-1-u1-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_basic#5','sci',5,1,'u1','L07','g5_1_sci_u1_L07_basic','lesson_basic','SC5-1-u1-C22',2,'match','auto','화석과 알 수 있는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u1-C22","difficulty":2,"kind":"match","stem":"화석과 알 수 있는 것을 알맞게 이으세요.","pairs":[{"l":"산호 화석","r":"따뜻하고 깊이가 얕은 바다"},{"l":"고사리 화석","r":"따뜻하고 습기가 많은 육지"},{"l":"공룡 발자국 화석","r":"공룡의 크기나 움직임"}],"mis":"SC5-1-u1-X36","explanation":["오늘날 사는 곳을 떠올려요.","바다와 육지예요.","발자국은 크기와 움직임이에요."],"asset":{"type":"passage","lines":["산호 — 오늘날 따뜻하고 깊이가 얕은 바다에서 산다.","고사리 — 오늘날 습기가 많은 곳에서 자란다.","조개 — 오늘날 바다나 갯벌에서 산다.","공룡 발자국 — 발자국의 크기와 발자국 사이의 간격이 남아 있다."],"title":"화석과 오늘날 비슷한 생물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_basic#6','sci',5,1,'u1','L07','g5_1_sci_u1_L07_basic','lesson_basic','SC5-1-u1-C22',2,'mc','auto','화석으로 과거 환경을 추리하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X37']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C22","difficulty":2,"kind":"mc","stem":"화석으로 과거 환경을 추리하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"화석이 된 생물과 비슷한 오늘날의 생물이 사는 곳을 살펴본다","correct":true},{"t":"화석의 색깔이 밝은지 어두운지 살펴본다","mis":"SC5-1-u1-X37"},{"t":"오늘날 그 지역의 날씨를 그대로 옛날 날씨라고 본다","mis":"SC5-1-u1-X37"},{"t":"화석의 무게를 재어 본다","mis":"SC5-1-u1-X37"}],"explanation":["오늘날 생물과 견줘요.","사는 곳을 살펴요.","비슷한 생물이 사는 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_basic#7','sci',5,1,'u1','L07','g5_1_sci_u1_L07_basic','lesson_basic','SC5-1-u1-C22',2,'ox','auto','지금 산인 곳은 옛날에도 언제나 산이었어요.',ARRAY['SC5-1-u1-X37']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C22","difficulty":2,"kind":"ox","stem":"지금 산인 곳은 옛날에도 언제나 산이었어요.","answer":"X","reason_options":[{"t":"산에서 바다 생물 화석이 나오기도 하듯 같은 곳도 옛날에는 달랐을 수 있기 때문에","correct":true},{"t":"화석은 오늘날의 환경만 알려 주기 때문에","mis":"SC5-1-u1-X37"}],"mis":"SC5-1-u1-X37","explanation":["화석이 알려 주는 것이에요.","옛날엔 달랐을 수 있어요.","언제나 같지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_basic#8','sci',5,1,'u1','L07','g5_1_sci_u1_L07_basic','lesson_basic','SC5-1-u1-C23',2,'mc','auto','자연사 박물관에서 할 수 있는 일은 어느 것인가요?',ARRAY['SC5-1-u1-X38','SC5-1-u1-X39','SC5-1-u1-X28']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C23","difficulty":2,"kind":"mc","stem":"자연사 박물관에서 할 수 있는 일은 어느 것인가요?","options":[{"t":"공룡 모형과 화석 표본 전시를 보고 전시 해설사의 설명을 듣는다","correct":true},{"t":"강가 지층의 탐방로를 따라 땅에 박힌 화석을 직접 찾는다","mis":"SC5-1-u1-X38"},{"t":"마음에 드는 화석 표본을 골라 집에 가져간다","mis":"SC5-1-u1-X39"},{"t":"화석을 깨뜨려 속을 살펴본다","mis":"SC5-1-u1-X28"}],"explanation":["박물관에는 무엇이 있나요?","전시와 해설이에요.","보고 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_basic#9','sci',5,1,'u1','L07','g5_1_sci_u1_L07_basic','lesson_basic','SC5-1-u1-C21',2,'error','auto','화석을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X35']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C21","difficulty":2,"kind":"error","stem":"화석을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「공룡 발자국 화석을 보면 공룡이 무슨 색이었는지 알 수 있어.」","correct":true,"mis_target":"SC5-1-u1-X35"},{"t":"하율 — 「발자국 사이의 간격으로 걸음을 짐작할 수 있어.」","mis":"SC5-1-u1-X35"},{"t":"서진 — 「발자국의 크기로 몸집을 짐작할 수 있어.」","mis":"SC5-1-u1-X35"}],"explanation":["발자국에 남은 것은?","색은 남지 않아요.","지민이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_basic#10','sci',5,1,'u1','L07','g5_1_sci_u1_L07_basic','lesson_basic','SC5-1-u1-C21',3,'mc','auto','공룡알 화석으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u1-X37','SC5-1-u1-X35']::text[],false,'{"seq":10,"concept":"SC5-1-u1-C21","difficulty":3,"kind":"mc","stem":"공룡알 화석으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"공룡이 알을 낳았고 그곳이 알을 낳던 곳이었다는 것","correct":true},{"t":"오늘날 그 지역의 기온","mis":"SC5-1-u1-X37"},{"t":"공룡이 알에서 나온 정확한 날짜","mis":"SC5-1-u1-X35"},{"t":"공룡이 좋아하던 소리","mis":"SC5-1-u1-X35"}],"explanation":["알이 모여 있어요.","알을 낳은 곳이에요.","알을 낳던 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_challenge#1','sci',5,1,'u1','L07','g5_1_sci_u1_L07_challenge','lesson_challenge','SC5-1-u1-C23',2,'sa','auto','「화석 산지는 옛날에 살았던 생물과 당시 환경을 알 수 있어 □□□ 연구에 중요한 자료입니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u1-C23","difficulty":2,"kind":"sa","stem":"「화석 산지는 옛날에 살았던 생물과 당시 환경을 알 수 있어 □□□ 연구에 중요한 자료입니다.」 □□□에 알맞은 말을 쓰세요.","answer":["생태계"],"explanation":["생물과 환경이 함께예요.","세 글자예요.","생태계예요."],"mis":"SC5-1-u1-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_challenge#2','sci',5,1,'u1','L07','g5_1_sci_u1_L07_challenge','lesson_challenge','SC5-1-u1-C22',2,'mc','auto','어느 바닷가 절벽에서 조개 화석이 나왔어요. 이곳의 과거 환경으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X36','SC5-1-u1-X37']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C22","difficulty":2,"kind":"mc","stem":"어느 바닷가 절벽에서 조개 화석이 나왔어요. 이곳의 과거 환경으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바다","correct":true},{"t":"사막","mis":"SC5-1-u1-X36"},{"t":"높은 산꼭대기의 숲","mis":"SC5-1-u1-X36"},{"t":"지금과 같은 땅이었으니 알 수 없다","mis":"SC5-1-u1-X37"}],"explanation":["오늘날 조개가 사는 곳이에요.","바다나 갯벌이에요.","바다였어요."],"asset":{"type":"passage","lines":["산호 — 오늘날 따뜻하고 깊이가 얕은 바다에서 산다.","고사리 — 오늘날 습기가 많은 곳에서 자란다.","조개 — 오늘날 바다나 갯벌에서 산다.","공룡 발자국 — 발자국의 크기와 발자국 사이의 간격이 남아 있다."],"title":"화석과 오늘날 비슷한 생물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_challenge#3','sci',5,1,'u1','L07','g5_1_sci_u1_L07_challenge','lesson_challenge','SC5-1-u1-C23',3,'match','auto','곳과 그곳에서 할 수 있는 일, 그 가치를 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u1-C23","difficulty":3,"kind":"match","stem":"곳과 그곳에서 할 수 있는 일, 그 가치를 알맞게 이으세요.","pairs":[{"l":"자연사 박물관","r":"화석 표본 전시를 보고 전시 해설사의 설명을 듣는다"},{"l":"화석 산지","r":"탐방로를 따라 땅에 남은 실제 화석을 관찰한다"},{"l":"화석 산지의 가치","r":"옛 생물과 당시 환경을 알려 주는 생태계 연구 자료"}],"mis":"SC5-1-u1-X38","explanation":["어디에서 하는 일인가요?","박물관과 화석 산지예요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_challenge#4','sci',5,1,'u1','L07','g5_1_sci_u1_L07_challenge','lesson_challenge','SC5-1-u1-C22',3,'error','auto','화석으로 과거를 추리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X36','SC5-1-u1-X37']::text[],false,'{"seq":4,"concept":"SC5-1-u1-C22","difficulty":3,"kind":"error","stem":"화석으로 과거를 추리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하 — 「산호 화석이 나왔으니 옛날에 춥고 아주 깊은 바다였어.」","correct":true,"mis_target":"SC5-1-u1-X36"},{"t":"유나 — 「고사리 화석이 나왔으니 습기가 많은 육지였어.」","mis":"SC5-1-u1-X36"},{"t":"건희 — 「같은 곳도 옛날엔 지금과 달랐을 수 있어.」","mis":"SC5-1-u1-X37"}],"explanation":["오늘날 산호가 사는 곳은?","따뜻하고 얕은 바다예요.","도하가 잘못 말했어요."],"asset":{"type":"passage","lines":["산호 — 오늘날 따뜻하고 깊이가 얕은 바다에서 산다.","고사리 — 오늘날 습기가 많은 곳에서 자란다.","조개 — 오늘날 바다나 갯벌에서 산다.","공룡 발자국 — 발자국의 크기와 발자국 사이의 간격이 남아 있다."],"title":"화석과 오늘날 비슷한 생물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_challenge#5','sci',5,1,'u1','L07','g5_1_sci_u1_L07_challenge','lesson_challenge','SC5-1-u1-C23',3,'ox','auto','화석 산지에서 멋진 화석을 발견하면 기념으로 집에 가져가도 돼요.',ARRAY['SC5-1-u1-X39']::text[],false,'{"seq":5,"concept":"SC5-1-u1-C23","difficulty":3,"kind":"ox","stem":"화석 산지에서 멋진 화석을 발견하면 기념으로 집에 가져가도 돼요.","answer":"X","reason_options":[{"t":"화석은 과거를 알려 주는 소중한 자료라 그 자리에 보전해야 하기 때문에","correct":true},{"t":"화석 산지의 화석은 가치가 없기 때문에","mis":"SC5-1-u1-X39"}],"mis":"SC5-1-u1-X39","explanation":["화석의 가치를 떠올려요.","연구에 중요한 자료예요.","가져가지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_challenge#6','sci',5,1,'u1','L07','g5_1_sci_u1_L07_challenge','lesson_challenge','SC5-1-u1-C21',3,'mc','auto','발자국 화석에서 발자국 사이의 간격이 넓은 것으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u1-X35','SC5-1-u1-X32']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C21","difficulty":3,"kind":"mc","stem":"발자국 화석에서 발자국 사이의 간격이 넓은 것으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"공룡의 걸음이 컸거나 움직임이 빨랐을 수 있다","correct":true},{"t":"공룡의 몸 색깔이 밝았다","mis":"SC5-1-u1-X35"},{"t":"그 공룡은 화석이 될 수 없다","mis":"SC5-1-u1-X32"},{"t":"공룡이 그곳에 알을 낳았다","mis":"SC5-1-u1-X35"}],"explanation":["간격은 무엇과 관계있나요?","걸음이에요.","움직임을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_challenge#7','sci',5,1,'u1','L07','g5_1_sci_u1_L07_challenge','lesson_challenge','SC5-1-u1-C22',3,'mc','auto','한 지층의 아래층에서 산호 화석이, 위층에서 고사리 화석이 나왔어요. 가장 알맞은 추리는 어느 것인가요?',ARRAY['SC5-1-u1-X12','SC5-1-u1-X37','SC5-1-u1-X36']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C22","difficulty":3,"kind":"mc","stem":"한 지층의 아래층에서 산호 화석이, 위층에서 고사리 화석이 나왔어요. 가장 알맞은 추리는 어느 것인가요?","options":[{"t":"이곳은 따뜻하고 얕은 바다였다가 나중에 습기가 많은 육지가 되었다","correct":true},{"t":"이곳은 육지였다가 나중에 바다가 되었다","mis":"SC5-1-u1-X12"},{"t":"이곳은 처음부터 지금까지 언제나 같은 환경이었다","mis":"SC5-1-u1-X37"},{"t":"산호와 고사리는 같은 환경에 살아서 알 수 없다","mis":"SC5-1-u1-X36"}],"explanation":["아래층이 먼저예요.","산호 다음 고사리예요.","바다에서 육지로 바뀌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_challenge#8','sci',5,1,'u1','L07','g5_1_sci_u1_L07_challenge','lesson_challenge','SC5-1-u1-C23',4,'mc','auto','화석의 가치를 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SC5-1-u1-X38','SC5-1-u1-X37','SC5-1-u1-X39']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C23","difficulty":4,"kind":"mc","stem":"화석의 가치를 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"옛 생물의 생김새와 과거 환경 등 지구의 과거에 관한 많은 정보를 알려 준다","correct":true},{"t":"보기에 예뻐서 장식하기 좋다","mis":"SC5-1-u1-X38"},{"t":"오늘날의 환경만 알려 준다","mis":"SC5-1-u1-X37"},{"t":"발견한 사람이 가져가 모으기 좋다","mis":"SC5-1-u1-X39"}],"explanation":["화석이 알려 주는 것은?","과거의 정보예요.","소중한 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_challenge#9','sci',5,1,'u1','L07','g5_1_sci_u1_L07_challenge','lesson_challenge','SC5-1-u1-C21',4,'mc','auto','단단한 암석에 공룡 발자국이 찍혀 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X44','SC5-1-u1-X21']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C21","difficulty":4,"kind":"mc","stem":"단단한 암석에 공룡 발자국이 찍혀 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"공룡이 걸을 때는 무른 진흙이나 모래였고 그 위에 퇴적물이 쌓여 굳어졌기 때문이다","correct":true},{"t":"공룡의 힘이 아주 세서 단단한 돌을 눌렀기 때문이다","mis":"SC5-1-u1-X44"},{"t":"사람이 나중에 돌에 새겼기 때문이다","mis":"SC5-1-u1-X44"},{"t":"돌이 불에 녹았다가 다시 굳었기 때문이다","mis":"SC5-1-u1-X21"}],"explanation":["그때 땅은 어땠을까요?","무른 진흙이었어요.","덮이고 굳었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L07_challenge#10','sci',5,1,'u1','L07','g5_1_sci_u1_L07_challenge','lesson_challenge','SC5-1-u1-C22',4,'essay','teacher','산호 화석과 고사리 화석을 예로 들어, 화석으로 과거 환경을 추리하는 방법을 설명하세요. 그리고 화석 산지가 가치 있는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u1-C22","difficulty":4,"kind":"essay","stem":"산호 화석과 고사리 화석을 예로 들어, 화석으로 과거 환경을 추리하는 방법을 설명하세요. 그리고 화석 산지가 가치 있는 까닭을 쓰세요.","answer_guide":{"answer":"예: 화석이 된 생물과 비슷한 오늘날의 생물이 사는 곳을 살펴보면 과거 환경을 추리할 수 있다. 오늘날 산호는 따뜻하고 깊이가 얕은 바다에 살므로 산호 화석이 나온 곳은 과거에 따뜻하고 깊이가 얕은 바다였다고 추리할 수 있다. 고사리는 습기가 많은 곳에서 자라므로 고사리 화석이 나온 곳은 과거에 따뜻하고 습기가 많은 육지였다. 화석 산지는 옛날에 살았던 생물과 당시 환경을 알 수 있어 생태계 연구에 중요한 자료이기 때문에 가치가 있다.","scoring_points":["오늘날 비슷한 생물과 견주는 방법을 썼는가","산호·고사리의 과거 환경을 바르게 썼는가","화석 산지의 가치를 썼는가"]},"explanation":["방법부터 써요.","두 화석을 예로 들어요.","가치를 써요."],"asset":{"type":"passage","lines":["산호 — 오늘날 따뜻하고 깊이가 얕은 바다에서 산다.","고사리 — 오늘날 습기가 많은 곳에서 자란다.","조개 — 오늘날 바다나 갯벌에서 산다.","공룡 발자국 — 발자국의 크기와 발자국 사이의 간격이 남아 있다."],"title":"화석과 오늘날 비슷한 생물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_basic#1','sci',5,1,'u1','L08','g5_1_sci_u1_L08_basic','lesson_basic','SC5-1-u1-C25',1,'mc','auto','우리나라에서 여러 모습의 지층과 공룡 발자국 화석이 특히 많이 발견된 곳은 어느 것인가요?',ARRAY['SC5-1-u1-X42']::text[],false,'{"seq":1,"concept":"SC5-1-u1-C25","difficulty":1,"kind":"mc","stem":"우리나라에서 여러 모습의 지층과 공룡 발자국 화석이 특히 많이 발견된 곳은 어느 것인가요?","options":[{"t":"바닷가","correct":true},{"t":"도시 한가운데","mis":"SC5-1-u1-X42"},{"t":"사막 한복판","mis":"SC5-1-u1-X42"},{"t":"높은 빌딩 옥상","mis":"SC5-1-u1-X42"}],"explanation":["지층이 드러난 곳이에요.","절벽과 바위가 많아요.","바닷가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_basic#2','sci',5,1,'u1','L08','g5_1_sci_u1_L08_basic','lesson_basic','SC5-1-u1-C24',1,'mc','auto','스마트 기기로 자료를 조사할 때 꼭 해야 할 일은 어느 것인가요?',ARRAY['SC5-1-u1-X40']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C24","difficulty":1,"kind":"mc","stem":"스마트 기기로 자료를 조사할 때 꼭 해야 할 일은 어느 것인가요?","options":[{"t":"올바른 정보인지 확인하고 출처를 밝힌다","correct":true},{"t":"가장 먼저 나온 내용을 그대로 옮긴다","mis":"SC5-1-u1-X40"},{"t":"어디에서 찾았는지는 적지 않는다","mis":"SC5-1-u1-X40"},{"t":"마음에 드는 내용만 골라 바꿔 쓴다","mis":"SC5-1-u1-X40"}],"explanation":["정보가 맞는지 살펴요.","어디서 찾았나요?","확인하고 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_basic#3','sci',5,1,'u1','L08','g5_1_sci_u1_L08_basic','lesson_basic','SC5-1-u1-C26',1,'ox','auto','땅을 파지 않고도 땅속 지층을 조사할 수 있어요.',ARRAY['SC5-1-u1-X43']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C26","difficulty":1,"kind":"ox","stem":"땅을 파지 않고도 땅속 지층을 조사할 수 있어요.","answer":"O","reason_options":[{"t":"진동·음파·인공위성 같은 방법으로 조사할 수 있기 때문에","correct":true},{"t":"땅속은 모두 텅 비어 있어서 볼 필요가 없기 때문에","mis":"SC5-1-u1-X43"}],"mis":"SC5-1-u1-X43","explanation":["과학이 톡톡을 떠올려요.","파지 않는 방법이 있어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_basic#4','sci',5,1,'u1','L08','g5_1_sci_u1_L08_basic','lesson_basic','SC5-1-u1-C25',1,'sa','auto','「경기도 화성시 고정리에서는 공룡□ 화석이 발견되었습니다.」 □에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u1-C25","difficulty":1,"kind":"sa","stem":"「경기도 화성시 고정리에서는 공룡□ 화석이 발견되었습니다.」 □에 알맞은 말을 쓰세요.","answer":["알"],"explanation":["여러 개가 모여 있어요.","달걀처럼 생겼어요.","공룡알이에요."],"asset":{"type":"passage","lines":["전북특별자치도 부안군 채석강 — 바닷가에 여러 겹으로 쌓인 지층","경상남도 고성군 상족암 — 바닷가 바위의 공룡 발자국 화석","경상남도 진주시 가진리 — 새 발자국 화석이 많이 나오는 화석 산지","경기도 화성시 고정리 — 공룡알 화석이 많이 나오는 화석 산지"],"title":"관광 지도에 넣을 곳"},"mis":"SC5-1-u1-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_basic#5','sci',5,1,'u1','L08','g5_1_sci_u1_L08_basic','lesson_basic','SC5-1-u1-C25',2,'match','auto','장소와 볼 수 있는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u1-C25","difficulty":2,"kind":"match","stem":"장소와 볼 수 있는 것을 알맞게 이으세요.","pairs":[{"l":"부안 채석강","r":"여러 겹으로 쌓인 지층"},{"l":"고성 상족암","r":"공룡 발자국 화석"},{"l":"진주 가진리","r":"새 발자국 화석"},{"l":"화성 고정리","r":"공룡알 화석"}],"mis":"SC5-1-u1-X41","explanation":["자료를 하나씩 읽어요.","지층과 화석이 섞여 있어요.","네 곳을 짝지어요."],"asset":{"type":"passage","lines":["전북특별자치도 부안군 채석강 — 바닷가에 여러 겹으로 쌓인 지층","경상남도 고성군 상족암 — 바닷가 바위의 공룡 발자국 화석","경상남도 진주시 가진리 — 새 발자국 화석이 많이 나오는 화석 산지","경기도 화성시 고정리 — 공룡알 화석이 많이 나오는 화석 산지"],"title":"관광 지도에 넣을 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_basic#6','sci',5,1,'u1','L08','g5_1_sci_u1_L08_basic','lesson_basic','SC5-1-u1-C24',2,'mc','auto','관광 지도를 만들 때 맨 먼저 하는 일은 어느 것인가요?',ARRAY['SC5-1-u1-X40']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C24","difficulty":2,"kind":"mc","stem":"관광 지도를 만들 때 맨 먼저 하는 일은 어느 것인가요?","options":[{"t":"지층과 화석을 본 경험이나 알고 있는 것을 이야기한다","correct":true},{"t":"다른 모둠 지도에 댓글을 단다","mis":"SC5-1-u1-X40"},{"t":"소개 글을 공유 게시판에 올린다","mis":"SC5-1-u1-X40"},{"t":"조사하지 않고 지도부터 그린다","mis":"SC5-1-u1-X40"}],"explanation":["계획하기부터예요.","아는 것을 나눠요.","경험을 이야기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_basic#7','sci',5,1,'u1','L08','g5_1_sci_u1_L08_basic','lesson_basic','SC5-1-u1-C24',2,'ox','auto','다른 모둠의 관광 지도에는 재미있게 장난스러운 댓글을 달아요.',ARRAY['SC5-1-u1-X40']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C24","difficulty":2,"kind":"ox","stem":"다른 모둠의 관광 지도에는 재미있게 장난스러운 댓글을 달아요.","answer":"X","reason_options":[{"t":"댓글을 쓸 때는 바르고 고운 말로 칭찬하고 궁금한 점을 나누어야 하기 때문에","correct":true},{"t":"댓글은 아무도 읽지 않기 때문에","mis":"SC5-1-u1-X40"}],"mis":"SC5-1-u1-X40","explanation":["댓글 예절이에요.","바르고 고운 말이에요.","장난 댓글은 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_basic#8','sci',5,1,'u1','L08','g5_1_sci_u1_L08_basic','lesson_basic','SC5-1-u1-C26',2,'mc','auto','바닷속 지층의 구조를 알아낼 때 쓰는 것은 어느 것인가요?',ARRAY['SC5-1-u1-X43']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C26","difficulty":2,"kind":"mc","stem":"바닷속 지층의 구조를 알아낼 때 쓰는 것은 어느 것인가요?","options":[{"t":"음파","correct":true},{"t":"돋보기","mis":"SC5-1-u1-X43"},{"t":"줄자","mis":"SC5-1-u1-X43"},{"t":"삽","mis":"SC5-1-u1-X43"}],"explanation":["바닷속은 깊어요.","소리를 보내요.","음파예요."],"asset":{"type":"passage","lines":["구멍 파기 — 구멍을 파면서 땅속 물질을 채집한다.","탄성파 탐사 — 진동을 보내 되돌아온 신호를 분석한다.","음파 — 바닷속 지층의 구조를 알아낸다.","인공위성·무인 항공기 — 촬영한 화면으로 넓은 범위를 살핀다."],"title":"보이지 않는 땅속을 조사하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_basic#9','sci',5,1,'u1','L08','g5_1_sci_u1_L08_basic','lesson_basic','SC5-1-u1-C24',2,'error','auto','관광 지도를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X39','SC5-1-u1-X40']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C24","difficulty":2,"kind":"error","stem":"관광 지도를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준호 — 「상족암에 가면 작은 화석 하나쯤은 기념으로 가져와도 돼.」","correct":true,"mis_target":"SC5-1-u1-X39"},{"t":"나윤 — 「조사를 어려워하는 친구를 도와주자.」","mis":"SC5-1-u1-X40"},{"t":"시온 — 「지층과 화석은 소중히 보전해야 해.」","mis":"SC5-1-u1-X39"}],"explanation":["보전을 떠올려요.","가져오지 않아요.","준호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_basic#10','sci',5,1,'u1','L08','g5_1_sci_u1_L08_basic','lesson_basic','SC5-1-u1-C26',3,'mc','auto','땅을 파지 않고 조사하는 방법끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X43']::text[],false,'{"seq":10,"concept":"SC5-1-u1-C26","difficulty":3,"kind":"mc","stem":"땅을 파지 않고 조사하는 방법끼리 묶은 것은 어느 것인가요?","options":[{"t":"탄성파 탐사, 인공위성이 촬영한 화면 분석","correct":true},{"t":"구멍을 파서 땅속 물질 채집, 탄성파 탐사","mis":"SC5-1-u1-X43"},{"t":"구멍을 파서 땅속 물질 채집, 채집한 물질 살피기","mis":"SC5-1-u1-X43"},{"t":"땅을 파지 않고는 조사할 수 없다","mis":"SC5-1-u1-X43"}],"explanation":["파는 방법을 빼요.","진동과 사진이에요.","탄성파와 인공위성이에요."],"asset":{"type":"passage","lines":["구멍 파기 — 구멍을 파면서 땅속 물질을 채집한다.","탄성파 탐사 — 진동을 보내 되돌아온 신호를 분석한다.","음파 — 바닷속 지층의 구조를 알아낸다.","인공위성·무인 항공기 — 촬영한 화면으로 넓은 범위를 살핀다."],"title":"보이지 않는 땅속을 조사하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_challenge#1','sci',5,1,'u1','L08','g5_1_sci_u1_L08_challenge','lesson_challenge','SC5-1-u1-C26',2,'sa','auto','「진동을 보내 되돌아온 신호를 분석하여 땅속을 조사하는 방법을 □□□ 탐사라고 합니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u1-C26","difficulty":2,"kind":"sa","stem":"「진동을 보내 되돌아온 신호를 분석하여 땅속을 조사하는 방법을 □□□ 탐사라고 합니다.」 □□□에 알맞은 말을 쓰세요.","answer":["탄성파"],"explanation":["진동을 보내요.","세 글자예요.","탄성파예요."],"asset":{"type":"passage","lines":["구멍 파기 — 구멍을 파면서 땅속 물질을 채집한다.","탄성파 탐사 — 진동을 보내 되돌아온 신호를 분석한다.","음파 — 바닷속 지층의 구조를 알아낸다.","인공위성·무인 항공기 — 촬영한 화면으로 넓은 범위를 살핀다."],"title":"보이지 않는 땅속을 조사하는 방법"},"mis":"SC5-1-u1-X43"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_challenge#2','sci',5,1,'u1','L08','g5_1_sci_u1_L08_challenge','lesson_challenge','SC5-1-u1-C25',2,'mc','auto','새 발자국 화석을 보러 가려면 어디로 가야 하나요?',ARRAY['SC5-1-u1-X41','SC5-1-u1-X42']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C25","difficulty":2,"kind":"mc","stem":"새 발자국 화석을 보러 가려면 어디로 가야 하나요?","options":[{"t":"경상남도 진주시 가진리","correct":true},{"t":"전북특별자치도 부안군 채석강","mis":"SC5-1-u1-X41"},{"t":"경기도 화성시 고정리","mis":"SC5-1-u1-X41"},{"t":"도시 한가운데의 공원","mis":"SC5-1-u1-X42"}],"explanation":["자료에서 새 발자국을 찾아요.","화석 산지예요.","진주 가진리예요."],"asset":{"type":"passage","lines":["전북특별자치도 부안군 채석강 — 바닷가에 여러 겹으로 쌓인 지층","경상남도 고성군 상족암 — 바닷가 바위의 공룡 발자국 화석","경상남도 진주시 가진리 — 새 발자국 화석이 많이 나오는 화석 산지","경기도 화성시 고정리 — 공룡알 화석이 많이 나오는 화석 산지"],"title":"관광 지도에 넣을 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_challenge#3','sci',5,1,'u1','L08','g5_1_sci_u1_L08_challenge','lesson_challenge','SC5-1-u1-C26',3,'match','auto','조사 방법과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u1-C26","difficulty":3,"kind":"match","stem":"조사 방법과 하는 일을 알맞게 이으세요.","pairs":[{"l":"구멍 파기","r":"땅속 물질을 채집한다"},{"l":"탄성파 탐사","r":"진동을 보내 되돌아온 신호를 분석한다"},{"l":"음파","r":"바닷속 지층의 구조를 알아낸다"},{"l":"인공위성","r":"넓은 범위를 촬영해 살핀다"}],"mis":"SC5-1-u1-X43","explanation":["방법을 하나씩 떠올려요.","파기·진동·소리·사진이에요.","넷을 짝지어요."],"asset":{"type":"passage","lines":["구멍 파기 — 구멍을 파면서 땅속 물질을 채집한다.","탄성파 탐사 — 진동을 보내 되돌아온 신호를 분석한다.","음파 — 바닷속 지층의 구조를 알아낸다.","인공위성·무인 항공기 — 촬영한 화면으로 넓은 범위를 살핀다."],"title":"보이지 않는 땅속을 조사하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_challenge#4','sci',5,1,'u1','L08','g5_1_sci_u1_L08_challenge','lesson_challenge','SC5-1-u1-C25',3,'error','auto','관광 지도 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u1-X41','SC5-1-u1-X42']::text[],false,'{"seq":4,"concept":"SC5-1-u1-C25","difficulty":3,"kind":"error","stem":"관광 지도 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「채석강은 공룡알 화석이 많이 나오는 곳이야.」","correct":true,"mis_target":"SC5-1-u1-X41"},{"t":"주아 — 「상족암에서는 지층과 화석을 함께 볼 수 있어.」","mis":"SC5-1-u1-X41"},{"t":"민결 — 「우리나라 바닷가에서 지층과 화석이 많이 발견됐어.」","mis":"SC5-1-u1-X42"}],"explanation":["자료를 다시 읽어요.","채석강은 지층이에요.","하람이 잘못 말했어요."],"asset":{"type":"passage","lines":["전북특별자치도 부안군 채석강 — 바닷가에 여러 겹으로 쌓인 지층","경상남도 고성군 상족암 — 바닷가 바위의 공룡 발자국 화석","경상남도 진주시 가진리 — 새 발자국 화석이 많이 나오는 화석 산지","경기도 화성시 고정리 — 공룡알 화석이 많이 나오는 화석 산지"],"title":"관광 지도에 넣을 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_challenge#5','sci',5,1,'u1','L08','g5_1_sci_u1_L08_challenge','lesson_challenge','SC5-1-u1-C26',3,'ox','auto','바닷속 깊은 곳의 지층은 직접 들어가 파지 않고 음파로 조사할 수 있어요.',ARRAY['SC5-1-u1-X43']::text[],false,'{"seq":5,"concept":"SC5-1-u1-C26","difficulty":3,"kind":"ox","stem":"바닷속 깊은 곳의 지층은 직접 들어가 파지 않고 음파로 조사할 수 있어요.","answer":"O","reason_options":[{"t":"음파를 쓰면 직접 들어가 파기 어려운 깊은 곳까지 구조를 알 수 있기 때문에","correct":true},{"t":"바닷속에는 지층이 없어서 조사할 필요가 없기 때문에","mis":"SC5-1-u1-X43"}],"mis":"SC5-1-u1-X43","explanation":["바닷속을 떠올려요.","음파를 써요.","맞는 말이에요."],"asset":{"type":"passage","lines":["구멍 파기 — 구멍을 파면서 땅속 물질을 채집한다.","탄성파 탐사 — 진동을 보내 되돌아온 신호를 분석한다.","음파 — 바닷속 지층의 구조를 알아낸다.","인공위성·무인 항공기 — 촬영한 화면으로 넓은 범위를 살핀다."],"title":"보이지 않는 땅속을 조사하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_challenge#6','sci',5,1,'u1','L08','g5_1_sci_u1_L08_challenge','lesson_challenge','SC5-1-u1-C24',3,'mc','auto','관광 지도를 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X40']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C24","difficulty":3,"kind":"mc","stem":"관광 지도를 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"경험 이야기 → 주제 정하기 → 역할 정하기 → 조사하기 → 소개 글 올리기 → 칭찬 댓글 달기","correct":true},{"t":"조사하기 → 경험 이야기 → 소개 글 올리기 → 주제 정하기 → 역할 정하기 → 칭찬 댓글 달기","mis":"SC5-1-u1-X40"},{"t":"주제 정하기 → 소개 글 올리기 → 조사하기 → 역할 정하기 → 경험 이야기 → 칭찬 댓글 달기","mis":"SC5-1-u1-X40"},{"t":"칭찬 댓글 달기 → 경험 이야기 → 주제 정하기 → 역할 정하기 → 조사하기 → 소개 글 올리기","mis":"SC5-1-u1-X40"}],"explanation":["계획하기부터예요.","해 보기 다음 나누기예요.","댓글은 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_challenge#7','sci',5,1,'u1','L08','g5_1_sci_u1_L08_challenge','lesson_challenge','SC5-1-u1-C25',3,'mc','auto','우리나라 관광 지도에 「지층과 화석을 함께 볼 수 있는 곳」으로 소개하기에 가장 알맞은 곳은 어느 것인가요?',ARRAY['SC5-1-u1-X41','SC5-1-u1-X42']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C25","difficulty":3,"kind":"mc","stem":"우리나라 관광 지도에 「지층과 화석을 함께 볼 수 있는 곳」으로 소개하기에 가장 알맞은 곳은 어느 것인가요?","options":[{"t":"고성 상족암","correct":true},{"t":"화성 고정리","mis":"SC5-1-u1-X41"},{"t":"진주 가진리","mis":"SC5-1-u1-X41"},{"t":"우리나라에는 그런 곳이 없다","mis":"SC5-1-u1-X42"}],"explanation":["자료를 읽어요.","바닷가 바위에 발자국이 있어요.","고성 상족암이에요."],"asset":{"type":"passage","lines":["전북특별자치도 부안군 채석강 — 바닷가에 여러 겹으로 쌓인 지층","경상남도 고성군 상족암 — 바닷가 바위의 공룡 발자국 화석","경상남도 진주시 가진리 — 새 발자국 화석이 많이 나오는 화석 산지","경기도 화성시 고정리 — 공룡알 화석이 많이 나오는 화석 산지"],"title":"관광 지도에 넣을 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_challenge#8','sci',5,1,'u1','L08','g5_1_sci_u1_L08_challenge','lesson_challenge','SC5-1-u1-C26',4,'mc','auto','지층을 조사하고 연구하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X39','SC5-1-u1-X43','SC5-1-u1-X07']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C26","difficulty":4,"kind":"mc","stem":"지층을 조사하고 연구하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지구의 과거 모습을 이해하고 지속가능한 지구를 만들기 위해","correct":true},{"t":"지층에 숨은 화석을 모두 꺼내 팔기 위해","mis":"SC5-1-u1-X39"},{"t":"땅을 파야만 알 수 있으니 구멍을 많이 뚫기 위해","mis":"SC5-1-u1-X43"},{"t":"지층의 색깔을 바꾸기 위해","mis":"SC5-1-u1-X07"}],"explanation":["과학이 톡톡을 떠올려요.","과거를 이해해요.","지속가능한 지구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_challenge#9','sci',5,1,'u1','L08','g5_1_sci_u1_L08_challenge','lesson_challenge','SC5-1-u1-C24',4,'mc','auto','친구가 누리망에서 찾은 글을 출처 없이 그대로 관광 지도에 붙이려고 해요. 가장 알맞은 조언은 어느 것인가요?',ARRAY['SC5-1-u1-X40']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C24","difficulty":4,"kind":"mc","stem":"친구가 누리망에서 찾은 글을 출처 없이 그대로 관광 지도에 붙이려고 해요. 가장 알맞은 조언은 어느 것인가요?","options":[{"t":"올바른 정보인지 확인하고, 어디에서 찾았는지 출처를 밝혀 내 말로 정리하자","correct":true},{"t":"먼저 나온 글이니 맞을 테고 그대로 붙여도 돼","mis":"SC5-1-u1-X40"},{"t":"출처는 길어서 적지 않아도 돼","mis":"SC5-1-u1-X40"},{"t":"재미있게 내용을 바꿔서 쓰면 더 좋아","mis":"SC5-1-u1-X40"}],"explanation":["조사할 때 지킬 점이에요.","확인하고 출처를 밝혀요.","내 말로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_L08_challenge#10','sci',5,1,'u1','L08','g5_1_sci_u1_L08_challenge','lesson_challenge','SC5-1-u1-C24',4,'essay','teacher','우리 모둠이 관광 지도에 넣을 곳 두 군데를 자료에서 골라 볼 수 있는 것과 함께 소개하는 글을 쓰고, 지도를 만들고 나눌 때 지킬 점 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u1-C24","difficulty":4,"kind":"essay","stem":"우리 모둠이 관광 지도에 넣을 곳 두 군데를 자료에서 골라 볼 수 있는 것과 함께 소개하는 글을 쓰고, 지도를 만들고 나눌 때 지킬 점 두 가지를 쓰세요.","answer_guide":{"answer":"예: 첫째, 전북특별자치도 부안군 채석강에 가면 바닷가에 여러 겹으로 쌓인 지층을 볼 수 있어요. 층마다 두께와 색깔이 다른 것을 비교해 보세요. 둘째, 경상남도 고성군 상족암에서는 바닷가 바위에 찍힌 공룡 발자국 화석을 볼 수 있어요. 지도를 만들 때는 올바른 정보인지 확인하고 출처를 밝히며, 다른 모둠 지도에는 바르고 고운 말로 칭찬 댓글을 단다. 지층과 화석은 소중히 보전하고 가져오지 않는다.","scoring_points":["두 곳과 볼 수 있는 것을 바르게 썼는가","소개 글의 모양을 갖추었는가","지킬 점 두 가지를 썼는가"]},"explanation":["두 곳을 골라요.","볼 것을 소개해요.","지킬 점을 써요."],"asset":{"type":"passage","lines":["전북특별자치도 부안군 채석강 — 바닷가에 여러 겹으로 쌓인 지층","경상남도 고성군 상족암 — 바닷가 바위의 공룡 발자국 화석","경상남도 진주시 가진리 — 새 발자국 화석이 많이 나오는 화석 산지","경기도 화성시 고정리 — 공룡알 화석이 많이 나오는 화석 산지"],"title":"관광 지도에 넣을 곳"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#1','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C4',1,'mc','auto','별무리반 일지 ①의 절벽처럼 퇴적물이 쌓여 층을 이룬 것을 무엇이라고 하나요?',ARRAY['SC5-1-u1-X04','SC5-1-u1-X05']::text[],false,'{"seq":1,"concept":"SC5-1-u1-C4","difficulty":1,"kind":"mc","stem":"별무리반 일지 ①의 절벽처럼 퇴적물이 쌓여 층을 이룬 것을 무엇이라고 하나요?","options":[{"t":"지층","correct":true},{"t":"화석","mis":"SC5-1-u1-X04"},{"t":"발굴","mis":"SC5-1-u1-X05"},{"t":"화성암","mis":"SC5-1-u1-X05"}],"explanation":["층이 쌓였어요.","줄무늬가 보여요.","지층이에요."],"asset":{"type":"passage","lines":["맨 아래 — 자갈층. 네 층 가운데 가장 두껍다.","그 위 — 모래층. 밝은 노란빛이다.","그 위 — 진흙층. 얇고 어두운 회색이다. 조개 화석이 박혀 있다.","맨 위 — 모래층. 절벽 오른쪽 끝에서는 층이 물결처럼 구부러져 있다."],"title":"별무리반 일지 ① 바닷가 절벽 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#2','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C10',1,'mc','auto','별무리반 일지 ① 그림에서 가장 먼저 쌓인 층은 어느 것인가요?',ARRAY['SC5-1-u1-X12','SC5-1-u1-X13']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C10","difficulty":1,"kind":"mc","stem":"별무리반 일지 ① 그림에서 가장 먼저 쌓인 층은 어느 것인가요?","options":[{"t":"맨 아래 자갈층","correct":true},{"t":"맨 위 모래층","mis":"SC5-1-u1-X12"},{"t":"진흙층","mis":"SC5-1-u1-X12"},{"t":"네 층이 동시에 쌓였다","mis":"SC5-1-u1-X13"}],"explanation":["아래가 먼저예요.","맨 아래를 봐요.","자갈층이에요."],"asset":{"type":"geo","items":[{"w":300,"h":164,"seg":[[[10,10],[290,10]],[[10,154],[290,154]],[[10,10],[10,154]],[[290,10],[290,154]],[[10,46],[290,46]],[[10,82],[290,82]],[[10,118],[290,118]]],"lab":[[[150,28],"모래층"],[[150,64],"진흙층"],[[150,100],"모래층"],[[150,136],"자갈층"]],"cap":"별무리반 일지 ① 바닷가 절벽 지층(위에서부터)"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#3','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C13',1,'mc','auto','별무리반 일지 ③에서 사암은 어느 것인가요?',ARRAY['SC5-1-u1-X19']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C13","difficulty":1,"kind":"mc","stem":"별무리반 일지 ③에서 사암은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"SC5-1-u1-X19"},{"t":"다","mis":"SC5-1-u1-X19"},{"t":"라","mis":"SC5-1-u1-X19"}],"explanation":["모래 알갱이를 찾아요.","까끌까끌해요.","가예요."],"asset":{"type":"passage","lines":["가 — 모래만 한 알갱이가 보이고 만지면 까끌까끌하다.","나 — 알갱이가 거의 보이지 않고 매끈하다. 어두운 회색이다.","다 — 콩알만 한 자갈이 박혀 울퉁불퉁하다.","라 — 알갱이가 거의 보이지 않고 매끈하다. 밝은 노란빛이다."],"title":"별무리반 일지 ③ 퇴적암 표본"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#4','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C16',1,'mc','auto','별무리반 일지 ④에서 흔적이 남은 화석은 어느 것인가요?',ARRAY['SC5-1-u1-X25','SC5-1-u1-X27']::text[],false,'{"seq":4,"concept":"SC5-1-u1-C16","difficulty":1,"kind":"mc","stem":"별무리반 일지 ④에서 흔적이 남은 화석은 어느 것인가요?","options":[{"t":"③ 공룡 발자국","correct":true},{"t":"① 물고기 뼈","mis":"SC5-1-u1-X25"},{"t":"② 고사리","mis":"SC5-1-u1-X27"},{"t":"④ 암모나이트","mis":"SC5-1-u1-X25"}],"explanation":["생활한 자국을 찾아요.","발자국이에요.","③이에요."],"asset":{"type":"passage","lines":["① 물고기의 뼈와 지느러미가 보인다.","② 갈라진 잎 모양이 남은 고사리","③ 커다란 발가락 자국이 남은 공룡 발자국","④ 둥글게 말린 암모나이트","⑤ 동물의 배설물이 굳은 것","⑥ 돋보기로 보아야 겨우 보이는 아주 작은 화석"],"title":"별무리반 일지 ④ 박물관에서 본 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#5','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C19',1,'mc','auto','별무리반 일지 ⑤에서 소라 껍데기는 실제의 무엇을 나타내나요?',ARRAY['SC5-1-u1-X30']::text[],false,'{"seq":5,"concept":"SC5-1-u1-C19","difficulty":1,"kind":"mc","stem":"별무리반 일지 ⑤에서 소라 껍데기는 실제의 무엇을 나타내나요?","options":[{"t":"옛날에 살았던 생물","correct":true},{"t":"흔적 위에 쌓이는 퇴적물","mis":"SC5-1-u1-X30"},{"t":"지층 속 화석","mis":"SC5-1-u1-X30"},{"t":"흐르는 물","mis":"SC5-1-u1-X30"}],"explanation":["소라는 살아 있던 것이에요.","생물이에요.","옛 생물이에요."],"asset":{"type":"passage","lines":["찰흙을 평평하게 펴고 소라 껍데기를 눌렀다가 떼어 냈다.","자국이 덮이도록 물을 붓고, 물 표면이 안 보일 만큼 석고 가루를 넣었다.","석고가 굳은 뒤 찰흙과 석고를 떼어 내니 석고에 소라 모양이 남았다.","모두 20분쯤 걸렸다."],"title":"별무리반 일지 ⑤ 소라 화석 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#6','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C22',1,'mc','auto','별무리반 일지 ⑥의 아래층이 쌓일 무렵 그곳은 어떤 환경이었나요?',ARRAY['SC5-1-u1-X36','SC5-1-u1-X37']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C22","difficulty":1,"kind":"mc","stem":"별무리반 일지 ⑥의 아래층이 쌓일 무렵 그곳은 어떤 환경이었나요?","options":[{"t":"따뜻하고 깊이가 얕은 바다","correct":true},{"t":"따뜻하고 습기가 많은 육지","mis":"SC5-1-u1-X36"},{"t":"춥고 아주 깊은 바다","mis":"SC5-1-u1-X36"},{"t":"지금과 똑같은 언덕","mis":"SC5-1-u1-X37"}],"explanation":["산호 화석이 나왔어요.","산호가 사는 곳이에요.","얕은 바다예요."],"asset":{"type":"passage","lines":["아래층 — 가지처럼 뻗은 산호 화석이 나왔다.","가운데층 — 화석을 찾지 못했다.","위층 — 갈라진 잎 모양의 고사리 화석이 나왔다.","위층 바위 — 커다란 공룡 발자국이 여러 개 찍혀 있고 발자국 사이 간격이 넓다."],"title":"별무리반 일지 ⑥ 언덕 지층의 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#7','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C25',1,'mc','auto','별무리반 일지 ⑧에서 공룡알 화석을 보러 가는 곳은 어디인가요?',ARRAY['SC5-1-u1-X41','SC5-1-u1-X42']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C25","difficulty":1,"kind":"mc","stem":"별무리반 일지 ⑧에서 공룡알 화석을 보러 가는 곳은 어디인가요?","options":[{"t":"화성 고정리","correct":true},{"t":"고성 상족암","mis":"SC5-1-u1-X41"},{"t":"부안 채석강","mis":"SC5-1-u1-X41"},{"t":"도시 한가운데 공원","mis":"SC5-1-u1-X42"}],"explanation":["계획을 읽어요.","공룡알이에요.","화성 고정리예요."],"asset":{"type":"passage","lines":["주제 — 우리나라의 공룡 화석","넣을 곳 — 고성 상족암(공룡 발자국 화석), 화성 고정리(공룡알 화석)","더 알아볼 것 — 바닷속 지층은 음파로, 넓은 땅은 인공위성 사진으로 조사한다고 한다.","약속 — 출처 밝히기, 고운 말 댓글, 화석은 가져오지 않기"],"title":"별무리반 일지 ⑧ 관광 지도 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#8','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C2',1,'mc','auto','화석을 발굴할 때 굳은 흙을 조금씩 파내는 도구는 어느 것인가요?',ARRAY['SC5-1-u1-X01','SC5-1-u1-X02']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C2","difficulty":1,"kind":"mc","stem":"화석을 발굴할 때 굳은 흙을 조금씩 파내는 도구는 어느 것인가요?","options":[{"t":"끌","correct":true},{"t":"쇠망치","mis":"SC5-1-u1-X01"},{"t":"물뿌리개","mis":"SC5-1-u1-X02"},{"t":"부채","mis":"SC5-1-u1-X02"}],"explanation":["굳은 흙을 파요.","조금씩 밀어 내요.","끌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#9','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C6',2,'mc','auto','별무리반 일지 ①의 절벽 오른쪽 끝처럼 층이 물결처럼 구부러진 지층은 어느 것인가요?',ARRAY['SC5-1-u1-X09','SC5-1-u1-X08']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C6","difficulty":2,"kind":"mc","stem":"별무리반 일지 ①의 절벽 오른쪽 끝처럼 층이 물결처럼 구부러진 지층은 어느 것인가요?","options":[{"t":"휘어진 지층","correct":true},{"t":"끊어진 지층","mis":"SC5-1-u1-X09"},{"t":"수평인 지층","mis":"SC5-1-u1-X09"},{"t":"구부러지면 지층이 아니다","mis":"SC5-1-u1-X08"}],"explanation":["모양을 읽어요.","물결처럼 구부러졌어요.","휘어진 지층이에요."],"asset":{"type":"passage","lines":["맨 아래 — 자갈층. 네 층 가운데 가장 두껍다.","그 위 — 모래층. 밝은 노란빛이다.","그 위 — 진흙층. 얇고 어두운 회색이다. 조개 화석이 박혀 있다.","맨 위 — 모래층. 절벽 오른쪽 끝에서는 층이 물결처럼 구부러져 있다."],"title":"별무리반 일지 ① 바닷가 절벽 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#10','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C11',2,'mc','auto','별무리반 일지 ②의 모형이 실제 지층과 다른 점은 어느 것인가요?',ARRAY['SC5-1-u1-X13','SC5-1-u1-X06','SC5-1-u1-X12']::text[],false,'{"seq":10,"concept":"SC5-1-u1-C11","difficulty":2,"kind":"mc","stem":"별무리반 일지 ②의 모형이 실제 지층과 다른 점은 어느 것인가요?","options":[{"t":"몇 분 만에 생기고 손으로 쉽게 흩어진다","correct":true},{"t":"여러 층이 생긴다","mis":"SC5-1-u1-X13"},{"t":"층마다 재료가 다르다","mis":"SC5-1-u1-X06"},{"t":"먼저 부은 것이 아래에 있다","mis":"SC5-1-u1-X12"}],"explanation":["기록의 끝 두 줄을 봐요.","시간과 단단함이에요.","다른 점이에요."],"asset":{"type":"passage","lines":["사각 통에 물을 조금 붓고, 잠기도록 물을 부은 재료를 차례로 부었다.","부은 차례 — 진흙 → 자갈과 모래 → 모래","5분쯤 지나자 세 층이 생겼다.","손가락으로 살짝 누르니 층이 쉽게 흩어졌다."],"title":"별무리반 일지 ② 우리 모둠 지층 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#11','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C13',2,'mc','auto','별무리반 일지 ③의 나와 라를 바르게 판단한 것은 어느 것인가요?',ARRAY['SC5-1-u1-X20','SC5-1-u1-X19','SC5-1-u1-X18']::text[],false,'{"seq":11,"concept":"SC5-1-u1-C13","difficulty":2,"kind":"mc","stem":"별무리반 일지 ③의 나와 라를 바르게 판단한 것은 어느 것인가요?","options":[{"t":"색은 다르지만 알갱이가 매우 작으니 둘 다 이암이다","correct":true},{"t":"색이 다르니 서로 다른 암석이다","mis":"SC5-1-u1-X20"},{"t":"나는 이암, 라는 역암이다","mis":"SC5-1-u1-X19"},{"t":"색이 밝은 라가 사암이다","mis":"SC5-1-u1-X18"}],"explanation":["알갱이를 견줘요.","둘 다 매끈해요.","둘 다 이암이에요."],"asset":{"type":"passage","lines":["가 — 모래만 한 알갱이가 보이고 만지면 까끌까끌하다.","나 — 알갱이가 거의 보이지 않고 매끈하다. 어두운 회색이다.","다 — 콩알만 한 자갈이 박혀 울퉁불퉁하다.","라 — 알갱이가 거의 보이지 않고 매끈하다. 밝은 노란빛이다."],"title":"별무리반 일지 ③ 퇴적암 표본"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#12','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C17',2,'mc','auto','별무리반 일지 ④의 화석 가운데 동물 화석끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X27']::text[],false,'{"seq":12,"concept":"SC5-1-u1-C17","difficulty":2,"kind":"mc","stem":"별무리반 일지 ④의 화석 가운데 동물 화석끼리 묶은 것은 어느 것인가요?","options":[{"t":"①, ④","correct":true},{"t":"②, ④","mis":"SC5-1-u1-X27"},{"t":"①, ②","mis":"SC5-1-u1-X27"},{"t":"②, ⑥","mis":"SC5-1-u1-X27"}],"explanation":["동물을 찾아요.","물고기와 암모나이트예요.","①과 ④예요."],"asset":{"type":"passage","lines":["① 물고기의 뼈와 지느러미가 보인다.","② 갈라진 잎 모양이 남은 고사리","③ 커다란 발가락 자국이 남은 공룡 발자국","④ 둥글게 말린 암모나이트","⑤ 동물의 배설물이 굳은 것","⑥ 돋보기로 보아야 겨우 보이는 아주 작은 화석"],"title":"별무리반 일지 ④ 박물관에서 본 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#13','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C20',2,'mc','auto','별무리반 일지 ⑤에서 물과 석고 가루로 자국을 덮은 일과 같은 실제의 일은 어느 것인가요?',ARRAY['SC5-1-u1-X32','SC5-1-u1-X34','SC5-1-u1-X30']::text[],false,'{"seq":13,"concept":"SC5-1-u1-C20","difficulty":2,"kind":"mc","stem":"별무리반 일지 ⑤에서 물과 석고 가루로 자국을 덮은 일과 같은 실제의 일은 어느 것인가요?","options":[{"t":"흔적 위로 퇴적물이 빠르게 쌓이는 일","correct":true},{"t":"생물이 죽는 일","mis":"SC5-1-u1-X32"},{"t":"지층이 깎여 드러나는 일","mis":"SC5-1-u1-X34"},{"t":"흔적이 불에 구워지는 일","mis":"SC5-1-u1-X30"}],"explanation":["자국을 덮었어요.","퇴적물이 덮어요.","빠르게 쌓이는 일이에요."],"asset":{"type":"passage","lines":["찰흙을 평평하게 펴고 소라 껍데기를 눌렀다가 떼어 냈다.","자국이 덮이도록 물을 붓고, 물 표면이 안 보일 만큼 석고 가루를 넣었다.","석고가 굳은 뒤 찰흙과 석고를 떼어 내니 석고에 소라 모양이 남았다.","모두 20분쯤 걸렸다."],"title":"별무리반 일지 ⑤ 소라 화석 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#14','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C21',2,'mc','auto','별무리반 일지 ⑥의 공룡 발자국으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u1-X35']::text[],false,'{"seq":14,"concept":"SC5-1-u1-C21","difficulty":2,"kind":"mc","stem":"별무리반 일지 ⑥의 공룡 발자국으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"몸집이 컸고 걸음이 컸을 것이다","correct":true},{"t":"몸 색깔이 초록색이었다","mis":"SC5-1-u1-X35"},{"t":"울음소리가 컸다","mis":"SC5-1-u1-X35"},{"t":"그곳에 알을 낳았다","mis":"SC5-1-u1-X35"}],"explanation":["발자국 크기와 간격이에요.","크고 넓어요.","몸집과 걸음이에요."],"asset":{"type":"passage","lines":["아래층 — 가지처럼 뻗은 산호 화석이 나왔다.","가운데층 — 화석을 찾지 못했다.","위층 — 갈라진 잎 모양의 고사리 화석이 나왔다.","위층 바위 — 커다란 공룡 발자국이 여러 개 찍혀 있고 발자국 사이 간격이 넓다."],"title":"별무리반 일지 ⑥ 언덕 지층의 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#15','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C24',2,'mc','auto','별무리반 일지 ⑧의 약속 가운데 「출처 밝히기」를 지키는 행동은 어느 것인가요?',ARRAY['SC5-1-u1-X40']::text[],false,'{"seq":15,"concept":"SC5-1-u1-C24","difficulty":2,"kind":"mc","stem":"별무리반 일지 ⑧의 약속 가운데 「출처 밝히기」를 지키는 행동은 어느 것인가요?","options":[{"t":"조사한 글 아래에 어디에서 찾았는지 적는다","correct":true},{"t":"찾은 글을 그대로 내 글처럼 붙인다","mis":"SC5-1-u1-X40"},{"t":"출처는 지우고 내용만 바꾼다","mis":"SC5-1-u1-X40"},{"t":"먼저 나온 글만 쓴다","mis":"SC5-1-u1-X40"}],"explanation":["어디서 찾았나요?","적어 두어요.","출처를 적어요."],"asset":{"type":"passage","lines":["주제 — 우리나라의 공룡 화석","넣을 곳 — 고성 상족암(공룡 발자국 화석), 화성 고정리(공룡알 화석)","더 알아볼 것 — 바닷속 지층은 음파로, 넓은 땅은 인공위성 사진으로 조사한다고 한다.","약속 — 출처 밝히기, 고운 말 댓글, 화석은 가져오지 않기"],"title":"별무리반 일지 ⑧ 관광 지도 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#16','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C12',2,'mc','auto','지층과 퇴적암의 관계를 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u1-X24','SC5-1-u1-X05']::text[],false,'{"seq":16,"concept":"SC5-1-u1-C12","difficulty":2,"kind":"mc","stem":"지층과 퇴적암의 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"지층은 퇴적물이 굳어진 퇴적암으로 이루어져 있다","correct":true},{"t":"지층과 퇴적암은 관계가 없다","mis":"SC5-1-u1-X24"},{"t":"지층은 뜨거운 물질이 굳은 암석으로만 이루어진다","mis":"SC5-1-u1-X05"},{"t":"퇴적암은 지층 밖에서만 생긴다","mis":"SC5-1-u1-X24"}],"explanation":["지층은 무엇으로 이루어졌나요?","퇴적물이 굳었어요.","퇴적암이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#17','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C3',3,'error','auto','별무리반 일지 ⑦에서 라온의 말을 바르게 고친 친구는 누구인가요?',ARRAY['SC5-1-u1-X04']::text[],false,'{"seq":17,"concept":"SC5-1-u1-C3","difficulty":3,"kind":"error","stem":"별무리반 일지 ⑦에서 라온의 말을 바르게 고친 친구는 누구인가요?","options":[{"t":"하리 — 「땅속에서 나온 것 가운데 옛 생물의 몸체나 흔적만 화석이야.」","correct":true,"mis_target":"SC5-1-u1-X04"},{"t":"보람 — 「유리병 조각도 땅에 묻혀 있었으니 화석이야.」","mis":"SC5-1-u1-X04"},{"t":"태민 — 「플라스틱 장난감도 오래되면 화석이야.」","mis":"SC5-1-u1-X04"}],"explanation":["화석의 뜻이에요.","옛 생물이에요.","하리가 바르게 고쳤어요."],"asset":{"type":"passage","lines":["라온 — 「땅속에서 나온 것은 다 화석이야.」","다빈 — 「역암은 알갱이가 가장 작아.」","이준 — 「멋진 화석은 기념으로 집에 가져가도 돼.」","소이 — 「지층에서는 맨 위 층이 가장 먼저 쌓였어.」"],"title":"별무리반 일지 ⑦ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#18','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C20',3,'ox','auto','단단한 바위에 찍힌 공룡 발자국은 공룡이 걸을 때 그곳이 무른 진흙이나 모래였기 때문에 생겼어요.',ARRAY['SC5-1-u1-X44']::text[],false,'{"seq":18,"concept":"SC5-1-u1-C20","difficulty":3,"kind":"ox","stem":"단단한 바위에 찍힌 공룡 발자국은 공룡이 걸을 때 그곳이 무른 진흙이나 모래였기 때문에 생겼어요.","answer":"O","reason_options":[{"t":"무른 땅에 찍힌 자국 위로 퇴적물이 쌓여 굳어졌기 때문에","correct":true},{"t":"공룡의 힘이 아주 세서 단단한 바위를 눌렀기 때문에","mis":"SC5-1-u1-X44"}],"mis":"SC5-1-u1-X44","explanation":["그때 땅은 어땠을까요?","무른 진흙이었어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#19','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C22',3,'mc','auto','별무리반 일지 ⑥의 언덕에서 일어난 환경의 변화를 차례로 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u1-X12','SC5-1-u1-X36','SC5-1-u1-X37']::text[],false,'{"seq":19,"concept":"SC5-1-u1-C22","difficulty":3,"kind":"mc","stem":"별무리반 일지 ⑥의 언덕에서 일어난 환경의 변화를 차례로 바르게 말한 것은 어느 것인가요?","options":[{"t":"따뜻하고 얕은 바다 → 따뜻하고 습기가 많은 육지","correct":true},{"t":"따뜻하고 습기가 많은 육지 → 따뜻하고 얕은 바다","mis":"SC5-1-u1-X12"},{"t":"춥고 깊은 바다 → 사막","mis":"SC5-1-u1-X36"},{"t":"언제나 지금과 같은 언덕","mis":"SC5-1-u1-X37"}],"explanation":["아래층부터 읽어요.","산호 다음 고사리예요.","바다에서 육지로예요."],"asset":{"type":"passage","lines":["아래층 — 가지처럼 뻗은 산호 화석이 나왔다.","가운데층 — 화석을 찾지 못했다.","위층 — 갈라진 잎 모양의 고사리 화석이 나왔다.","위층 바위 — 커다란 공룡 발자국이 여러 개 찍혀 있고 발자국 사이 간격이 넓다."],"title":"별무리반 일지 ⑥ 언덕 지층의 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#20','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C20',3,'mc','auto','해파리처럼 몸이 물렁한 생물의 화석이 드문 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X33','SC5-1-u1-X36','SC5-1-u1-X32']::text[],false,'{"seq":20,"concept":"SC5-1-u1-C20","difficulty":3,"kind":"mc","stem":"해파리처럼 몸이 물렁한 생물의 화석이 드문 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"단단하거나 질긴 부분이 없어 화석으로 남기 어렵기 때문에","correct":true},{"t":"물렁한 몸이 화석으로 가장 잘 남기 때문에","mis":"SC5-1-u1-X33"},{"t":"바다 생물은 화석이 될 수 없기 때문에","mis":"SC5-1-u1-X36"},{"t":"죽으면 모두 화석이 되니 드물지 않다","mis":"SC5-1-u1-X32"}],"explanation":["잘 남는 부분을 떠올려요.","단단하거나 질긴 부분이에요.","물렁하면 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#21','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C11',3,'mc','auto','지층 모형과 화석 모형에서 공통으로 알 수 있는 실제와의 차이점은 어느 것인가요?',ARRAY['SC5-1-u1-X13','SC5-1-u1-X15','SC5-1-u1-X14']::text[],false,'{"seq":21,"concept":"SC5-1-u1-C11","difficulty":3,"kind":"mc","stem":"지층 모형과 화석 모형에서 공통으로 알 수 있는 실제와의 차이점은 어느 것인가요?","options":[{"t":"모형은 몇 분이면 되지만 실제는 아주 오랜 시간이 걸린다","correct":true},{"t":"실제도 모형처럼 몇 분이면 된다","mis":"SC5-1-u1-X13"},{"t":"모형과 실제는 닮은 점이 하나도 없다","mis":"SC5-1-u1-X15"},{"t":"실제는 불에 구워 단단해진다","mis":"SC5-1-u1-X14"}],"explanation":["두 모형을 떠올려요.","시간이 달라요.","실제는 오래 걸려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#22','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C23',3,'mc','auto','자연사 박물관과 화석 산지를 견준 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X39','SC5-1-u1-X38']::text[],false,'{"seq":22,"concept":"SC5-1-u1-C23","difficulty":3,"kind":"mc","stem":"자연사 박물관과 화석 산지를 견준 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"박물관은 표본 전시와 해설을, 화석 산지는 탐방로를 따라 땅에 남은 화석을 볼 수 있다","correct":true},{"t":"두 곳 모두 화석을 가져갈 수 있다","mis":"SC5-1-u1-X39"},{"t":"화석 산지는 화석이 하나도 없는 곳이다","mis":"SC5-1-u1-X38"},{"t":"박물관에서는 탐방로를 따라 땅을 판다","mis":"SC5-1-u1-X38"}],"explanation":["두 곳을 견줘요.","전시와 탐방이에요.","하는 일이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#23','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C9',4,'mc','auto','별무리반 일지 ① 그림의 지층이 만들어진 과정을 가장 바르게 설명한 것은 어느 것인가요?',ARRAY['SC5-1-u1-X12','SC5-1-u1-X16','SC5-1-u1-X13']::text[],false,'{"seq":23,"concept":"SC5-1-u1-C9","difficulty":4,"kind":"mc","stem":"별무리반 일지 ① 그림의 지층이 만들어진 과정을 가장 바르게 설명한 것은 어느 것인가요?","options":[{"t":"흐르는 물이 운반한 자갈 → 모래 → 진흙 → 모래가 차례로 쌓이고 눌려 굳은 뒤 드러나 깎였다","correct":true},{"t":"맨 위 모래층부터 쌓이고 마지막에 자갈층이 쌓였다","mis":"SC5-1-u1-X12"},{"t":"굳어진 다음에 운반되어 쌓였다","mis":"SC5-1-u1-X16"},{"t":"네 층이 하루 만에 한꺼번에 생겼다","mis":"SC5-1-u1-X13"}],"explanation":["아래부터 읽어요.","쌓이고 눌리고 굳어요.","드러나 깎였어요."],"asset":{"type":"geo","items":[{"w":300,"h":164,"seg":[[[10,10],[290,10]],[[10,154],[290,154]],[[10,10],[10,154]],[[290,10],[290,154]],[[10,46],[290,46]],[[10,82],[290,82]],[[10,118],[290,118]]],"lab":[[[150,28],"모래층"],[[150,64],"진흙층"],[[150,100],"모래층"],[[150,136],"자갈층"]],"cap":"별무리반 일지 ① 바닷가 절벽 지층(위에서부터)"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#24','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C10',4,'essay','teacher','별무리반 일지 ①의 지층 그림을 보고 네 층을 오래된 층부터 차례로 쓰고 그 근거를 쓰세요. 그리고 층마다 두께와 색깔이 다른 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u1-C10","difficulty":4,"kind":"essay","stem":"별무리반 일지 ①의 지층 그림을 보고 네 층을 오래된 층부터 차례로 쓰고 그 근거를 쓰세요. 그리고 층마다 두께와 색깔이 다른 까닭을 쓰세요.","answer_guide":{"answer":"예: 오래된 층부터 자갈층, 모래층, 진흙층, 모래층의 차례이다. 지층에서는 아래에 있는 층이 위에 있는 층보다 먼저 쌓였기 때문이다. 층마다 두께와 색깔이 다른 것은 층마다 쌓인 퇴적물의 종류와 양이 달랐기 때문이다.","scoring_points":["네 층의 차례를 바르게 썼는가","아래 층이 먼저라는 근거를 썼는가","퇴적물이 달라서라는 까닭을 썼는가"]},"explanation":["맨 아래부터 읽어요.","근거를 써요.","두께와 색을 설명해요."],"asset":{"type":"geo","items":[{"w":300,"h":164,"seg":[[[10,10],[290,10]],[[10,154],[290,154]],[[10,10],[10,154]],[[290,10],[290,154]],[[10,46],[290,46]],[[10,82],[290,82]],[[10,118],[290,118]]],"lab":[[[150,28],"모래층"],[[150,64],"진흙층"],[[150,100],"모래층"],[[150,136],"자갈층"]],"cap":"별무리반 일지 ① 바닷가 절벽 지층(위에서부터)"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_a#25','sci',5,1,'u1','','g5_1_sci_u1_review_a','unit_review','SC5-1-u1-C4',4,'essay','teacher','별무리반 일지 ⑦의 라온과 소이의 말이 왜 옳지 않은지 배운 내용을 근거로 바로잡아 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u1-C4","difficulty":4,"kind":"essay","stem":"별무리반 일지 ⑦의 라온과 소이의 말이 왜 옳지 않은지 배운 내용을 근거로 바로잡아 쓰세요.","answer_guide":{"answer":"예: 라온아, 땅속에서 나온 것이 모두 화석은 아니야. 화석은 옛날에 살았던 생물의 몸체나 흔적이 지층 속에 남은 것이라서 유리병 조각이나 장난감은 화석이 아니야. 소이야, 지층에서는 아래에 있는 층이 먼저 쌓인 거야. 돌탑의 맨 아래 돌을 가장 먼저 쌓은 것처럼 맨 위 층은 가장 나중에 쌓인 층이야.","scoring_points":["라온의 말을 화석의 뜻으로 바로잡았는가","소이의 말을 층의 차례로 바로잡았는가","근거를 들어 설명했는가"]},"explanation":["라온부터 따져요.","소이는 층의 차례예요.","근거를 들어요."],"asset":{"type":"passage","lines":["라온 — 「땅속에서 나온 것은 다 화석이야.」","다빈 — 「역암은 알갱이가 가장 작아.」","이준 — 「멋진 화석은 기념으로 집에 가져가도 돼.」","소이 — 「지층에서는 맨 위 층이 가장 먼저 쌓였어.」"],"title":"별무리반 일지 ⑦ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#1','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C5',1,'sa','auto','별무리반 일지 ①에서 가장 두꺼운 층은 무엇인가요? (□□층)','{}'::text[],false,'{"seq":1,"concept":"SC5-1-u1-C5","difficulty":1,"kind":"sa","stem":"별무리반 일지 ①에서 가장 두꺼운 층은 무엇인가요? (□□층)","answer":["자갈층","자갈"],"explanation":["기록을 읽어요.","맨 아래 층이에요.","자갈층이에요."],"asset":{"type":"passage","lines":["맨 아래 — 자갈층. 네 층 가운데 가장 두껍다.","그 위 — 모래층. 밝은 노란빛이다.","그 위 — 진흙층. 얇고 어두운 회색이다. 조개 화석이 박혀 있다.","맨 위 — 모래층. 절벽 오른쪽 끝에서는 층이 물결처럼 구부러져 있다."],"title":"별무리반 일지 ① 바닷가 절벽 관찰"},"mis":"SC5-1-u1-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#2','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C10',1,'sa','auto','별무리반 일지 ②의 모형에서 맨 아래에 깔린 재료는 무엇인가요? (□□)','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u1-C10","difficulty":1,"kind":"sa","stem":"별무리반 일지 ②의 모형에서 맨 아래에 깔린 재료는 무엇인가요? (□□)","answer":["진흙"],"explanation":["먼저 부은 것을 찾아요.","먼저 부은 것이 아래로 가요.","진흙이에요."],"asset":{"type":"passage","lines":["사각 통에 물을 조금 붓고, 잠기도록 물을 부은 재료를 차례로 부었다.","부은 차례 — 진흙 → 자갈과 모래 → 모래","5분쯤 지나자 세 층이 생겼다.","손가락으로 살짝 누르니 층이 쉽게 흩어졌다."],"title":"별무리반 일지 ② 우리 모둠 지층 모형"},"mis":"SC5-1-u1-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#3','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C13',1,'sa','auto','별무리반 일지 ③의 다처럼 자갈이 박혀 있는 퇴적암은 무엇인가요? (□□)','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u1-C13","difficulty":1,"kind":"sa","stem":"별무리반 일지 ③의 다처럼 자갈이 박혀 있는 퇴적암은 무엇인가요? (□□)","answer":["역암"],"explanation":["자갈이 보여요.","알갱이가 가장 커요.","역암이에요."],"asset":{"type":"passage","lines":["가 — 모래만 한 알갱이가 보이고 만지면 까끌까끌하다.","나 — 알갱이가 거의 보이지 않고 매끈하다. 어두운 회색이다.","다 — 콩알만 한 자갈이 박혀 울퉁불퉁하다.","라 — 알갱이가 거의 보이지 않고 매끈하다. 밝은 노란빛이다."],"title":"별무리반 일지 ③ 퇴적암 표본"},"mis":"SC5-1-u1-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#4','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C17',1,'sa','auto','별무리반 일지 ④에서 식물 화석은 몇 번인가요? (숫자)','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u1-C17","difficulty":1,"kind":"sa","stem":"별무리반 일지 ④에서 식물 화석은 몇 번인가요? (숫자)","answer":["2","②"],"explanation":["잎 모양을 찾아요.","고사리예요.","②예요."],"asset":{"type":"passage","lines":["① 물고기의 뼈와 지느러미가 보인다.","② 갈라진 잎 모양이 남은 고사리","③ 커다란 발가락 자국이 남은 공룡 발자국","④ 둥글게 말린 암모나이트","⑤ 동물의 배설물이 굳은 것","⑥ 돋보기로 보아야 겨우 보이는 아주 작은 화석"],"title":"별무리반 일지 ④ 박물관에서 본 화석"},"mis":"SC5-1-u1-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#5','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C19',1,'sa','auto','별무리반 일지 ⑤에서 자국 위에 물을 붓고 넣은 가루는 무엇인가요? (□□ 가루)','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u1-C19","difficulty":1,"kind":"sa","stem":"별무리반 일지 ⑤에서 자국 위에 물을 붓고 넣은 가루는 무엇인가요? (□□ 가루)","answer":["석고","석고 가루"],"explanation":["굳는 가루예요.","두 글자예요.","석고예요."],"asset":{"type":"passage","lines":["찰흙을 평평하게 펴고 소라 껍데기를 눌렀다가 떼어 냈다.","자국이 덮이도록 물을 붓고, 물 표면이 안 보일 만큼 석고 가루를 넣었다.","석고가 굳은 뒤 찰흙과 석고를 떼어 내니 석고에 소라 모양이 남았다.","모두 20분쯤 걸렸다."],"title":"별무리반 일지 ⑤ 소라 화석 모형"},"mis":"SC5-1-u1-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#6','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C22',1,'sa','auto','별무리반 일지 ⑥의 위층이 쌓일 무렵 그곳은 바다와 육지 가운데 어느 쪽이었나요? (□□)','{}'::text[],false,'{"seq":6,"concept":"SC5-1-u1-C22","difficulty":1,"kind":"sa","stem":"별무리반 일지 ⑥의 위층이 쌓일 무렵 그곳은 바다와 육지 가운데 어느 쪽이었나요? (□□)","answer":["육지"],"explanation":["고사리 화석이 나왔어요.","습기가 많은 곳이에요.","육지예요."],"asset":{"type":"passage","lines":["아래층 — 가지처럼 뻗은 산호 화석이 나왔다.","가운데층 — 화석을 찾지 못했다.","위층 — 갈라진 잎 모양의 고사리 화석이 나왔다.","위층 바위 — 커다란 공룡 발자국이 여러 개 찍혀 있고 발자국 사이 간격이 넓다."],"title":"별무리반 일지 ⑥ 언덕 지층의 화석"},"mis":"SC5-1-u1-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#7','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C26',1,'sa','auto','별무리반 일지 ⑧에서 바닷속 지층을 조사하는 방법은 무엇인가요? (□□)','{}'::text[],false,'{"seq":7,"concept":"SC5-1-u1-C26","difficulty":1,"kind":"sa","stem":"별무리반 일지 ⑧에서 바닷속 지층을 조사하는 방법은 무엇인가요? (□□)","answer":["음파"],"explanation":["바닷속이에요.","소리를 써요.","음파예요."],"asset":{"type":"passage","lines":["주제 — 우리나라의 공룡 화석","넣을 곳 — 고성 상족암(공룡 발자국 화석), 화성 고정리(공룡알 화석)","더 알아볼 것 — 바닷속 지층은 음파로, 넓은 땅은 인공위성 사진으로 조사한다고 한다.","약속 — 출처 밝히기, 고운 말 댓글, 화석은 가져오지 않기"],"title":"별무리반 일지 ⑧ 관광 지도 계획"},"mis":"SC5-1-u1-X43"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#8','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C23',1,'sa','auto','「공룡 모형과 화석 표본을 전시하고 해설사가 설명해 주는 곳은 자연사 □□□입니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SC5-1-u1-C23","difficulty":1,"kind":"sa","stem":"「공룡 모형과 화석 표본을 전시하고 해설사가 설명해 주는 곳은 자연사 □□□입니다.」 □□□에 알맞은 말을 쓰세요.","answer":["박물관"],"explanation":["전시하는 곳이에요.","세 글자예요.","박물관이에요."],"mis":"SC5-1-u1-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#9','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C6',2,'sa','auto','별무리반 일지 ①의 절벽 왼쪽처럼 층이 나란히 평평한 지층을 무엇이라고 하나요? (□□인 지층)','{}'::text[],false,'{"seq":9,"concept":"SC5-1-u1-C6","difficulty":2,"kind":"sa","stem":"별무리반 일지 ①의 절벽 왼쪽처럼 층이 나란히 평평한 지층을 무엇이라고 하나요? (□□인 지층)","answer":["수평"],"explanation":["평평해요.","나란해요.","수평인 지층이에요."],"asset":{"type":"passage","lines":["맨 아래 — 자갈층. 네 층 가운데 가장 두껍다.","그 위 — 모래층. 밝은 노란빛이다.","그 위 — 진흙층. 얇고 어두운 회색이다. 조개 화석이 박혀 있다.","맨 위 — 모래층. 절벽 오른쪽 끝에서는 층이 물결처럼 구부러져 있다."],"title":"별무리반 일지 ① 바닷가 절벽 관찰"},"mis":"SC5-1-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#10','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C9',2,'sa','auto','「별무리반 일지 ②의 모형과 달리 실제 지층은 아주 오랜 시간 눌리고 □□□ 단단해집니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u1-C9","difficulty":2,"kind":"sa","stem":"「별무리반 일지 ②의 모형과 달리 실제 지층은 아주 오랜 시간 눌리고 □□□ 단단해집니다.」 □□□에 알맞은 말을 쓰세요.","answer":["굳어져","굳어서"],"explanation":["단단해지는 까닭이에요.","세 글자예요.","굳어져예요."],"asset":{"type":"passage","lines":["사각 통에 물을 조금 붓고, 잠기도록 물을 부은 재료를 차례로 부었다.","부은 차례 — 진흙 → 자갈과 모래 → 모래","5분쯤 지나자 세 층이 생겼다.","손가락으로 살짝 누르니 층이 쉽게 흩어졌다."],"title":"별무리반 일지 ② 우리 모둠 지층 모형"},"mis":"SC5-1-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#11','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C13',2,'sa','auto','별무리반 일지 ③의 표본을 알갱이가 작은 것부터 늘어놓을 때 가장 마지막은 무엇인가요? (기호)','{}'::text[],false,'{"seq":11,"concept":"SC5-1-u1-C13","difficulty":2,"kind":"sa","stem":"별무리반 일지 ③의 표본을 알갱이가 작은 것부터 늘어놓을 때 가장 마지막은 무엇인가요? (기호)","answer":["다"],"explanation":["가장 큰 알갱이를 찾아요.","자갈이에요.","다예요."],"asset":{"type":"passage","lines":["가 — 모래만 한 알갱이가 보이고 만지면 까끌까끌하다.","나 — 알갱이가 거의 보이지 않고 매끈하다. 어두운 회색이다.","다 — 콩알만 한 자갈이 박혀 울퉁불퉁하다.","라 — 알갱이가 거의 보이지 않고 매끈하다. 밝은 노란빛이다."],"title":"별무리반 일지 ③ 퇴적암 표본"},"mis":"SC5-1-u1-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#12','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C18',2,'sa','auto','별무리반 일지 ④의 화석들은 주로 어떤 암석에서 발견되었을까요? (□□□)','{}'::text[],false,'{"seq":12,"concept":"SC5-1-u1-C18","difficulty":2,"kind":"sa","stem":"별무리반 일지 ④의 화석들은 주로 어떤 암석에서 발견되었을까요? (□□□)","answer":["퇴적암"],"explanation":["쌓여 굳은 암석이에요.","생물이 함께 묻혀요.","퇴적암이에요."],"asset":{"type":"passage","lines":["① 물고기의 뼈와 지느러미가 보인다.","② 갈라진 잎 모양이 남은 고사리","③ 커다란 발가락 자국이 남은 공룡 발자국","④ 둥글게 말린 암모나이트","⑤ 동물의 배설물이 굳은 것","⑥ 돋보기로 보아야 겨우 보이는 아주 작은 화석"],"title":"별무리반 일지 ④ 박물관에서 본 화석"},"mis":"SC5-1-u1-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#13','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C20',2,'sa','auto','「생물의 뼈·이빨·껍데기처럼 □□□ 부분은 화석이 되기 쉽습니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u1-C20","difficulty":2,"kind":"sa","stem":"「생물의 뼈·이빨·껍데기처럼 □□□ 부분은 화석이 되기 쉽습니다.」 □□□에 알맞은 말을 쓰세요.","answer":["단단한"],"explanation":["소라 껍데기를 떠올려요.","물렁하지 않아요.","단단한이에요."],"mis":"SC5-1-u1-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#14','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C22',2,'sa','auto','별무리반 일지 ⑥에서 바다였던 때의 층은 아래층과 위층 가운데 어느 것인가요? (□□층)','{}'::text[],false,'{"seq":14,"concept":"SC5-1-u1-C22","difficulty":2,"kind":"sa","stem":"별무리반 일지 ⑥에서 바다였던 때의 층은 아래층과 위층 가운데 어느 것인가요? (□□층)","answer":["아래층","아래"],"explanation":["산호가 나온 층이에요.","바다 생물이에요.","아래층이에요."],"asset":{"type":"passage","lines":["아래층 — 가지처럼 뻗은 산호 화석이 나왔다.","가운데층 — 화석을 찾지 못했다.","위층 — 갈라진 잎 모양의 고사리 화석이 나왔다.","위층 바위 — 커다란 공룡 발자국이 여러 개 찍혀 있고 발자국 사이 간격이 넓다."],"title":"별무리반 일지 ⑥ 언덕 지층의 화석"},"mis":"SC5-1-u1-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#15','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C24',2,'sa','auto','별무리반 일지 ⑧에서 다른 모둠 지도에 댓글을 달 때 쓰기로 한 말은 어떤 말인가요? (□□ 말)','{}'::text[],false,'{"seq":15,"concept":"SC5-1-u1-C24","difficulty":2,"kind":"sa","stem":"별무리반 일지 ⑧에서 다른 모둠 지도에 댓글을 달 때 쓰기로 한 말은 어떤 말인가요? (□□ 말)","answer":["고운","바르고 고운"],"explanation":["약속을 읽어요.","예쁜 말이에요.","고운 말이에요."],"asset":{"type":"passage","lines":["주제 — 우리나라의 공룡 화석","넣을 곳 — 고성 상족암(공룡 발자국 화석), 화성 고정리(공룡알 화석)","더 알아볼 것 — 바닷속 지층은 음파로, 넓은 땅은 인공위성 사진으로 조사한다고 한다.","약속 — 출처 밝히기, 고운 말 댓글, 화석은 가져오지 않기"],"title":"별무리반 일지 ⑧ 관광 지도 계획"},"mis":"SC5-1-u1-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#16','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C1',2,'sa','auto','숨겨진 블록을 찾는 활동에서 마지막에 블록의 흙을 털어 낸 도구는 무엇인가요? (작은 □)','{}'::text[],false,'{"seq":16,"concept":"SC5-1-u1-C1","difficulty":2,"kind":"sa","stem":"숨겨진 블록을 찾는 활동에서 마지막에 블록의 흙을 털어 낸 도구는 무엇인가요? (작은 □)","answer":["붓"],"explanation":["마지막 단계예요.","살살 털어요.","붓이에요."],"mis":"SC5-1-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#17','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C13',3,'error','auto','별무리반 일지 ⑦에서 다빈의 말을 바르게 고친 친구는 누구인가요?',ARRAY['SC5-1-u1-X19','SC5-1-u1-X20']::text[],false,'{"seq":17,"concept":"SC5-1-u1-C13","difficulty":3,"kind":"error","stem":"별무리반 일지 ⑦에서 다빈의 말을 바르게 고친 친구는 누구인가요?","options":[{"t":"세린 — 「역암은 자갈이 섞여 알갱이가 가장 커.」","correct":true,"mis_target":"SC5-1-u1-X19"},{"t":"은호 — 「사암이 알갱이가 가장 작아.」","mis":"SC5-1-u1-X19"},{"t":"가온 — 「색이 어두운 암석이 알갱이가 작아.」","mis":"SC5-1-u1-X20"}],"explanation":["알갱이 크기 순서예요.","자갈이 가장 커요.","세린이 바르게 고쳤어요."],"asset":{"type":"passage","lines":["라온 — 「땅속에서 나온 것은 다 화석이야.」","다빈 — 「역암은 알갱이가 가장 작아.」","이준 — 「멋진 화석은 기념으로 집에 가져가도 돼.」","소이 — 「지층에서는 맨 위 층이 가장 먼저 쌓였어.」"],"title":"별무리반 일지 ⑦ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#18','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C15',3,'ox','auto','모래를 손으로 아주 세게 쥐면 바로 사암이 돼요.',ARRAY['SC5-1-u1-X22']::text[],false,'{"seq":18,"concept":"SC5-1-u1-C15","difficulty":3,"kind":"ox","stem":"모래를 손으로 아주 세게 쥐면 바로 사암이 돼요.","answer":"X","reason_options":[{"t":"오랜 시간 눌리고 물에 녹은 물질이 엉겨 붙는 과정이 없기 때문에","correct":true},{"t":"손힘만 더 세면 사암이 되기 때문에","mis":"SC5-1-u1-X22"}],"mis":"SC5-1-u1-X22","explanation":["퇴적암이 되는 과정이에요.","오래 걸려요.","바로 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#19','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C10',3,'mc','auto','별무리반 일지 ⑥에서 가장 먼저 쌓인 층과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X12','SC5-1-u1-X13']::text[],false,'{"seq":19,"concept":"SC5-1-u1-C10","difficulty":3,"kind":"mc","stem":"별무리반 일지 ⑥에서 가장 먼저 쌓인 층과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"아래층 — 아래에 있는 층이 위층보다 먼저 쌓였기 때문에","correct":true},{"t":"위층 — 화석이 더 많기 때문에","mis":"SC5-1-u1-X12"},{"t":"가운데층 — 화석이 없기 때문에","mis":"SC5-1-u1-X12"},{"t":"알 수 없다 — 층은 한꺼번에 생기기 때문에","mis":"SC5-1-u1-X13"}],"explanation":["층의 자리를 봐요.","아래가 먼저예요.","아래층이에요."],"asset":{"type":"passage","lines":["아래층 — 가지처럼 뻗은 산호 화석이 나왔다.","가운데층 — 화석을 찾지 못했다.","위층 — 갈라진 잎 모양의 고사리 화석이 나왔다.","위층 바위 — 커다란 공룡 발자국이 여러 개 찍혀 있고 발자국 사이 간격이 넓다."],"title":"별무리반 일지 ⑥ 언덕 지층의 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#20','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C20',3,'mc','auto','땅속 깊이 있던 화석을 우리가 바닷가 절벽에서 볼 수 있게 된 까닭은 어느 것인가요?',ARRAY['SC5-1-u1-X34']::text[],false,'{"seq":20,"concept":"SC5-1-u1-C20","difficulty":3,"kind":"mc","stem":"땅속 깊이 있던 화석을 우리가 바닷가 절벽에서 볼 수 있게 된 까닭은 어느 것인가요?","options":[{"t":"지층이 물 밖으로 드러나 깎이면서 화석이 드러났기 때문에","correct":true},{"t":"화석이 스스로 위로 올라왔기 때문에","mis":"SC5-1-u1-X34"},{"t":"사람이 화석을 절벽에 붙였기 때문에","mis":"SC5-1-u1-X34"},{"t":"화석은 처음부터 땅 위에 만들어지기 때문에","mis":"SC5-1-u1-X34"}],"explanation":["지층이 어떻게 되나요?","드러나 깎여요.","깎여서 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#21','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C19',3,'mc','auto','화석 모형에서 석고를 쓰는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X30','SC5-1-u1-X31']::text[],false,'{"seq":21,"concept":"SC5-1-u1-C19","difficulty":3,"kind":"mc","stem":"화석 모형에서 석고를 쓰는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"굳으면서 자국 모양을 그대로 남겨 지층이 굳는 것을 나타내기 위해","correct":true},{"t":"석고가 조개를 나타내기 때문에","mis":"SC5-1-u1-X30"},{"t":"석고를 날려 보기 위해","mis":"SC5-1-u1-X30"},{"t":"실제 화석도 석고로 만들어지기 때문에","mis":"SC5-1-u1-X31"}],"explanation":["석고는 굳어요.","모양을 남겨요.","지층이 굳는 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#22','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C25',3,'mc','auto','우리나라 관광 지도에 「여러 겹으로 쌓인 바닷가 지층」을 넣으려면 어느 곳을 고르는 것이 알맞은가요?',ARRAY['SC5-1-u1-X41','SC5-1-u1-X42']::text[],false,'{"seq":22,"concept":"SC5-1-u1-C25","difficulty":3,"kind":"mc","stem":"우리나라 관광 지도에 「여러 겹으로 쌓인 바닷가 지층」을 넣으려면 어느 곳을 고르는 것이 알맞은가요?","options":[{"t":"부안 채석강","correct":true},{"t":"화성 고정리","mis":"SC5-1-u1-X41"},{"t":"진주 가진리","mis":"SC5-1-u1-X41"},{"t":"우리나라에는 없다","mis":"SC5-1-u1-X42"}],"explanation":["지층을 볼 곳이에요.","여러 겹이에요.","채석강이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#23','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C13',4,'mc','auto','별무리반 일지 ③의 네 표본을 알갱이가 작은 것부터 바르게 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X19','SC5-1-u1-X20']::text[],false,'{"seq":23,"concept":"SC5-1-u1-C13","difficulty":4,"kind":"mc","stem":"별무리반 일지 ③의 네 표본을 알갱이가 작은 것부터 바르게 묶은 것은 어느 것인가요?","options":[{"t":"나·라 → 가 → 다","correct":true},{"t":"다 → 가 → 나·라","mis":"SC5-1-u1-X19"},{"t":"나 → 가 → 라 → 다","mis":"SC5-1-u1-X20"},{"t":"가 → 나·라 → 다","mis":"SC5-1-u1-X19"}],"explanation":["알갱이를 견줘요.","나와 라는 같아요.","이암·사암·역암 순이에요."],"asset":{"type":"passage","lines":["가 — 모래만 한 알갱이가 보이고 만지면 까끌까끌하다.","나 — 알갱이가 거의 보이지 않고 매끈하다. 어두운 회색이다.","다 — 콩알만 한 자갈이 박혀 울퉁불퉁하다.","라 — 알갱이가 거의 보이지 않고 매끈하다. 밝은 노란빛이다."],"title":"별무리반 일지 ③ 퇴적암 표본"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#24','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C13',4,'essay','teacher','별무리반 일지 ③의 네 표본을 이암·사암·역암으로 분류하고, 분류한 근거와 퇴적암이 만들어지는 과정을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u1-C13","difficulty":4,"kind":"essay","stem":"별무리반 일지 ③의 네 표본을 이암·사암·역암으로 분류하고, 분류한 근거와 퇴적암이 만들어지는 과정을 쓰세요.","answer_guide":{"answer":"예: 나와 라는 알갱이가 거의 보이지 않고 매끈하므로 이암, 가는 모래만 한 알갱이가 보이므로 사암, 다는 자갈이 박혀 있으므로 역암이다. 퇴적암은 색깔이 아니라 알갱이의 크기에 따라 분류한다. 퇴적암은 퇴적물이 쌓이고, 눌리면서 알갱이 사이가 좁아지고, 물에 녹은 물질이 알갱이를 엉겨 붙게 하여 오랜 시간에 걸쳐 만들어진다.","scoring_points":["네 표본을 바르게 분류했는가","알갱이 크기를 근거로 썼는가","퇴적암이 만들어지는 과정을 썼는가"]},"explanation":["알갱이를 읽어요.","셋으로 나눠요.","과정을 써요."],"asset":{"type":"passage","lines":["가 — 모래만 한 알갱이가 보이고 만지면 까끌까끌하다.","나 — 알갱이가 거의 보이지 않고 매끈하다. 어두운 회색이다.","다 — 콩알만 한 자갈이 박혀 울퉁불퉁하다.","라 — 알갱이가 거의 보이지 않고 매끈하다. 밝은 노란빛이다."],"title":"별무리반 일지 ③ 퇴적암 표본"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_b#25','sci',5,1,'u1','','g5_1_sci_u1_review_b','unit_review','SC5-1-u1-C13',4,'essay','teacher','별무리반 일지 ⑦의 다빈과 이준의 말이 왜 옳지 않은지 바로잡아 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u1-C13","difficulty":4,"kind":"essay","stem":"별무리반 일지 ⑦의 다빈과 이준의 말이 왜 옳지 않은지 바로잡아 쓰세요.","answer_guide":{"answer":"예: 다빈아, 역암은 자갈에 모래나 진흙이 섞여 있어서 알갱이가 가장 커. 알갱이가 가장 작은 것은 진흙으로 이루어진 이암이야. 이준아, 화석은 옛 생물과 과거 환경을 알려 주는 소중한 자료라서 가져가면 안 돼. 그 자리에 소중히 보전해야 다른 사람도 보고 연구할 수 있어.","scoring_points":["다빈의 말을 알갱이 크기로 바로잡았는가","이준의 말을 화석의 가치·보전으로 바로잡았는가","근거를 들어 설명했는가"]},"explanation":["다빈부터 따져요.","이준은 화석의 가치예요.","근거를 들어요."],"asset":{"type":"passage","lines":["라온 — 「땅속에서 나온 것은 다 화석이야.」","다빈 — 「역암은 알갱이가 가장 작아.」","이준 — 「멋진 화석은 기념으로 집에 가져가도 돼.」","소이 — 「지층에서는 맨 위 층이 가장 먼저 쌓였어.」"],"title":"별무리반 일지 ⑦ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#1','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C5',1,'ox','auto','별무리반 일지 ①의 네 층은 두께와 색깔이 모두 같아요.',ARRAY['SC5-1-u1-X06']::text[],false,'{"seq":1,"concept":"SC5-1-u1-C5","difficulty":1,"kind":"ox","stem":"별무리반 일지 ①의 네 층은 두께와 색깔이 모두 같아요.","answer":"X","reason_options":[{"t":"두꺼운 자갈층과 얇은 진흙층, 밝은 층과 어두운 층이 있기 때문에","correct":true},{"t":"한 절벽의 층은 언제나 똑같기 때문에","mis":"SC5-1-u1-X06"}],"mis":"SC5-1-u1-X06","explanation":["기록을 견줘요.","두께와 색이 달라요.","모두 같지 않아요."],"asset":{"type":"passage","lines":["맨 아래 — 자갈층. 네 층 가운데 가장 두껍다.","그 위 — 모래층. 밝은 노란빛이다.","그 위 — 진흙층. 얇고 어두운 회색이다. 조개 화석이 박혀 있다.","맨 위 — 모래층. 절벽 오른쪽 끝에서는 층이 물결처럼 구부러져 있다."],"title":"별무리반 일지 ① 바닷가 절벽 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#2','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C10',1,'ox','auto','별무리반 일지 ① 그림에서 맨 위 모래층은 가장 나중에 쌓인 층이에요.',ARRAY['SC5-1-u1-X17']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C10","difficulty":1,"kind":"ox","stem":"별무리반 일지 ① 그림에서 맨 위 모래층은 가장 나중에 쌓인 층이에요.","answer":"O","reason_options":[{"t":"위에 있는 층일수록 나중에 쌓였기 때문에","correct":true},{"t":"모래는 언제나 가장 나중에 쌓이기 때문에","mis":"SC5-1-u1-X17"}],"mis":"SC5-1-u1-X17","explanation":["층의 자리를 봐요.","맨 위예요.","맞는 말이에요."],"asset":{"type":"geo","items":[{"w":300,"h":164,"seg":[[[10,10],[290,10]],[[10,154],[290,154]],[[10,10],[10,154]],[[290,10],[290,154]],[[10,46],[290,46]],[[10,82],[290,82]],[[10,118],[290,118]]],"lab":[[[150,28],"모래층"],[[150,64],"진흙층"],[[150,100],"모래층"],[[150,136],"자갈층"]],"cap":"별무리반 일지 ① 바닷가 절벽 지층(위에서부터)"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#3','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C13',1,'mc','auto','별무리반 일지 ③의 표본을 분류할 때 살펴야 할 것은 어느 것인가요?',ARRAY['SC5-1-u1-X20','SC5-1-u1-X18']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C13","difficulty":1,"kind":"mc","stem":"별무리반 일지 ③의 표본을 분류할 때 살펴야 할 것은 어느 것인가요?","options":[{"t":"알갱이의 크기","correct":true},{"t":"색깔","mis":"SC5-1-u1-X20"},{"t":"무게","mis":"SC5-1-u1-X18"},{"t":"주운 곳","mis":"SC5-1-u1-X18"}],"explanation":["분류 기준이에요.","돋보기로 봐요.","알갱이 크기예요."],"asset":{"type":"passage","lines":["가 — 모래만 한 알갱이가 보이고 만지면 까끌까끌하다.","나 — 알갱이가 거의 보이지 않고 매끈하다. 어두운 회색이다.","다 — 콩알만 한 자갈이 박혀 울퉁불퉁하다.","라 — 알갱이가 거의 보이지 않고 매끈하다. 밝은 노란빛이다."],"title":"별무리반 일지 ③ 퇴적암 표본"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#4','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C16',1,'ox','auto','별무리반 일지 ④의 ⑤처럼 배설물이 굳은 것도 화석이에요.',ARRAY['SC5-1-u1-X25']::text[],false,'{"seq":4,"concept":"SC5-1-u1-C16","difficulty":1,"kind":"ox","stem":"별무리반 일지 ④의 ⑤처럼 배설물이 굳은 것도 화석이에요.","answer":"O","reason_options":[{"t":"생물이 남긴 흔적도 지층 속에 남으면 화석이 되기 때문에","correct":true},{"t":"배설물은 생물의 몸체이기 때문에","mis":"SC5-1-u1-X25"}],"mis":"SC5-1-u1-X25","explanation":["흔적도 화석일까요?","네, 흔적도 돼요.","맞는 말이에요."],"asset":{"type":"passage","lines":["① 물고기의 뼈와 지느러미가 보인다.","② 갈라진 잎 모양이 남은 고사리","③ 커다란 발가락 자국이 남은 공룡 발자국","④ 둥글게 말린 암모나이트","⑤ 동물의 배설물이 굳은 것","⑥ 돋보기로 보아야 겨우 보이는 아주 작은 화석"],"title":"별무리반 일지 ④ 박물관에서 본 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#5','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C19',1,'ox','auto','별무리반 일지 ⑤처럼 실제 화석도 20분쯤이면 만들어져요.',ARRAY['SC5-1-u1-X31']::text[],false,'{"seq":5,"concept":"SC5-1-u1-C19","difficulty":1,"kind":"ox","stem":"별무리반 일지 ⑤처럼 실제 화석도 20분쯤이면 만들어져요.","answer":"X","reason_options":[{"t":"실제 화석은 아주 오랜 시간에 걸쳐 만들어지기 때문에","correct":true},{"t":"석고가 없어서 실제 화석은 만들어지지 않기 때문에","mis":"SC5-1-u1-X31"}],"mis":"SC5-1-u1-X31","explanation":["모형과 실제를 견줘요.","실제는 오래 걸려요.","20분이 아니에요."],"asset":{"type":"passage","lines":["찰흙을 평평하게 펴고 소라 껍데기를 눌렀다가 떼어 냈다.","자국이 덮이도록 물을 붓고, 물 표면이 안 보일 만큼 석고 가루를 넣었다.","석고가 굳은 뒤 찰흙과 석고를 떼어 내니 석고에 소라 모양이 남았다.","모두 20분쯤 걸렸다."],"title":"별무리반 일지 ⑤ 소라 화석 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#6','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C22',1,'ox','auto','별무리반 일지 ⑥의 언덕은 옛날에도 지금과 같은 언덕이었어요.',ARRAY['SC5-1-u1-X37']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C22","difficulty":1,"kind":"ox","stem":"별무리반 일지 ⑥의 언덕은 옛날에도 지금과 같은 언덕이었어요.","answer":"X","reason_options":[{"t":"아래층의 산호 화석으로 옛날에는 바다였음을 알 수 있기 때문에","correct":true},{"t":"화석은 오늘날의 환경만 알려 주기 때문에","mis":"SC5-1-u1-X37"}],"mis":"SC5-1-u1-X37","explanation":["아래층 화석을 봐요.","산호예요.","옛날엔 바다였어요."],"asset":{"type":"passage","lines":["아래층 — 가지처럼 뻗은 산호 화석이 나왔다.","가운데층 — 화석을 찾지 못했다.","위층 — 갈라진 잎 모양의 고사리 화석이 나왔다.","위층 바위 — 커다란 공룡 발자국이 여러 개 찍혀 있고 발자국 사이 간격이 넓다."],"title":"별무리반 일지 ⑥ 언덕 지층의 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#7','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C25',1,'ox','auto','별무리반 일지 ⑧의 고성 상족암에서는 공룡 발자국 화석을 볼 수 있어요.',ARRAY['SC5-1-u1-X41']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C25","difficulty":1,"kind":"ox","stem":"별무리반 일지 ⑧의 고성 상족암에서는 공룡 발자국 화석을 볼 수 있어요.","answer":"O","reason_options":[{"t":"바닷가 바위에 공룡 발자국 화석이 남아 있는 곳이기 때문에","correct":true},{"t":"상족암은 공룡알 화석만 나오는 곳이기 때문에","mis":"SC5-1-u1-X41"}],"mis":"SC5-1-u1-X41","explanation":["계획을 읽어요.","발자국이에요.","맞는 말이에요."],"asset":{"type":"passage","lines":["주제 — 우리나라의 공룡 화석","넣을 곳 — 고성 상족암(공룡 발자국 화석), 화성 고정리(공룡알 화석)","더 알아볼 것 — 바닷속 지층은 음파로, 넓은 땅은 인공위성 사진으로 조사한다고 한다.","약속 — 출처 밝히기, 고운 말 댓글, 화석은 가져오지 않기"],"title":"별무리반 일지 ⑧ 관광 지도 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#8','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C3',1,'ox','auto','화석을 발굴할 때는 빠르기보다 조심스러움이 중요해요.',ARRAY['SC5-1-u1-X01']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C3","difficulty":1,"kind":"ox","stem":"화석을 발굴할 때는 빠르기보다 조심스러움이 중요해요.","answer":"O","reason_options":[{"t":"서두르면 화석이 깨져 정보를 잃을 수 있기 때문에","correct":true},{"t":"화석은 단단해서 절대 깨지지 않기 때문에","mis":"SC5-1-u1-X01"}],"mis":"SC5-1-u1-X01","explanation":["발굴 체험을 떠올려요.","조심조심 파요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#9','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C5',2,'match','auto','별무리반 일지 ①의 층과 관찰한 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SC5-1-u1-C5","difficulty":2,"kind":"match","stem":"별무리반 일지 ①의 층과 관찰한 모습을 알맞게 이으세요.","pairs":[{"l":"자갈층","r":"가장 두껍다"},{"l":"진흙층","r":"얇고 어둡다"},{"l":"그 위 모래층","r":"밝은 노란빛이다"}],"mis":"SC5-1-u1-X06","explanation":["기록을 하나씩 읽어요.","두께와 색이에요.","셋을 이어요."],"asset":{"type":"passage","lines":["맨 아래 — 자갈층. 네 층 가운데 가장 두껍다.","그 위 — 모래층. 밝은 노란빛이다.","그 위 — 진흙층. 얇고 어두운 회색이다. 조개 화석이 박혀 있다.","맨 위 — 모래층. 절벽 오른쪽 끝에서는 층이 물결처럼 구부러져 있다."],"title":"별무리반 일지 ① 바닷가 절벽 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#10','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C9',2,'match','auto','별무리반 일지 ②의 모형과 실제 자연을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u1-C9","difficulty":2,"kind":"match","stem":"별무리반 일지 ②의 모형과 실제 자연을 알맞게 이으세요.","pairs":[{"l":"부은 물","r":"자갈·모래·진흙을 운반하는 흐르는 물"},{"l":"사각 통의 바닥","r":"바다나 호수의 밑바닥"},{"l":"생긴 세 층","r":"쌓여 생긴 지층"}],"mis":"SC5-1-u1-X15","explanation":["모형을 실제와 견줘요.","물은 흐르는 물이에요.","바닥은 밑바닥이에요."],"asset":{"type":"passage","lines":["사각 통에 물을 조금 붓고, 잠기도록 물을 부은 재료를 차례로 부었다.","부은 차례 — 진흙 → 자갈과 모래 → 모래","5분쯤 지나자 세 층이 생겼다.","손가락으로 살짝 누르니 층이 쉽게 흩어졌다."],"title":"별무리반 일지 ② 우리 모둠 지층 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#11','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C14',2,'match','auto','퇴적암 관찰 차례와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SC5-1-u1-C14","difficulty":2,"kind":"match","stem":"퇴적암 관찰 차례와 하는 일을 알맞게 이으세요.","pairs":[{"l":"첫째","r":"번호 붙임딱지를 붙인다"},{"l":"둘째","r":"표면을 손으로 만져 본다"},{"l":"셋째","r":"돋보기로 알갱이를 본다"},{"l":"넷째","r":"크기별로 나눈다"}],"mis":"SC5-1-u1-X23","explanation":["번호부터 붙여요.","만지고 들여다봐요.","마지막에 나눠요."],"asset":{"type":"passage","lines":["가 — 모래만 한 알갱이가 보이고 만지면 까끌까끌하다.","나 — 알갱이가 거의 보이지 않고 매끈하다. 어두운 회색이다.","다 — 콩알만 한 자갈이 박혀 울퉁불퉁하다.","라 — 알갱이가 거의 보이지 않고 매끈하다. 밝은 노란빛이다."],"title":"별무리반 일지 ③ 퇴적암 표본"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#12','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C16',2,'match','auto','별무리반 일지 ④의 화석을 남은 것에 따라 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SC5-1-u1-C16","difficulty":2,"kind":"match","stem":"별무리반 일지 ④의 화석을 남은 것에 따라 알맞게 이으세요.","pairs":[{"l":"① 물고기","r":"뼈가 남은 몸체 화석"},{"l":"③ 공룡 발자국","r":"발가락 자국이 남은 흔적 화석"},{"l":"② 고사리","r":"잎 모양이 남은 식물 화석"}],"mis":"SC5-1-u1-X25","explanation":["몸체인지 흔적인지 봐요.","발자국은 흔적이에요.","셋을 이어요."],"asset":{"type":"passage","lines":["① 물고기의 뼈와 지느러미가 보인다.","② 갈라진 잎 모양이 남은 고사리","③ 커다란 발가락 자국이 남은 공룡 발자국","④ 둥글게 말린 암모나이트","⑤ 동물의 배설물이 굳은 것","⑥ 돋보기로 보아야 겨우 보이는 아주 작은 화석"],"title":"별무리반 일지 ④ 박물관에서 본 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#13','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C19',2,'match','auto','별무리반 일지 ⑤의 모형 과정과 실제를 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u1-C19","difficulty":2,"kind":"match","stem":"별무리반 일지 ⑤의 모형 과정과 실제를 알맞게 이으세요.","pairs":[{"l":"찰흙에 소라 껍데기를 눌렀다 뗀다","r":"생물의 흔적이 퇴적물에 남는다"},{"l":"석고가 굳는다","r":"퇴적물이 굳어 지층이 된다"},{"l":"찰흙과 석고를 떼어 낸다","r":"지층이 깎여 화석이 발견된다"}],"mis":"SC5-1-u1-X30","explanation":["차례대로 견줘요.","남고 굳고 발견돼요.","셋을 이어요."],"asset":{"type":"passage","lines":["찰흙을 평평하게 펴고 소라 껍데기를 눌렀다가 떼어 냈다.","자국이 덮이도록 물을 붓고, 물 표면이 안 보일 만큼 석고 가루를 넣었다.","석고가 굳은 뒤 찰흙과 석고를 떼어 내니 석고에 소라 모양이 남았다.","모두 20분쯤 걸렸다."],"title":"별무리반 일지 ⑤ 소라 화석 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#14','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C22',2,'match','auto','별무리반 일지 ⑥의 층과 알 수 있는 과거 환경을 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SC5-1-u1-C22","difficulty":2,"kind":"match","stem":"별무리반 일지 ⑥의 층과 알 수 있는 과거 환경을 알맞게 이으세요.","pairs":[{"l":"아래층","r":"따뜻하고 깊이가 얕은 바다"},{"l":"위층","r":"따뜻하고 습기가 많은 육지"},{"l":"위층 바위","r":"큰 공룡이 걸어 다닌 땅"}],"mis":"SC5-1-u1-X36","explanation":["나온 화석을 봐요.","산호·고사리·발자국이에요.","셋을 이어요."],"asset":{"type":"passage","lines":["아래층 — 가지처럼 뻗은 산호 화석이 나왔다.","가운데층 — 화석을 찾지 못했다.","위층 — 갈라진 잎 모양의 고사리 화석이 나왔다.","위층 바위 — 커다란 공룡 발자국이 여러 개 찍혀 있고 발자국 사이 간격이 넓다."],"title":"별무리반 일지 ⑥ 언덕 지층의 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#15','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C26',2,'match','auto','조사할 곳과 알맞은 방법을 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SC5-1-u1-C26","difficulty":2,"kind":"match","stem":"조사할 곳과 알맞은 방법을 이으세요.","pairs":[{"l":"바닷속 깊은 지층","r":"음파"},{"l":"아주 넓은 땅","r":"인공위성 사진"},{"l":"땅속 물질 그대로","r":"구멍을 파서 채집"}],"mis":"SC5-1-u1-X43","explanation":["곳마다 달라요.","깊은 바다는 소리예요.","셋을 이어요."],"asset":{"type":"passage","lines":["주제 — 우리나라의 공룡 화석","넣을 곳 — 고성 상족암(공룡 발자국 화석), 화성 고정리(공룡알 화석)","더 알아볼 것 — 바닷속 지층은 음파로, 넓은 땅은 인공위성 사진으로 조사한다고 한다.","약속 — 출처 밝히기, 고운 말 댓글, 화석은 가져오지 않기"],"title":"별무리반 일지 ⑧ 관광 지도 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#16','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C7',2,'match','auto','지층 카드에서 관찰한 것과 관찰 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"SC5-1-u1-C7","difficulty":2,"kind":"match","stem":"지층 카드에서 관찰한 것과 관찰 결과를 알맞게 이으세요.","pairs":[{"l":"모양","r":"수평이거나 휘어져 있다"},{"l":"두께","r":"두꺼운 층과 얇은 층이 있다"},{"l":"색깔","r":"밝은 층과 어두운 층이 있다"}],"mis":"SC5-1-u1-X10","explanation":["관찰한 것을 하나씩 봐요.","모양·두께·색깔이에요.","셋을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#17','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C23',3,'error','auto','별무리반 일지 ⑦에서 이준의 말을 바르게 고친 친구는 누구인가요?',ARRAY['SC5-1-u1-X39','SC5-1-u1-X38']::text[],false,'{"seq":17,"concept":"SC5-1-u1-C23","difficulty":3,"kind":"error","stem":"별무리반 일지 ⑦에서 이준의 말을 바르게 고친 친구는 누구인가요?","options":[{"t":"루아 — 「화석은 과거를 알려 주는 자료라 그 자리에 보전해야 해.」","correct":true,"mis_target":"SC5-1-u1-X39"},{"t":"정민 — 「작은 화석은 가져가도 돼.」","mis":"SC5-1-u1-X39"},{"t":"윤슬 — 「화석은 가치가 없으니 버려도 돼.」","mis":"SC5-1-u1-X38"}],"explanation":["화석의 가치예요.","소중한 자료예요.","루아가 바르게 고쳤어요."],"asset":{"type":"passage","lines":["라온 — 「땅속에서 나온 것은 다 화석이야.」","다빈 — 「역암은 알갱이가 가장 작아.」","이준 — 「멋진 화석은 기념으로 집에 가져가도 돼.」","소이 — 「지층에서는 맨 위 층이 가장 먼저 쌓였어.」"],"title":"별무리반 일지 ⑦ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#18','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C22',3,'ox','auto','같은 곳에서 아래층은 바다 생물 화석, 위층은 육지 식물 화석이 나왔다면 그곳은 바다였다가 육지가 되었을 수 있어요.',ARRAY['SC5-1-u1-X12']::text[],false,'{"seq":18,"concept":"SC5-1-u1-C22","difficulty":3,"kind":"ox","stem":"같은 곳에서 아래층은 바다 생물 화석, 위층은 육지 식물 화석이 나왔다면 그곳은 바다였다가 육지가 되었을 수 있어요.","answer":"O","reason_options":[{"t":"아래층이 먼저 쌓였고 화석마다 알려 주는 환경이 다르기 때문에","correct":true},{"t":"위층이 먼저 쌓였기 때문에","mis":"SC5-1-u1-X12"}],"mis":"SC5-1-u1-X12","explanation":["아래가 먼저예요.","바다 다음 육지예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#19','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C21',3,'mc','auto','별무리반 일지 ⑥의 위층 바위에 발자국이 남은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X44','SC5-1-u1-X36']::text[],false,'{"seq":19,"concept":"SC5-1-u1-C21","difficulty":3,"kind":"mc","stem":"별무리반 일지 ⑥의 위층 바위에 발자국이 남은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"공룡이 무른 땅을 걸은 뒤 그 위로 퇴적물이 빠르게 쌓여 굳어졌다","correct":true},{"t":"공룡이 단단한 바위를 힘껏 밟았다","mis":"SC5-1-u1-X44"},{"t":"사람이 나중에 바위에 새겼다","mis":"SC5-1-u1-X44"},{"t":"바다였을 때 산호가 남긴 자국이다","mis":"SC5-1-u1-X36"}],"explanation":["발자국이 남는 과정이에요.","무른 땅이었어요.","덮이고 굳었어요."],"asset":{"type":"passage","lines":["아래층 — 가지처럼 뻗은 산호 화석이 나왔다.","가운데층 — 화석을 찾지 못했다.","위층 — 갈라진 잎 모양의 고사리 화석이 나왔다.","위층 바위 — 커다란 공룡 발자국이 여러 개 찍혀 있고 발자국 사이 간격이 넓다."],"title":"별무리반 일지 ⑥ 언덕 지층의 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#20','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C20',3,'mc','auto','화석이 만들어지는 데 꼭 필요한 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X30','SC5-1-u1-X32','SC5-1-u1-X31']::text[],false,'{"seq":20,"concept":"SC5-1-u1-C20","difficulty":3,"kind":"mc","stem":"화석이 만들어지는 데 꼭 필요한 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"생물의 몸체나 흔적 위로 퇴적물이 빠르게 쌓이는 일","correct":true},{"t":"생물이 불에 타는 일","mis":"SC5-1-u1-X30"},{"t":"생물이 오랫동안 공기 중에 놓여 있는 일","mis":"SC5-1-u1-X32"},{"t":"생물이 며칠 만에 돌로 바뀌는 일","mis":"SC5-1-u1-X31"}],"explanation":["빠르게 덮여야 해요.","퇴적물이 덮어요.","빠르게 쌓이는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#21','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C11',3,'mc','auto','지층 모형을 손가락으로 누르면 쉽게 흩어지는데 실제 지층은 단단한 까닭은 어느 것인가요?',ARRAY['SC5-1-u1-X14','SC5-1-u1-X13']::text[],false,'{"seq":21,"concept":"SC5-1-u1-C11","difficulty":3,"kind":"mc","stem":"지층 모형을 손가락으로 누르면 쉽게 흩어지는데 실제 지층은 단단한 까닭은 어느 것인가요?","options":[{"t":"실제 지층은 오랜 시간 눌리고 굳어졌기 때문에","correct":true},{"t":"실제 지층은 불에 구워졌기 때문에","mis":"SC5-1-u1-X14"},{"t":"실제 지층은 얼어 있기 때문에","mis":"SC5-1-u1-X14"},{"t":"실제 지층도 사실 쉽게 흩어지기 때문에","mis":"SC5-1-u1-X13"}],"explanation":["모형과 실제를 견줘요.","오래 눌렸어요.","굳어졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#22','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C24',3,'mc','auto','관광 지도를 나눌 때 가장 알맞은 댓글은 어느 것인가요?',ARRAY['SC5-1-u1-X40']::text[],false,'{"seq":22,"concept":"SC5-1-u1-C24","difficulty":3,"kind":"mc","stem":"관광 지도를 나눌 때 가장 알맞은 댓글은 어느 것인가요?","options":[{"t":"「상족암 사진과 설명이 자세해서 가 보고 싶어요. 발자국 크기도 알려 주면 좋겠어요.」","correct":true},{"t":"「별로네요. 다시 하세요.」","mis":"SC5-1-u1-X40"},{"t":"「ㅋㅋㅋ 아무거나 올렸네」","mis":"SC5-1-u1-X40"},{"t":"「우리 모둠이 훨씬 잘했어요.」","mis":"SC5-1-u1-X40"}],"explanation":["칭찬과 궁금한 점이에요.","고운 말이에요.","첫 번째 댓글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#23','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C16',4,'mc','auto','별무리반 일지 ④를 보고 「화석」을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SC5-1-u1-X26','SC5-1-u1-X25','SC5-1-u1-X04']::text[],false,'{"seq":23,"concept":"SC5-1-u1-C16","difficulty":4,"kind":"mc","stem":"별무리반 일지 ④를 보고 「화석」을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"옛 생물의 몸체나 흔적이 지층 속에 남은 것으로, 동물·식물·흔적 화석이 있고 크기도 다양하다","correct":true},{"t":"큰 동물의 뼈만 화석이다","mis":"SC5-1-u1-X26"},{"t":"식물과 흔적은 화석이 아니다","mis":"SC5-1-u1-X25"},{"t":"땅속에서 나온 모든 것이 화석이다","mis":"SC5-1-u1-X04"}],"explanation":["여섯 화석을 떠올려요.","몸체와 흔적, 크기가 달라요.","다양해요."],"asset":{"type":"passage","lines":["① 물고기의 뼈와 지느러미가 보인다.","② 갈라진 잎 모양이 남은 고사리","③ 커다란 발가락 자국이 남은 공룡 발자국","④ 둥글게 말린 암모나이트","⑤ 동물의 배설물이 굳은 것","⑥ 돋보기로 보아야 겨우 보이는 아주 작은 화석"],"title":"별무리반 일지 ④ 박물관에서 본 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#24','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C20',4,'essay','teacher','별무리반 일지 ⑤의 소라 화석 모형을 실제 화석이 만들어지는 과정과 짝지어 설명하고, 실제 화석이 되기 위한 조건 두 가지를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u1-C20","difficulty":4,"kind":"essay","stem":"별무리반 일지 ⑤의 소라 화석 모형을 실제 화석이 만들어지는 과정과 짝지어 설명하고, 실제 화석이 되기 위한 조건 두 가지를 쓰세요.","answer_guide":{"answer":"예: 찰흙에 소라 껍데기를 눌렀다 뗀 것은 생물의 흔적이 퇴적물에 남은 것과 같다. 물과 석고 가루를 부은 것은 그 위로 퇴적물이 쌓인 것이고, 석고가 굳은 것은 퇴적물이 굳어 지층이 된 것과 같다. 찰흙과 석고를 떼어 낸 것은 지층이 깎여 화석이 발견되는 것과 같다. 실제 화석이 되려면 퇴적물이 빠르게 쌓여야 하고, 단단하거나 질긴 부분이 있으면 화석이 되기 쉽다. 실제로는 20분이 아니라 아주 오랜 시간이 걸린다.","scoring_points":["모형 과정을 실제와 짝지었는가","조건 두 가지를 썼는가","시간의 차이를 썼는가"]},"explanation":["모형을 차례로 떠올려요.","실제와 짝지어요.","조건을 써요."],"asset":{"type":"passage","lines":["찰흙을 평평하게 펴고 소라 껍데기를 눌렀다가 떼어 냈다.","자국이 덮이도록 물을 붓고, 물 표면이 안 보일 만큼 석고 가루를 넣었다.","석고가 굳은 뒤 찰흙과 석고를 떼어 내니 석고에 소라 모양이 남았다.","모두 20분쯤 걸렸다."],"title":"별무리반 일지 ⑤ 소라 화석 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_c#25','sci',5,1,'u1','','g5_1_sci_u1_review_c','unit_review','SC5-1-u1-C24',4,'essay','teacher','별무리반 일지 ⑧의 관광 지도 계획에 넣을 소개 글을 두 곳에 대해 쓰고, 땅속을 조사하는 방법 두 가지와 지층을 연구하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u1-C24","difficulty":4,"kind":"essay","stem":"별무리반 일지 ⑧의 관광 지도 계획에 넣을 소개 글을 두 곳에 대해 쓰고, 땅속을 조사하는 방법 두 가지와 지층을 연구하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 경상남도 고성군 상족암에 가면 바닷가 바위에 찍힌 공룡 발자국 화석을 볼 수 있어요. 경기도 화성시 고정리에서는 여러 개가 모여 있는 공룡알 화석을 볼 수 있어요. 바닷속 지층은 음파로 구조를 알아내고, 넓은 땅은 인공위성이 찍은 화면으로 살펴볼 수 있다. 지구의 과거 모습을 이해하고 지속가능한 지구를 만들기 위해 지층을 조사하고 연구한다.","scoring_points":["두 곳의 소개 글을 바르게 썼는가","조사 방법 두 가지를 썼는가","연구하는 까닭을 썼는가"]},"explanation":["계획을 읽어요.","두 곳을 소개해요.","방법과 까닭을 써요."],"asset":{"type":"passage","lines":["주제 — 우리나라의 공룡 화석","넣을 곳 — 고성 상족암(공룡 발자국 화석), 화성 고정리(공룡알 화석)","더 알아볼 것 — 바닷속 지층은 음파로, 넓은 땅은 인공위성 사진으로 조사한다고 한다.","약속 — 출처 밝히기, 고운 말 댓글, 화석은 가져오지 않기"],"title":"별무리반 일지 ⑧ 관광 지도 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#1','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C5',1,'mc','auto','별무리반 일지 ① 그림에서 볼 수 있는 지층의 특징은 어느 것인가요?',ARRAY['SC5-1-u1-X06','SC5-1-u1-X07','SC5-1-u1-X05']::text[],false,'{"seq":1,"concept":"SC5-1-u1-C5","difficulty":1,"kind":"mc","stem":"별무리반 일지 ① 그림에서 볼 수 있는 지층의 특징은 어느 것인가요?","options":[{"t":"여러 층으로 이루어져 줄무늬가 보인다","correct":true},{"t":"층이 하나뿐이다","mis":"SC5-1-u1-X06"},{"t":"사람이 색을 칠한 줄이 보인다","mis":"SC5-1-u1-X07"},{"t":"뜨거운 물질이 굳어 생겼다","mis":"SC5-1-u1-X05"}],"explanation":["그림을 봐요.","층이 여럿이에요.","줄무늬가 보여요."],"asset":{"type":"geo","items":[{"w":300,"h":164,"seg":[[[10,10],[290,10]],[[10,154],[290,154]],[[10,10],[10,154]],[[290,10],[290,154]],[[10,46],[290,46]],[[10,82],[290,82]],[[10,118],[290,118]]],"lab":[[[150,28],"모래층"],[[150,64],"진흙층"],[[150,100],"모래층"],[[150,136],"자갈층"]],"cap":"별무리반 일지 ① 바닷가 절벽 지층(위에서부터)"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#2','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C10',1,'mc','auto','별무리반 일지 ②의 모형에서 맨 위에 쌓인 층은 어느 것인가요?',ARRAY['SC5-1-u1-X12','SC5-1-u1-X11']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C10","difficulty":1,"kind":"mc","stem":"별무리반 일지 ②의 모형에서 맨 위에 쌓인 층은 어느 것인가요?","options":[{"t":"모래층","correct":true},{"t":"진흙층","mis":"SC5-1-u1-X12"},{"t":"자갈과 모래층","mis":"SC5-1-u1-X12"},{"t":"층이 생기지 않았다","mis":"SC5-1-u1-X11"}],"explanation":["마지막에 부은 것이에요.","나중이 위예요.","모래층이에요."],"asset":{"type":"passage","lines":["사각 통에 물을 조금 붓고, 잠기도록 물을 부은 재료를 차례로 부었다.","부은 차례 — 진흙 → 자갈과 모래 → 모래","5분쯤 지나자 세 층이 생겼다.","손가락으로 살짝 누르니 층이 쉽게 흩어졌다."],"title":"별무리반 일지 ② 우리 모둠 지층 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#3','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C13',1,'ox','auto','별무리반 일지 ③의 나는 알갱이가 거의 보이지 않으니 이암이에요.',ARRAY['SC5-1-u1-X20']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C13","difficulty":1,"kind":"ox","stem":"별무리반 일지 ③의 나는 알갱이가 거의 보이지 않으니 이암이에요.","answer":"O","reason_options":[{"t":"이암은 진흙처럼 알갱이가 매우 작기 때문에","correct":true},{"t":"이암은 색이 어두운 암석이기 때문에","mis":"SC5-1-u1-X20"}],"mis":"SC5-1-u1-X20","explanation":["알갱이를 봐요.","아주 작아요.","맞는 말이에요."],"asset":{"type":"passage","lines":["가 — 모래만 한 알갱이가 보이고 만지면 까끌까끌하다.","나 — 알갱이가 거의 보이지 않고 매끈하다. 어두운 회색이다.","다 — 콩알만 한 자갈이 박혀 울퉁불퉁하다.","라 — 알갱이가 거의 보이지 않고 매끈하다. 밝은 노란빛이다."],"title":"별무리반 일지 ③ 퇴적암 표본"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#4','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C17',1,'mc','auto','별무리반 일지 ④의 ⑥으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u1-X26','SC5-1-u1-X25']::text[],false,'{"seq":4,"concept":"SC5-1-u1-C17","difficulty":1,"kind":"mc","stem":"별무리반 일지 ④의 ⑥으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"맨눈으로 보기 어려울 만큼 작은 화석도 있다","correct":true},{"t":"화석은 모두 크다","mis":"SC5-1-u1-X26"},{"t":"작은 것은 화석이 아니다","mis":"SC5-1-u1-X26"},{"t":"돋보기로 보는 것은 모두 흔적 화석이다","mis":"SC5-1-u1-X25"}],"explanation":["크기를 봐요.","아주 작아요.","작은 화석도 있어요."],"asset":{"type":"passage","lines":["① 물고기의 뼈와 지느러미가 보인다.","② 갈라진 잎 모양이 남은 고사리","③ 커다란 발가락 자국이 남은 공룡 발자국","④ 둥글게 말린 암모나이트","⑤ 동물의 배설물이 굳은 것","⑥ 돋보기로 보아야 겨우 보이는 아주 작은 화석"],"title":"별무리반 일지 ④ 박물관에서 본 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#5','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C19',1,'mc','auto','별무리반 일지 ⑤에서 굳은 석고 속 소라 모양은 실제의 무엇에 해당하나요?',ARRAY['SC5-1-u1-X30','SC5-1-u1-X34']::text[],false,'{"seq":5,"concept":"SC5-1-u1-C19","difficulty":1,"kind":"mc","stem":"별무리반 일지 ⑤에서 굳은 석고 속 소라 모양은 실제의 무엇에 해당하나요?","options":[{"t":"지층 속에 만들어진 화석","correct":true},{"t":"바다에 사는 소라","mis":"SC5-1-u1-X30"},{"t":"퇴적물이 쌓이는 곳","mis":"SC5-1-u1-X30"},{"t":"지층을 깎는 물","mis":"SC5-1-u1-X34"}],"explanation":["석고 속에 남았어요.","지층 속에 남은 것이에요.","화석이에요."],"asset":{"type":"passage","lines":["찰흙을 평평하게 펴고 소라 껍데기를 눌렀다가 떼어 냈다.","자국이 덮이도록 물을 붓고, 물 표면이 안 보일 만큼 석고 가루를 넣었다.","석고가 굳은 뒤 찰흙과 석고를 떼어 내니 석고에 소라 모양이 남았다.","모두 20분쯤 걸렸다."],"title":"별무리반 일지 ⑤ 소라 화석 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#6','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C22',1,'mc','auto','별무리반 일지 ⑥의 화석으로 과거 환경을 알아내는 방법은 어느 것인가요?',ARRAY['SC5-1-u1-X37']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C22","difficulty":1,"kind":"mc","stem":"별무리반 일지 ⑥의 화석으로 과거 환경을 알아내는 방법은 어느 것인가요?","options":[{"t":"오늘날 비슷한 생물이 사는 곳과 견주어 본다","correct":true},{"t":"화석의 색을 비교한다","mis":"SC5-1-u1-X37"},{"t":"화석의 무게를 잰다","mis":"SC5-1-u1-X37"},{"t":"오늘날의 날씨를 그대로 옛날 날씨로 본다","mis":"SC5-1-u1-X37"}],"explanation":["오늘날 생물과 견줘요.","사는 곳을 살펴요.","견주어 봐요."],"asset":{"type":"passage","lines":["아래층 — 가지처럼 뻗은 산호 화석이 나왔다.","가운데층 — 화석을 찾지 못했다.","위층 — 갈라진 잎 모양의 고사리 화석이 나왔다.","위층 바위 — 커다란 공룡 발자국이 여러 개 찍혀 있고 발자국 사이 간격이 넓다."],"title":"별무리반 일지 ⑥ 언덕 지층의 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#7','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C26',1,'mc','auto','별무리반 일지 ⑧에서 넓은 땅을 살피는 데 쓴다고 한 것은 어느 것인가요?',ARRAY['SC5-1-u1-X43']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C26","difficulty":1,"kind":"mc","stem":"별무리반 일지 ⑧에서 넓은 땅을 살피는 데 쓴다고 한 것은 어느 것인가요?","options":[{"t":"인공위성 사진","correct":true},{"t":"돋보기","mis":"SC5-1-u1-X43"},{"t":"삽으로 판 구멍","mis":"SC5-1-u1-X43"},{"t":"줄자","mis":"SC5-1-u1-X43"}],"explanation":["넓은 범위예요.","하늘 위에서 찍어요.","인공위성 사진이에요."],"asset":{"type":"passage","lines":["주제 — 우리나라의 공룡 화석","넣을 곳 — 고성 상족암(공룡 발자국 화석), 화성 고정리(공룡알 화석)","더 알아볼 것 — 바닷속 지층은 음파로, 넓은 땅은 인공위성 사진으로 조사한다고 한다.","약속 — 출처 밝히기, 고운 말 댓글, 화석은 가져오지 않기"],"title":"별무리반 일지 ⑧ 관광 지도 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#8','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C23',1,'mc','auto','화석 산지에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X38','SC5-1-u1-X39']::text[],false,'{"seq":8,"concept":"SC5-1-u1-C23","difficulty":1,"kind":"mc","stem":"화석 산지에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"화석이 많이 발견되는 곳이다","correct":true},{"t":"화석을 만들어 파는 가게이다","mis":"SC5-1-u1-X38"},{"t":"화석을 마음껏 가져갈 수 있는 곳이다","mis":"SC5-1-u1-X39"},{"t":"화석이 하나도 없는 곳이다","mis":"SC5-1-u1-X38"}],"explanation":["이름을 풀어 봐요.","화석이 나오는 땅이에요.","많이 발견되는 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#9','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C6',2,'ox','auto','한 절벽 안에서도 층이 평평한 곳과 구부러진 곳이 함께 보일 수 있어요.',ARRAY['SC5-1-u1-X08']::text[],false,'{"seq":9,"concept":"SC5-1-u1-C6","difficulty":2,"kind":"ox","stem":"한 절벽 안에서도 층이 평평한 곳과 구부러진 곳이 함께 보일 수 있어요.","answer":"O","reason_options":[{"t":"지층의 모양은 다양해서 한 곳에서도 여러 모양이 나타날 수 있기 때문에","correct":true},{"t":"지층은 언제나 수평이라 구부러진 곳은 지층이 아니기 때문에","mis":"SC5-1-u1-X08"}],"mis":"SC5-1-u1-X08","explanation":["일지 ①을 떠올려요.","오른쪽 끝이 구부러졌어요.","맞는 말이에요."],"asset":{"type":"passage","lines":["맨 아래 — 자갈층. 네 층 가운데 가장 두껍다.","그 위 — 모래층. 밝은 노란빛이다.","그 위 — 진흙층. 얇고 어두운 회색이다. 조개 화석이 박혀 있다.","맨 위 — 모래층. 절벽 오른쪽 끝에서는 층이 물결처럼 구부러져 있다."],"title":"별무리반 일지 ① 바닷가 절벽 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#10','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C9',2,'ox','auto','별무리반 일지 ②처럼 실제 지층도 진흙이 언제나 맨 아래에 쌓여요.',ARRAY['SC5-1-u1-X17']::text[],false,'{"seq":10,"concept":"SC5-1-u1-C9","difficulty":2,"kind":"ox","stem":"별무리반 일지 ②처럼 실제 지층도 진흙이 언제나 맨 아래에 쌓여요.","answer":"X","reason_options":[{"t":"쌓이는 재료와 차례는 그때그때 다르기 때문에","correct":true},{"t":"진흙은 무거워 언제나 맨 아래로 가기 때문에","mis":"SC5-1-u1-X17"}],"mis":"SC5-1-u1-X17","explanation":["일지 ①을 떠올려요.","맨 아래가 자갈이었어요.","언제나 같지 않아요."],"asset":{"type":"passage","lines":["사각 통에 물을 조금 붓고, 잠기도록 물을 부은 재료를 차례로 부었다.","부은 차례 — 진흙 → 자갈과 모래 → 모래","5분쯤 지나자 세 층이 생겼다.","손가락으로 살짝 누르니 층이 쉽게 흩어졌다."],"title":"별무리반 일지 ② 우리 모둠 지층 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#11','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C15',2,'ox','auto','별무리반 일지 ③의 가는 모래가 쌓여 눌리고 엉겨 붙어 굳어진 암석이에요.',ARRAY['SC5-1-u1-X22']::text[],false,'{"seq":11,"concept":"SC5-1-u1-C15","difficulty":2,"kind":"ox","stem":"별무리반 일지 ③의 가는 모래가 쌓여 눌리고 엉겨 붙어 굳어진 암석이에요.","answer":"O","reason_options":[{"t":"사암은 모래가 오랜 시간 눌리고 엉겨 붙어 만들어지기 때문에","correct":true},{"t":"모래를 손으로 세게 쥐면 바로 사암이 되기 때문에","mis":"SC5-1-u1-X22"}],"mis":"SC5-1-u1-X22","explanation":["가는 사암이에요.","모래가 굳었어요.","맞는 말이에요."],"asset":{"type":"passage","lines":["가 — 모래만 한 알갱이가 보이고 만지면 까끌까끌하다.","나 — 알갱이가 거의 보이지 않고 매끈하다. 어두운 회색이다.","다 — 콩알만 한 자갈이 박혀 울퉁불퉁하다.","라 — 알갱이가 거의 보이지 않고 매끈하다. 밝은 노란빛이다."],"title":"별무리반 일지 ③ 퇴적암 표본"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#12','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C18',2,'ox','auto','별무리반 일지 ④의 화석은 뜨거운 것이 식어 굳은 암석에서 주로 나와요.',ARRAY['SC5-1-u1-X29']::text[],false,'{"seq":12,"concept":"SC5-1-u1-C18","difficulty":2,"kind":"ox","stem":"별무리반 일지 ④의 화석은 뜨거운 것이 식어 굳은 암석에서 주로 나와요.","answer":"X","reason_options":[{"t":"화석은 퇴적물과 함께 생물이 묻혀 굳은 퇴적암에서 주로 나오기 때문에","correct":true},{"t":"화석은 뜨거운 곳에서만 만들어지기 때문에","mis":"SC5-1-u1-X29"}],"mis":"SC5-1-u1-X29","explanation":["화석이 묻히는 과정이에요.","퇴적물과 함께예요.","퇴적암이에요."],"asset":{"type":"passage","lines":["① 물고기의 뼈와 지느러미가 보인다.","② 갈라진 잎 모양이 남은 고사리","③ 커다란 발가락 자국이 남은 공룡 발자국","④ 둥글게 말린 암모나이트","⑤ 동물의 배설물이 굳은 것","⑥ 돋보기로 보아야 겨우 보이는 아주 작은 화석"],"title":"별무리반 일지 ④ 박물관에서 본 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#13','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C20',2,'ox','auto','생물이 죽은 뒤 오랫동안 아무것도 덮이지 않아도 화석이 잘 만들어져요.',ARRAY['SC5-1-u1-X32']::text[],false,'{"seq":13,"concept":"SC5-1-u1-C20","difficulty":2,"kind":"ox","stem":"생물이 죽은 뒤 오랫동안 아무것도 덮이지 않아도 화석이 잘 만들어져요.","answer":"X","reason_options":[{"t":"퇴적물이 빠르게 덮여야 흔적이 그대로 남기 때문에","correct":true},{"t":"죽은 생물은 모두 화석이 되기 때문에","mis":"SC5-1-u1-X32"}],"mis":"SC5-1-u1-X32","explanation":["화석이 될 조건이에요.","빠르게 덮여야 해요.","잘 만들어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#14','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C21',2,'ox','auto','별무리반 일지 ⑥의 발자국 화석만으로 공룡이 태어난 날짜를 알 수 있어요.',ARRAY['SC5-1-u1-X35']::text[],false,'{"seq":14,"concept":"SC5-1-u1-C21","difficulty":2,"kind":"ox","stem":"별무리반 일지 ⑥의 발자국 화석만으로 공룡이 태어난 날짜를 알 수 있어요.","answer":"X","reason_options":[{"t":"발자국으로는 크기나 움직임 정도를 짐작할 수 있기 때문에","correct":true},{"t":"발자국에는 날짜가 새겨져 있기 때문에","mis":"SC5-1-u1-X35"}],"mis":"SC5-1-u1-X35","explanation":["발자국에 남은 것은?","크기와 간격이에요.","날짜는 알 수 없어요."],"asset":{"type":"passage","lines":["아래층 — 가지처럼 뻗은 산호 화석이 나왔다.","가운데층 — 화석을 찾지 못했다.","위층 — 갈라진 잎 모양의 고사리 화석이 나왔다.","위층 바위 — 커다란 공룡 발자국이 여러 개 찍혀 있고 발자국 사이 간격이 넓다."],"title":"별무리반 일지 ⑥ 언덕 지층의 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#15','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C24',2,'ox','auto','별무리반 일지 ⑧처럼 화석이 있는 곳에서도 화석은 가져오지 않아요.',ARRAY['SC5-1-u1-X39']::text[],false,'{"seq":15,"concept":"SC5-1-u1-C24","difficulty":2,"kind":"ox","stem":"별무리반 일지 ⑧처럼 화석이 있는 곳에서도 화석은 가져오지 않아요.","answer":"O","reason_options":[{"t":"지층과 화석은 과거를 알려 주는 자료라 소중히 보전해야 하기 때문에","correct":true},{"t":"화석은 무거워서 들고 오기 어렵기 때문에","mis":"SC5-1-u1-X39"}],"mis":"SC5-1-u1-X39","explanation":["약속을 읽어요.","보전해요.","맞는 말이에요."],"asset":{"type":"passage","lines":["주제 — 우리나라의 공룡 화석","넣을 곳 — 고성 상족암(공룡 발자국 화석), 화성 고정리(공룡알 화석)","더 알아볼 것 — 바닷속 지층은 음파로, 넓은 땅은 인공위성 사진으로 조사한다고 한다.","약속 — 출처 밝히기, 고운 말 댓글, 화석은 가져오지 않기"],"title":"별무리반 일지 ⑧ 관광 지도 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#16','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C1',2,'ox','auto','블록을 숨긴 다음 흙의 윗부분을 눌러 단단하게 하는 것은 땅속에 묻힌 것처럼 하기 위해서예요.',ARRAY['SC5-1-u1-X01']::text[],false,'{"seq":16,"concept":"SC5-1-u1-C1","difficulty":2,"kind":"ox","stem":"블록을 숨긴 다음 흙의 윗부분을 눌러 단단하게 하는 것은 땅속에 묻힌 것처럼 하기 위해서예요.","answer":"O","reason_options":[{"t":"겉에서 보이지 않게 단단히 묻혀 있는 모습을 흉내 내기 위해서이기 때문에","correct":true},{"t":"블록을 빨리 찾기 위해서이기 때문에","mis":"SC5-1-u1-X01"}],"mis":"SC5-1-u1-X01","explanation":["땅속을 흉내 내요.","겉에서 안 보여요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#17','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C10',3,'error','auto','별무리반 일지 ⑦에서 소이의 말을 바르게 고친 친구는 누구인가요?',ARRAY['SC5-1-u1-X12','SC5-1-u1-X13']::text[],false,'{"seq":17,"concept":"SC5-1-u1-C10","difficulty":3,"kind":"error","stem":"별무리반 일지 ⑦에서 소이의 말을 바르게 고친 친구는 누구인가요?","options":[{"t":"지율 — 「아래에 있는 층이 먼저 쌓였으니 맨 아래 층이 가장 오래됐어.」","correct":true,"mis_target":"SC5-1-u1-X12"},{"t":"한결 — 「가운데 층이 가장 먼저 쌓였어.」","mis":"SC5-1-u1-X12"},{"t":"소담 — 「층은 한꺼번에 생겨서 차례가 없어.」","mis":"SC5-1-u1-X13"}],"explanation":["돌탑을 떠올려요.","아래가 먼저예요.","지율이 바르게 고쳤어요."],"asset":{"type":"passage","lines":["라온 — 「땅속에서 나온 것은 다 화석이야.」","다빈 — 「역암은 알갱이가 가장 작아.」","이준 — 「멋진 화석은 기념으로 집에 가져가도 돼.」","소이 — 「지층에서는 맨 위 층이 가장 먼저 쌓였어.」"],"title":"별무리반 일지 ⑦ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#18','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C26',3,'ox','auto','땅속은 반드시 구멍을 파야만 조사할 수 있어요.',ARRAY['SC5-1-u1-X43']::text[],false,'{"seq":18,"concept":"SC5-1-u1-C26","difficulty":3,"kind":"ox","stem":"땅속은 반드시 구멍을 파야만 조사할 수 있어요.","answer":"X","reason_options":[{"t":"탄성파·음파·인공위성처럼 파지 않고 조사하는 방법도 있기 때문에","correct":true},{"t":"땅속에는 아무것도 없어 조사할 필요가 없기 때문에","mis":"SC5-1-u1-X43"}],"mis":"SC5-1-u1-X43","explanation":["과학이 톡톡을 떠올려요.","파지 않는 방법이 있어요.","반드시는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#19','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C22',3,'mc','auto','별무리반 일지 ⑥의 가운데층에서 화석을 찾지 못한 것에 대해 가장 알맞은 생각은 어느 것인가요?',ARRAY['SC5-1-u1-X05','SC5-1-u1-X37','SC5-1-u1-X12']::text[],false,'{"seq":19,"concept":"SC5-1-u1-C22","difficulty":3,"kind":"mc","stem":"별무리반 일지 ⑥의 가운데층에서 화석을 찾지 못한 것에 대해 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"화석이 남을 조건이 맞지 않았거나 아직 찾지 못했을 수 있다","correct":true},{"t":"가운데층은 지층이 아니다","mis":"SC5-1-u1-X05"},{"t":"가운데층이 쌓일 때는 생물이 하나도 없었다고 단정한다","mis":"SC5-1-u1-X37"},{"t":"화석이 없으니 가운데층이 가장 먼저 쌓였다","mis":"SC5-1-u1-X12"}],"explanation":["단정할 수 있을까요?","조건이 있어요.","아직 모를 수 있어요."],"asset":{"type":"passage","lines":["아래층 — 가지처럼 뻗은 산호 화석이 나왔다.","가운데층 — 화석을 찾지 못했다.","위층 — 갈라진 잎 모양의 고사리 화석이 나왔다.","위층 바위 — 커다란 공룡 발자국이 여러 개 찍혀 있고 발자국 사이 간격이 넓다."],"title":"별무리반 일지 ⑥ 언덕 지층의 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#20','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C20',3,'mc','auto','조개껍데기는 화석이 잘 되고 조개의 살은 잘 남지 않는 까닭은 어느 것인가요?',ARRAY['SC5-1-u1-X33','SC5-1-u1-X32','SC5-1-u1-X27']::text[],false,'{"seq":20,"concept":"SC5-1-u1-C20","difficulty":3,"kind":"mc","stem":"조개껍데기는 화석이 잘 되고 조개의 살은 잘 남지 않는 까닭은 어느 것인가요?","options":[{"t":"껍데기는 단단하고 살은 물렁해 금방 없어지기 때문에","correct":true},{"t":"살이 더 단단하기 때문에","mis":"SC5-1-u1-X33"},{"t":"껍데기는 퇴적물에 덮이지 않기 때문에","mis":"SC5-1-u1-X32"},{"t":"조개는 동물이 아니기 때문에","mis":"SC5-1-u1-X27"}],"explanation":["단단함을 견줘요.","껍데기가 단단해요.","살은 금방 없어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#21','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C19',3,'mc','auto','화석 모형의 「찰흙과 석고를 떼어 내어 관찰하는 일」과 같은 실제의 일은 어느 것인가요?',ARRAY['SC5-1-u1-X30','SC5-1-u1-X32']::text[],false,'{"seq":21,"concept":"SC5-1-u1-C19","difficulty":3,"kind":"mc","stem":"화석 모형의 「찰흙과 석고를 떼어 내어 관찰하는 일」과 같은 실제의 일은 어느 것인가요?","options":[{"t":"지층이 깎여 그 속의 화석이 드러나 발견되는 일","correct":true},{"t":"생물이 바다에 가라앉는 일","mis":"SC5-1-u1-X30"},{"t":"흔적 위로 퇴적물이 쌓이는 일","mis":"SC5-1-u1-X30"},{"t":"생물이 화석으로 바뀌지 않는 일","mis":"SC5-1-u1-X32"}],"explanation":["마지막 단계예요.","떼어 내 보여요.","깎여 발견돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#22','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C25',3,'mc','auto','우리나라에서 지층과 화석을 많이 볼 수 있는 곳에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u1-X42','SC5-1-u1-X41']::text[],false,'{"seq":22,"concept":"SC5-1-u1-C25","difficulty":3,"kind":"mc","stem":"우리나라에서 지층과 화석을 많이 볼 수 있는 곳에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"특히 바닷가에서 여러 모습의 지층과 공룡 발자국 화석이 많이 발견되었다","correct":true},{"t":"우리나라에서는 지층과 화석을 볼 수 없다","mis":"SC5-1-u1-X42"},{"t":"도시 한가운데에서 가장 많이 발견된다","mis":"SC5-1-u1-X42"},{"t":"공룡알 화석은 채석강에서만 나온다","mis":"SC5-1-u1-X41"}],"explanation":["관광 지도를 떠올려요.","바닷가예요.","많이 발견되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#23','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C22',4,'mc','auto','어느 높은 산의 지층에서 조개 화석이 나왔어요. 가장 알맞은 추리는 어느 것인가요?',ARRAY['SC5-1-u1-X37','SC5-1-u1-X38']::text[],false,'{"seq":23,"concept":"SC5-1-u1-C22","difficulty":4,"kind":"mc","stem":"어느 높은 산의 지층에서 조개 화석이 나왔어요. 가장 알맞은 추리는 어느 것인가요?","options":[{"t":"이 산의 지층이 쌓일 무렵 그곳은 바다였고, 그 뒤 땅이 드러나 지금의 산이 되었다","correct":true},{"t":"조개가 산을 기어 올라갔다","mis":"SC5-1-u1-X37"},{"t":"그곳은 옛날에도 지금처럼 산이었다","mis":"SC5-1-u1-X37"},{"t":"조개 화석은 과거 환경을 알려 주지 않는다","mis":"SC5-1-u1-X38"}],"explanation":["오늘날 조개가 사는 곳은?","바다예요.","옛날엔 바다였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#24','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C22',4,'essay','teacher','별무리반 일지 ⑥의 화석을 이용해 이 언덕의 과거 환경이 어떻게 바뀌었는지 차례대로 추리하고, 그렇게 추리한 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u1-C22","difficulty":4,"kind":"essay","stem":"별무리반 일지 ⑥의 화석을 이용해 이 언덕의 과거 환경이 어떻게 바뀌었는지 차례대로 추리하고, 그렇게 추리한 방법을 쓰세요.","answer_guide":{"answer":"예: 가장 먼저 쌓인 아래층에서 산호 화석이 나왔으므로 그때 이곳은 따뜻하고 깊이가 얕은 바다였다. 나중에 쌓인 위층에서는 고사리 화석이 나왔으므로 따뜻하고 습기가 많은 육지가 되었다. 위층 바위의 크고 간격이 넓은 공룡 발자국으로 그 육지에 몸집이 큰 공룡이 걸어 다녔음을 알 수 있다. 화석이 된 생물과 비슷한 오늘날의 생물이 사는 곳을 살펴 과거 환경을 추리했다.","scoring_points":["아래층이 먼저임을 이용했는가","바다에서 육지로 바뀐 것을 추리했는가","오늘날 생물과 견주는 방법을 썼는가"]},"explanation":["아래층부터 읽어요.","화석마다 환경을 떠올려요.","방법을 써요."],"asset":{"type":"passage","lines":["아래층 — 가지처럼 뻗은 산호 화석이 나왔다.","가운데층 — 화석을 찾지 못했다.","위층 — 갈라진 잎 모양의 고사리 화석이 나왔다.","위층 바위 — 커다란 공룡 발자국이 여러 개 찍혀 있고 발자국 사이 간격이 넓다."],"title":"별무리반 일지 ⑥ 언덕 지층의 화석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u1_review_d#25','sci',5,1,'u1','','g5_1_sci_u1_review_d','unit_review','SC5-1-u1-C23',4,'essay','teacher','「지층과 화석」 단원에서 배운 흐름을 「쌓이고 → 굳어지고 → 그 속에 남고 → 깎여서」의 차례로 설명하고, 화석이 우리에게 알려 주는 것 두 가지를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u1-C23","difficulty":4,"kind":"essay","stem":"「지층과 화석」 단원에서 배운 흐름을 「쌓이고 → 굳어지고 → 그 속에 남고 → 깎여서」의 차례로 설명하고, 화석이 우리에게 알려 주는 것 두 가지를 쓰세요.","answer_guide":{"answer":"예: 흐르는 물이 운반한 자갈·모래·진흙 같은 퇴적물이 바다나 호수 밑바닥에 쌓인다. 오랜 시간 눌리고 굳어져 퇴적암으로 된 지층이 만들어진다. 이때 퇴적물이 빠르게 덮은 생물의 몸체나 흔적이 그 속에 남아 화석이 된다. 지층이 땅 위로 드러나 깎이면서 우리가 지층과 화석을 볼 수 있다. 화석은 옛날에 살았던 생물의 생김새와 특징, 그리고 그 지역의 과거 환경을 알려 준다.","scoring_points":["네 단계를 차례대로 썼는가","퇴적암·화석과 이어 설명했는가","화석이 알려 주는 것 두 가지를 썼는가"]},"explanation":["쌓이는 것부터 써요.","화석이 남는 때를 넣어요.","알려 주는 것을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
